/* ─────────────────────────────────────────────
   FONTS
   Uncut Sans Variable — self-hosted
   Inter — Google Fonts (loaded in index.html)
───────────────────────────────────────────── */
@font-face {
  font-family: "Uncut Sans";
  src: url("/fonts/UncutSans-Variable.woff2") format("woff2-variations");
  font-weight: 300 700;
  font-style: normal;
  /* optional, not swap: the font is preloaded (index.html) so it's normally
     ready in time, but if it isn't, never swap it in later — that swap is
     what was causing a real, measured CLS on headings once SSR made text
     visible from first paint instead of hiding it behind a loading spinner. */
  font-display: optional;
}

@tailwind base;
@tailwind components;
@tailwind utilities;

/* ─────────────────────────────────────────────
   HERO GRADIENT — light / dark variants
───────────────────────────────────────────── */
.hero-gradient {
  background:
    radial-gradient(ellipse 70% 60% at 52% 28%, rgba(255,255,255,0.92) 0%, transparent 62%),
    radial-gradient(ellipse 58% 52% at  2%  2%, hsl(214 72% 86% / 0.85) 0%, transparent 58%),
    radial-gradient(ellipse 52% 48% at 98% 95%, hsl(220 65% 87% / 0.80) 0%, transparent 55%),
    radial-gradient(ellipse 44% 40% at 10% 92%, hsl(210 60% 89% / 0.65) 0%, transparent 52%),
    radial-gradient(ellipse 40% 36% at 92%  8%, hsl(218 68% 88% / 0.70) 0%, transparent 50%),
    hsl(214 52% 93%);
}

.dark .hero-gradient {
  background:
    radial-gradient(ellipse 65% 55% at 50% 30%, hsl(224 50% 14% / 0.55) 0%, transparent 62%),
    radial-gradient(ellipse 55% 50% at  2%  2%, hsl(224 60% 18% / 0.65) 0%, transparent 56%),
    radial-gradient(ellipse 50% 46% at 98% 95%, hsl(220 55% 16% / 0.60) 0%, transparent 54%),
    radial-gradient(ellipse 42% 38% at 10% 92%, hsl(210 50% 14% / 0.50) 0%, transparent 50%),
    radial-gradient(ellipse 38% 34% at 92%  8%, hsl(218 55% 16% / 0.55) 0%, transparent 48%),
    hsl(var(--background));
}

/* ─────────────────────────────────────────────
   ANIMATIONS
───────────────────────────────────────────── */
@keyframes float {
  0%, 100% { transform: translateY(0px); }
  50%       { transform: translateY(-12px); }
}

@keyframes logo-reveal {
  0%   { opacity: 0; transform: scale(0.55) translateY(18px); }
  100% { opacity: 1; transform: scale(1)    translateY(0px);  }
}

/* Explorer panel enter / exit */
@keyframes panel-in {
  from { opacity: 0; transform: translateY(-6px); }
  to   { opacity: 1; transform: translateY(0);    }
}

@keyframes panel-out {
  from { opacity: 1; transform: translateY(0);    }
  to   { opacity: 0; transform: translateY(-4px); }
}

/* ─────────────────────────────────────────────
   DESIGN TOKENS
───────────────────────────────────────────── */
@layer base {
  :root {
    /* ────────────────────────────────────────────
       DESIGN TOKENS — Awwwards editorial palette
       ToolTrim blue is the ONLY accent colour.
    ──────────────────────────────────────────── */

    /* ── Page / surface ── */
    --background: 0 20% 99%;         /* #FDFCFC — soft near-white */
    --foreground: 240 3% 12%;        /* #1D1D1F — main text */

    --card: 0 0% 100%;               /* #FFFFFF — pure white cards */
    --card-foreground: 240 3% 12%;

    --popover: 0 0% 100%;
    --popover-foreground: 240 3% 12%;

    /* ── ToolTrim blue — sole accent, use sparingly ── */
    --primary: 224 76% 50%;          /* #1E4FCC — active, selected, links, rare CTAs */
    --primary-foreground: 0 0% 100%;

    /* ── Secondary / muted surfaces ── */
    --secondary: 60 15% 94%;         /* #F1F1EC — secondary surface */
    --secondary-foreground: 240 3% 12%;

    --muted: 60 15% 94%;             /* #F1F1EC */
    --muted-foreground: 240 3% 12%;  /* high-contrast secondary copy */

    /* ── Accent tint (blue, very light) ── */
    --accent: 224 76% 96%;           /* near-white blue tint */
    --accent-foreground: 224 76% 44%;

    /* ── Status ── */
    --destructive: 0 72% 51%;
    --destructive-foreground: 0 0% 100%;

    /* ── Borders ── */
    --border: 60 7% 84%;             /* #DADAD4 — standard */
    --input:  60 7% 84%;
    --ring:   224 76% 50%;           /* ToolTrim blue focus ring */

    /* ── Radius ── */
    /* ── Radius scale ──
       Seven steps, nothing between them. Before this, 19 distinct radii were
       in use (2,3,4,5,6,7,9,10,11,12,13,14,16,18,20,22,24,28px): nobody can
       tell 6px from 7px, so pick the nearest step — never a new value. */
    --radius-xs:   0.25rem;            /* 4px  — chips, tiny controls */
    --radius-sm:   0.375rem;           /* 6px  — inputs, small buttons */
    --radius:      0.5rem;             /* 8px  — default */
    --radius-card: 0.5rem;             /* 8px  — cards, editorial */
    --radius-md:   0.75rem;            /* 12px — panels */
    --radius-lg:   1rem;               /* 16px — large cards */
    --radius-xl:   1.25rem;            /* 20px — hero surfaces */
    --radius-2xl:  1.5rem;             /* 24px — full-bleed blocks */
    --radius-pill: 9999px;             /* pill badges / filters */
    --radius-circle: 50%;              /* avatars, dots, round buttons */
    --radius-2xs: 2px;
    --radius-stack-plan: 14px;
    --radius-stack-pair-logo: 9px;
    --radius-stack-card: 22px;
    --radius-stack-card-mobile: 18px;
    --radius-stack-logo: 13px;
    --radius-stack-logo-mobile: 11px;
    --color-stack-accent-fallback: #8E8E93;
    --color-stack-saving: #0E9F6E;
    --color-stack-overlap: #E8590C;

    /* ── Component heights ── */
    --h-btn:   56px;                   /* primary/secondary button */
    --h-input: 56px;                   /* input fields */
    --h-btn-sm: 40px;                  /* compact button */
    --navbar-h: 68px;                  /* fixed navbar height — canonical */
    --header-height: var(--navbar-h);  /* alias — same value */

    /* ── Layout grid tokens ──────────────────────
       Usage: @layer components → .layout-shell, .layout-content, etc.
       All containers use the same --layout-gutter → one breakpoint to rule them all.
    ─────────────────────────────────────────── */
    --layout-max:            1440px;   /* full-width shell (hero backgrounds, CTA bands) */
    /* Editorial content column (guides, articles, tools). Was a hard
       1280px cap, which left an ever-growing idle margin on wide desktop
       screens once the viewport passed ~1280px + gutters — the column
       just stopped growing while the screen kept getting wider. Clamp
       lets it keep expanding with the viewport (still 1280px minimum,
       same as before, on anything narrower) up to a 1600px ceiling so
       it doesn't stretch into unreadable line lengths on ultra-wide
       monitors either. */
    --layout-content:        clamp(1280px, 90vw, 1600px);
    --layout-article:        760px;    /* article text column */
    --layout-sidebar:        260px;    /* article TOC sidebar */
    --layout-tool-sidebar:   360px;    /* tool page sticky card */
    --layout-gutter:         48px;     /* horizontal padding — desktop */
    --layout-gutter-tablet:  32px;
    --layout-gutter-mobile:  20px;

    /* ── Spacing scale ── */
    --space-2xs: 4px;
    --space-xs:  8px;
    --space-sm:  12px;
    --space-md:  16px;
    --space-lg:  24px;
    --space-xl:  32px;
    --space-2xl: 48px;
    --space-3xl: 64px;
    --space-4xl: 96px;

    /* ── Semantic overrides ── */
    --savings: 224 76% 50%;          /* ToolTrim blue — featured savings */
    --savings-foreground: 0 0% 100%;
    --cancel: 0 72% 55%;
    --cancel-foreground: 0 0% 100%;
    --keep: 142 60% 38%;
    --keep-foreground: 0 0% 100%;

    /* ── Sidebar ── */
    --sidebar-background: 0 20% 99%;
    --sidebar-foreground: 240 3% 12%;
    --sidebar-primary: 224 76% 50%;
    --sidebar-primary-foreground: 0 0% 100%;
    --sidebar-accent: 60 15% 94%;
    --sidebar-accent-foreground: 240 3% 12%;
    --sidebar-border: 60 7% 84%;
    --sidebar-ring: 224 76% 50%;

    /* ── Font families ── */
    --font-brand: "Uncut Sans", system-ui, sans-serif;
    --font-ui:    "Inter Tight", "Inter", system-ui, sans-serif;

    /* ────────────────────────────────────────────
       SEMANTIC PALETTE REFERENCE (hex aliases)
       Use with color: var(--color-*) in custom CSS.
       For Tailwind, use the tokens above.
    ──────────────────────────────────────────── */
    --color-bg:            #FFFFFF;
    --color-surface:       #FFFFFF;
    --color-surface-soft:  #F5F5F7;
    --color-chip:          #E0DBD7;    /* deeper warm taupe — tags/badges, one notch past surface-soft */
    /* Palette warm greys (CLAUDE.md): page backgrounds and secondary surfaces. */
    --color-bg-warm:       #F6F5F4;
    --color-surface-warm:  #EDEBE9;

    --color-text:          #1D1D1F;
    --color-text-strong:   #1D1D1F;
    --color-muted:         #1D1D1F;
    --color-muted-light:   #1D1D1F;
    /* Secondary tones (Michael, 8 Oct 2026): body copy and metadata only,
       never titles; both pass AA on #FFFFFF and #F6F5F4. */
    --color-text-secondary: #424245;
    --color-text-meta:      #6F6F68;

    --color-border:        #E6E6E6;
    --color-border-soft:   #E7E7E0;
    --color-border-strong: #1D1D1F;

    --color-hover:         #1D1D1F;
    --color-hover-text:    #FFFFFF;
    --color-hover-strong:  #000000;    /* deepest press state, one notch past --color-hover */

    /* Dark "ink" surface — floating pill nav, aligned with the footer slab */
    --color-ink:           oklch(0.20 0.004 100);
    --color-ink-border:    oklch(0.30 0.004 100);

    --color-accent:        hsl(224 76% 50%);   /* ToolTrim blue */
    --color-accent-soft:   hsl(224 76% 96%);   /* very light tint */

    /* Editorial illustration and stack-family surfaces. These remain named
       tokens so component CSS never recreates an ad-hoc colour palette. */
    --color-story-clay:       #D8C9B8;
    --color-story-sage:       #BCC4BD;
    --color-story-sand:       #E4DED1;
    --color-story-taupe:      #C5B6A1;
    --color-story-mist:       #D7D8D2;
    --color-stack-default:    #E5F5FF;
    --color-stack-ia:         #EEE7FF;
    --color-stack-organise:   #DFF3EA;
    --color-stack-design:     #DEF0FB;
    --color-stack-automate:   #FFE3CF;
    --color-stack-market:     #F8E2EF;
    --color-stack-sell:       #E5ECFF;
    --color-stack-finance:    #E3F0DC;
    --color-stack-dev:        #E8E0FF;
    --color-stack-custom:     #F3EAD2;
    --color-stack-create:     #D8D7D0;
    --color-tutorial-surface: #F8F8F4;

    /* ── ToolTrim typography scale — canonical size tokens ──────────────────
       Single source of truth. All page-level classes (cp-*, sd-*, tt-*) must
       reference these vars instead of hard-coding clamp() / px values.
       To resize a level globally → change ONE var here.
    ──────────────────────────────────────────────────────────────────────── */
    --tt-size-hero:          clamp(64px, 8vw, 124px);    /* H1 Compare, ToolDetail */
    --tt-size-hero-sub:      clamp(22px, 2vw, 30px);     /* Subtitle / promise below H1 */
    --tt-size-page-title:    clamp(40px, 4.5vw, 56px);   /* Editorial page/article H1 */
    --tt-size-section-h:     clamp(25px, 2.4vw, 32px);    /* Section title — compact gallery hierarchy */
    --tt-size-section-intro: clamp(16px, 1.3vw, 18px);   /* Subtitle directly under section title */
    --tt-size-body-large:    clamp(18px, 1.5vw, 22px);   /* Large body / framing copy */
    --tt-size-body:          16px;                        /* Standard body */
    --tt-size-kicker:        11px;                        /* ALL kickers / eyebrows */
    --tt-size-fact:          clamp(18px, 1.2vw, 22px);   /* Fact/data value */
    --tt-size-fact-compact:  14px;                        /* Table cell / compact fact */
    --tt-size-card-title:    15px;                        /* Card / row title */
    --tt-size-card-body:     14px;                        /* Card body / secondary note */
    --tt-size-metric:        clamp(24px, 1.8vw, 32px);   /* KPI / metric */
    --tt-size-cta-h:         clamp(22px, 2.5vw, 36px);    /* CTA band heading */

    /* ── Section / hero spacing ── */
    --tt-section-y: clamp(56px, 5.5vw, 88px);  /* Section vertical padding — tightened so consecutive sections read as flow, not islands */
    --tt-hero-pt:   72px;                       /* Hero padding-top */
    --tt-hero-pb:   64px;                       /* Hero padding-bottom */

    /* ── Border radius scale ── */
    --tt-radius-sm: 12px;
    --tt-radius-md: 18px;
    --tt-radius-lg: 24px;
    --tt-radius-xl: 32px;
    /* Public editorial surfaces — use these aliases instead of choosing a
       geometric radius per component. Controls remain pill/circle tokens. */
    --tt-surface-radius-info:  var(--tt-radius-sm); /* informative / functional card */
    --tt-surface-radius-media: var(--tt-radius-md); /* image-led editorial card */
    --tt-surface-radius-panel: var(--tt-radius-lg); /* grouped section / hero panel */
  }

  /* ── Global interaction primitives — adapted from details.so ──────────
     Squircle corners everywhere (falls back invisibly to plain
     border-radius in browsers without corner-shape support), plus a
     press-scale on every real control, sitewide. This is deliberately
     :active, not :hover — the source has no hover-transform anywhere
     either; the only motion is the click/tap response.

     Uses `animation`, not `transition: transform`, on purpose: `transition`
     is a shorthand, so a lower-specificity rule adding transform to it
     either loses outright to a component's own `transition` (no scale
     smoothing — this bit ToolTrim's own audit: measured coverage of only
     14–47% of real links/buttons across a sample page before this fix)
     or a higher-specificity rule wins outright and silently deletes that
     component's own colour/background transition timing. `animation` is a
     wholly separate property from `transition`, so it can never collide
     with any of the hundreds of existing per-component transitions in
     this file — smooth press-in on 100% of controls, guaranteed. */
  *, *::before, *::after {
    corner-shape: superellipse(1.2);
  }

  @keyframes tt-press {
    to { transform: scale(0.97); }
  }
  :where(a[href], button:not(:disabled), [role="button"]):active {
    animation: tt-press 150ms ease-out forwards;
  }

  /* Responsive gutter — tablet & mobile overrides */
  @media (max-width: 1023px) {
    :root { --layout-gutter: var(--layout-gutter-tablet); }
  }
  @media (max-width: 767px) {
    :root { --layout-gutter: var(--layout-gutter-mobile); }
  }

  .dark {
    /* Editorial dark — same warm neutrals, darkened */
    --background: 0 0% 7%;           /* #111111 */
    --foreground: 60 8% 87%;         /* #DEDED6 — warm near-white */

    --card: 0 0% 10%;                /* #1A1A1A */
    --card-foreground: 60 8% 87%;

    --popover: 0 0% 10%;
    --popover-foreground: 60 8% 87%;

    --primary: 224 76% 62%;          /* slightly lighter blue for dark bg */
    --primary-foreground: 0 0% 100%;

    --secondary: 0 0% 13%;           /* #222222 */
    --secondary-foreground: 60 5% 80%;

    --muted: 0 0% 13%;
    --muted-foreground: 60 3% 55%;   /* #8A8A82 */

    --accent: 224 40% 16%;
    --accent-foreground: 224 76% 72%;

    --destructive: 0 62% 44%;
    --destructive-foreground: 0 0% 100%;

    --border: 0 0% 18%;              /* #2E2E2E */
    --input:  0 0% 18%;
    --ring:   224 76% 62%;

    --keep: 142 55% 44%;
    --keep-foreground: 0 0% 100%;
    --cancel: 0 70% 55%;
    --cancel-foreground: 0 0% 100%;
    --savings: 224 76% 62%;
    --savings-foreground: 0 0% 100%;

    --sidebar-background: 0 0% 7%;
    --sidebar-foreground: 60 5% 75%;
    --sidebar-primary: 224 76% 62%;
    --sidebar-primary-foreground: 0 0% 100%;
    --sidebar-accent: 0 0% 13%;
    --sidebar-accent-foreground: 60 5% 80%;
    --sidebar-border: 0 0% 18%;
    --sidebar-ring: 224 76% 62%;

    /* dark mode hex aliases */
    --color-bg:            #111111;
    --color-surface:       #1A1A1A;
    --color-surface-soft:  #222222;
    --color-chip:          #2B2A28;
    --color-bg-warm:       #1A1A1A;
    --color-surface-warm:  #222222;
    --color-text:          #DEDED6;
    --color-text-strong:   #F0F0EA;
    --color-muted:         #8A8A82;
    --color-muted-light:   #5E5E58;
    --color-text-secondary: #C9C9C1;
    --color-text-meta:      #8A8A82;
    --color-border:        #2E2E2E;
    --color-border-soft:   #262626;
    --color-border-strong: #DEDED6;
    --color-hover:         #DEDED6;
    --color-hover-text:    #111111;
    --color-hover-strong:  #FFFFFF;    /* inverted: deepest press = brightest */
    --color-accent:        hsl(224 76% 62%);
    --color-accent-soft:   hsl(224 40% 16%);
  }
}

/* Story article layout: documentary grid inspired by the shared reference. */
@layer components {
  .analytics-consent { position: fixed; z-index: 1000; right: 20px; bottom: 20px; width: min(440px, calc(100vw - 32px)); display: flex; gap: 20px; align-items: end; padding: 20px; border: 1px solid #DADAD4; border-radius: 14px; background: #FFFFFF; box-shadow: 0 12px 40px rgba(34,34,34,.14); color: #222222; }
  .analytics-consent__copy { flex: 1; }
  .analytics-consent__copy strong { display: block; margin-bottom: 6px; font: 600 16px/1.2 var(--font-ui); }
  .analytics-consent__copy p { margin: 0 0 8px; font: 400 13px/1.45 var(--font-ui); color: #6F6F68; }
  .analytics-consent__copy a { font: 500 12px/1 var(--font-ui); color: #222222; text-decoration: underline; }
  .analytics-consent__actions { display: flex; flex-direction: column-reverse; gap: 8px; flex-shrink: 0; }
  .analytics-consent__actions button { min-height: 36px; padding: 0 14px; border: 1px solid #DADAD4; border-radius: 999px; font: 600 12px/1 var(--font-ui); cursor: pointer; }
  .analytics-consent__accept { background: #222222; color: #FFFFFF; border-color: #222222 !important; }
  .analytics-consent__refuse { background: #FFFFFF; color: #222222; }
  @media (max-width: 560px) {
    .analytics-consent {
      right: 0;
      bottom: calc(66px + env(safe-area-inset-bottom));
      width: 100%;
      max-height: min(48vh, 360px);
      flex-direction: column;
      align-items: stretch;
      gap: 12px;
      padding: 16px;
      border-right: 0;
      border-bottom: 0;
      border-left: 0;
      border-radius: 16px 16px 0 0;
    }
    .analytics-consent__copy { min-height: 0; overflow: auto; }
    .analytics-consent__copy p { max-width: 60ch; }
    .analytics-consent__actions { flex-direction: row; }
    .analytics-consent__actions button { flex: 1; min-height: 40px; }
  }
  /* Barre d'onglets du bas (jusqu'à 640 px) : le bandeau se pose au-dessus
     au lieu de la couvrir. */
  @media (min-width: 561px) and (max-width: 640px) {
    .analytics-consent { bottom: calc(78px + env(safe-area-inset-bottom)); }
  }
}
