/* ─────────────────────────────────────────────
   GLOBAL LAYOUT UTILITIES
   Single source of truth for container widths.
   All pages should use these tokens (migration progressive).
───────────────────────────────────────────── */

/* ── Force light mode on editorial pages (ComparePage) ─────────────
   Overrides the .dark root cascade. Declared outside @layer so
   specificity beats the layered .dark values.
────────────────────────────────────────────────────────────────── */
.cp-page-light {
  color-scheme: light;
  background-color: var(--color-bg);
  color: var(--color-text);
  /* shadcn/tailwind tokens */
  --background: 0 20% 99%;
  --foreground: 240 3% 12%;
  --card: 0 0% 100%;
  --card-foreground: 240 3% 12%;
  --popover: 0 0% 100%;
  --popover-foreground: 240 3% 12%;
  --muted: 60 15% 94%;
  --muted-foreground: 240 3% 12%;
  --border: 60 7% 84%;
  --input: 60 7% 84%;
  --secondary: 60 15% 94%;
  --secondary-foreground: 240 3% 12%;
  --accent: 224 76% 96%;
  --accent-foreground: 224 76% 44%;
  /* semantic hex tokens */
  --color-bg:            #FFFFFF;
  --color-surface:       #FFFFFF;
  --color-surface-soft:  #F5F5F7;
  --color-chip:          #E0DBD7;
  --color-text:          #1D1D1F;
  --color-text-strong:   #1D1D1F;
  --color-muted:         #1D1D1F;
  --color-muted-light:   #1D1D1F;
  --color-border:        #E6E6E6;
  --color-border-soft:   #E7E7E0;
  --color-border-strong: #1D1D1F;
  --color-hover:         #1D1D1F;
  --color-hover-text:    #FFFFFF;
}

/* ─────────────────────────────────────────────
   BASE TYPOGRAPHY
   --font-brand  Uncut Sans — logo, h1/h2, identity moments
   --font-ui     Inter Tight — body, nav, UI, cards, tables
───────────────────────────────────────────── */
@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply bg-background text-foreground antialiased;
    font-family: var(--font-ui);
    font-size: 16px;           /* 15–17px range */
    line-height: 1.5;          /* 1.45–1.6 range */
    font-weight: 400;
    letter-spacing: -0.005em;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  /* h1 / h2 — brand identity moments */
  h1, h2 {
    font-family: var(--font-brand);
    color: hsl(var(--foreground));
  }

  h1 {
    font-weight: 600;
    line-height: 1.0;
    letter-spacing: -0.04em;
  }
  h2 {
    font-weight: 600;
    line-height: 1.0;
    letter-spacing: -0.04em;
  }

  /* h3–h6 — UI / content headings */
  h3, h4, h5, h6 {
    font-family: var(--font-ui);
    color: hsl(var(--foreground));
  }
  h3 {
    font-weight: 600;
    line-height: 1.1;
    letter-spacing: -0.03em;
  }
  h4, h5, h6 {
    font-weight: 500;
    line-height: 1.3;
    letter-spacing: -0.01em;
  }

  p {
    line-height: 1.55;
  }

  /* Prose overrides for guide content */
  .prose h1, .prose h2, .prose h3,
  .prose h4, .prose h5, .prose h6 {
    font-family: var(--font-brand);
  }
  .prose p, .prose li, .prose blockquote {
    font-family: var(--font-ui);
    font-size: 1rem;
    line-height: 1.75;
  }
  .prose strong {
    font-weight: 600;
  }
}

/* ─────────────────────────────────────────────
   TYPE SCALE — single source of truth
   --font-brand  h1, h2, identity moments
   --font-ui     h3+, body, UI everywhere
───────────────────────────────────────────── */
@layer components {

  /* ── Section titles — brand font, 32–56px ── */
  .ts-h1 {
    font-family: var(--font-brand);
    font-size: clamp(2rem, 5.5vw, 3.5rem);   /* 32–56px */
    font-weight: 600;
    line-height: 1.0;
    letter-spacing: -0.04em;
    color: hsl(var(--foreground));
  }

  .ts-h2 {
    font-family: var(--font-ui);
    font-size: var(--tt-size-section-h);
    font-weight: 620;
    line-height: 1.08;
    letter-spacing: -0.035em;
    color: hsl(var(--foreground));
  }

  /* ── Card / step titles — UI font, 22–32px ── */
  .ts-h3 {
    font-family: var(--font-ui);
    font-size: clamp(1.375rem, 2vw, 2rem);   /* 22–32px */
    font-weight: 600;
    line-height: 1.1;
    letter-spacing: -0.03em;
    color: hsl(var(--foreground));
  }

  /* ── Scores — UI font, 48–80px ── */
  .ts-score {
    font-family: var(--font-ui);
    font-size: clamp(3rem, 7vw, 5rem);       /* 48–80px */
    font-weight: 700;
    line-height: 0.9;
    letter-spacing: -0.05em;
    color: hsl(var(--foreground));
  }

  /* ── Metadata / labels — UI font, 10–12px ── */
  .ts-eyebrow {
    font-family: var(--font-ui);
    font-size: 0.6875rem;                    /* 11px */
    font-weight: 600;
    line-height: 1;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: hsl(var(--muted-foreground));
  }

  /* Canonical section heading for pages that do not use a prefixed shared
     header component yet. Page H1/hero titles intentionally stay separate. */
  .tt-section-title {
    margin: 0;
    color: var(--color-text-strong);
    font-family: var(--font-ui);
    font-size: var(--tt-size-section-h);
    font-weight: 620;
    letter-spacing: -0.035em;
    line-height: 1.08;
  }

  .ts-caption {
    font-family: var(--font-ui);
    font-size: 0.6875rem;                    /* 11px */
    font-weight: 500;
    line-height: 1.4;
    color: hsl(var(--muted-foreground));
  }

  /* ── Mono badge — prices, savings, technical ── */
  .ts-mono-badge {
    font-family: "DM Mono", ui-monospace, monospace;
    font-size: 0.6875rem;                    /* 11px */
    font-weight: 500;
    letter-spacing: 0.04em;
    text-transform: none;
  }
}

/* ─────────────────────────────────────────────
   TT TYPE SCALE — canonical ToolTrim typography
   Single source of truth for all page templates.
   Stack pages and Compare pages use these values.
   No page-specific font-size overrides unless
   for layout-only concerns (grid, max-width).
   ─────────────────────────────────────────────
   Anti-exception rule:
   FORBIDDEN → .cp-hero-title { font-size: clamp(72px,12vw,170px) }
   REQUIRED  → align cp-* to tt-* values below
───────────────────────────────────────────── */
@layer components {
  /* ── Section kicker / eyebrow ───────────────── */
  .tt-kicker {
    font-family: var(--font-ui);
    font-size: var(--tt-size-kicker);
    font-weight: 700;
    line-height: 1;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-muted);
    display: block;
  }
  /* ── Body text ───────────────────────────────── */
  .tt-body {
    font-family: var(--font-ui);
    font-size: var(--tt-size-body);
    font-weight: 400;
    line-height: 1.5;
  }
  /* ── Body large — framing, summaries ────────── */
  .tt-body-large {
    font-family: var(--font-ui);
    font-size: var(--tt-size-body-large);
    font-weight: 400;
    line-height: 1.42;
    letter-spacing: -0.02em;
  }
  /* ── Fact label — uppercase micro label ──────── */
  .tt-fact-label {
    font-family: var(--font-ui);
    font-size: 10px;
    font-weight: 700;
    line-height: 1;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-muted-light);
    display: block;
  }
  /* ── CTA band heading — medium-scale title ──── */
  .tt-cta-title {
    font-family: var(--font-brand);
    font-size: var(--tt-size-cta-h);
    font-weight: 600;
    letter-spacing: -0.055em;
    line-height: 0.98;
    color: var(--color-text);
    max-width: 720px;
    margin: 0 0 16px;
  }

  /* ─────────────────────────────────────────────
     GLOBAL BUTTONS
     Use these site-wide instead of page-specific
     button styles. Never create a local .foo-btn.
  ───────────────────────────────────────────── */
  .tt-button-primary {
    display: inline-flex;
    align-items: center;
    flex-shrink: 0;
    height: 40px;
    padding: 0 18px;
    background: var(--color-text);
    border: none;
    border-radius: var(--radius);
    font-family: var(--font-ui);
    font-size: 13px;
    font-weight: 600;
    color: var(--color-surface);
    text-decoration: none;
    white-space: nowrap;
    cursor: pointer;
    transition: background 0.15s ease;
  }
  .tt-button-primary:hover { background: #3A3A38; }
  /* Both buttons render with no visible focus state at all (verified: a
     tabbed-to .tt-button-primary computes outline: none with nothing to
     replace it) — every other interactive control in this file gets a
     :focus-visible outline, these two global, site-wide button classes
     didn't. */
  .tt-button-primary:focus-visible { outline: 2px solid var(--color-text); outline-offset: 2px; }
  .tt-button-secondary {
    display: inline-flex;
    align-items: center;
    flex-shrink: 0;
    height: 40px;
    padding: 0 18px;
    background: transparent;
    border: 1.5px solid var(--color-border-strong);
    border-radius: var(--radius);
    font-family: var(--font-ui);
    font-size: 13px;
    font-weight: 600;
    color: var(--color-text);
    text-decoration: none;
    white-space: nowrap;
    cursor: pointer;
    transition: background 0.15s ease, color 0.15s ease;
  }
  .tt-button-secondary:hover { background: var(--color-text); color: var(--color-surface); }
  .tt-button-secondary:focus-visible { outline: 2px solid var(--color-text); outline-offset: 2px; }

}

/* ─────────────────────────────────────────────
   COMPONENTS — surfaces, buttons, inputs, badges
───────────────────────────────────────────── */
@layer components {

  /* ── Surfaces ───────────────────────────────── */
  .surface-card {
    border-radius: var(--radius-card);
    border: 1px solid var(--color-border);
    background: var(--color-surface);
  }

  .dark .surface-card {
    border-color: hsl(0 0% 18%);
    background: hsl(0 0% 10%);
  }

  /* Grey hover — no blue tint */
  .surface-card-hover {
    border-radius: var(--radius-card);
    border: 1px solid var(--color-border);
    background: var(--color-surface);
    transition: border-color 180ms ease-out, background 180ms ease-out;
    cursor: pointer;
  }

  .surface-card-hover:hover {
    border-color: var(--color-text);
    background: var(--color-bg);
  }

  .dark .surface-card-hover {
    border-color: hsl(0 0% 18%);
    background: hsl(0 0% 10%);
  }

  .dark .surface-card-hover:hover {
    border-color: hsl(0 0% 45%);
    background: hsl(0 0% 13%);
  }

  .surface-panel {
    border-radius: var(--radius-card);
    border: 1px solid var(--color-border);
    background: hsl(var(--background));
  }

  .dark .surface-panel {
    border-color: hsl(0 0% 18%);
  }

  .surface-accent {
    border-radius: var(--radius-card);
    border: 1px solid hsl(var(--primary) / 0.2);
    background: hsl(var(--primary) / 0.06);
  }

  .surface-control {
    border-radius: var(--radius-card);
    border: 1px solid var(--color-border);
    background: hsl(var(--background));
    transition: border-color 180ms ease-out;
  }

  .surface-control:hover {
    border-color: var(--color-text);
  }

  .dark .surface-control {
    border-color: hsl(0 0% 20%);
  }

  /* ── Input system ─────────────────────────────── */
  .input {
    display: block;
    width: 100%;
    height: var(--h-input);
    padding: 0 18px;
    border-radius: var(--radius);
    border: 1px solid var(--color-border);
    background: var(--color-surface-soft);
    color: var(--color-text);
    font-family: var(--font-ui);
    font-size: 1rem;                   /* 16px */
    font-weight: 400;
    line-height: 1;
    letter-spacing: -0.01em;
    outline: none;
    transition: border-color 160ms ease-out, background 160ms ease-out;
    -webkit-appearance: none;
    appearance: none;
  }

  .input::placeholder {
    color: var(--color-muted);
    font-weight: 400;
  }

  .input:hover {
    background: var(--color-surface-soft);
  }

  .input:focus {
    border-color: var(--color-text);
    background: var(--color-surface-soft);
    box-shadow: none;
  }

  .dark .input {
    background: hsl(0 0% 14%);
    border-color: hsl(0 0% 22%);
    color: hsl(var(--foreground));
  }

  .dark .input::placeholder {
    color: hsl(var(--muted-foreground));
  }

  .dark .input:focus {
    border-color: hsl(0 0% 50%);
  }

  /* Compact input */
  .input-sm {
    height: var(--h-btn-sm);
    padding: 0 14px;
    border-radius: var(--radius-sm);
    font-size: 0.875rem;
  }

  /* ── Badge / pill system ──────────────────────── */

  /* Base badge */
  .badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    height: 28px;
    padding: 0 10px;
    border: 1px solid var(--color-border);
    background: transparent;
    color: var(--color-text);
    border-radius: var(--radius-pill);
    font-family: var(--font-ui);
    font-size: 0.75rem;                /* 12px */
    font-weight: 500;
    line-height: 1;
    letter-spacing: -0.005em;
    white-space: nowrap;
  }

  .dark .badge {
    border-color: hsl(0 0% 25%);
    color: hsl(var(--foreground));
  }

  /* ── Label (metadata, section headings) ──────── */
  .label {
    display: inline-block;
    font-family: var(--font-ui);
    font-size: 11px;
    font-weight: 600;
    line-height: 1;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-muted);
  }

  .dark .label {
    color: hsl(var(--muted-foreground));
  }

  /* ── Dividers / borders ───────────────────────── */
  /* Use border-top: 1px solid var(--color-border) inline,
     or these utilities for standalone dividers: */
  .divider {
    border: none;
    border-top: 1px solid var(--color-border);
    margin: 0;
  }

  .dark .divider {
    border-top-color: hsl(0 0% 18%);
  }

  .divider-soft {
    border: none;
    border-top: 1px solid var(--color-border-soft);
  }

  .dark .divider-soft {
    border-top-color: hsl(0 0% 15%);
  }

  /* ── Editorial container ──────────────────────── */
  .container-page {
    width: 100%;
    max-width: 1440px;
    margin-left: auto;
    margin-right: auto;
    padding-left: 56px;
    padding-right: 56px;
  }

  @media (max-width: 1023px) {
    .container-page {
      padding-left: 32px;
      padding-right: 32px;
    }
  }

  @media (max-width: 639px) {
    .container-page {
      padding-left: 20px;
      padding-right: 20px;
    }
  }

  /* ── Section spacing ──────────────────────────── */
  .section-lg {
    padding-top: 96px;
    padding-bottom: 96px;
  }

  @media (min-width: 1024px) {
    .section-lg {
      padding-top: 128px;
      padding-bottom: 128px;
    }
  }

  .section-md {
    padding-top: 64px;
    padding-bottom: 64px;
  }

  @media (min-width: 1024px) {
    .section-md {
      padding-top: 80px;
      padding-bottom: 80px;
    }
  }

  .section-sm {
    padding-top: 40px;
    padding-bottom: 40px;
  }

  @media (min-width: 1024px) {
    .section-sm {
      padding-top: 56px;
      padding-bottom: 56px;
    }
  }
}

/* ─────────────────────────────────────────────
   LOGO — monochromatic dark ink, inverts on dark bg
───────────────────────────────────────────── */
@layer utilities {
  .site-logo {
    /* dark ink on light bg — no filter needed */
  }

  .dark .site-logo {
    /* invert #222 → #ddd (near-white) for dark mode */
    filter: invert(1);
  }
}

/* ─────────────────────────────────────────────
   NAVIGATION — header, nav links, mega-menu
───────────────────────────────────────────── */
@layer components {
  /* ── Header shell ─────────────────────────── */
  .header-root {
    background: var(--color-bg);
    border-bottom: 1px solid var(--color-border);
  }

  .dark .header-root {
    background: hsl(var(--background));
    border-bottom-color: hsl(var(--border));
  }

  .header-inner {
    padding-left: 44px;
    padding-right: 44px;
  }

  @media (max-width: 1023px) {
    .header-inner {
      padding-left: 20px;
      padding-right: 20px;
    }
  }

  /* ── Desktop nav link ─────────────────────── */
  .nav-link {
    position: relative;
    display: inline-flex;
    align-items: center;
    height: 100%;
    font-family: var(--font-ui);
    font-size: 0.9375rem;              /* 15px */
    font-weight: 500;
    line-height: 1;
    letter-spacing: -0.02em;
    color: var(--color-text);
    background: none;
    border: none;
    cursor: pointer;
    text-decoration: none;
    transition: opacity 160ms ease-out;
    white-space: nowrap;
    padding: 0;
  }

  .dark .nav-link {
    color: hsl(var(--foreground));
  }

  .nav-link:hover,
  .nav-link:focus-visible {
    opacity: 0.60;
    outline: none;
  }

  /* Active: 1px underline sitting close beneath the text */
  .nav-link::after {
    content: "";
    position: absolute;
    bottom: 16px;
    left: 0;
    right: 0;
    height: 1px;
    background: transparent;
    transition: background 160ms ease-out;
  }

  .nav-link--active::after {
    background: var(--color-text);
  }

  .dark .nav-link--active::after {
    background: hsl(var(--foreground));
  }

  /* ── Explorer trigger (panel opener) ─────── */
  .nav-explorer-btn {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 4px;
    height: 100%;
    font-family: var(--font-ui);
    font-size: 0.9375rem;              /* 15px */
    font-weight: 500;
    line-height: 1;
    letter-spacing: -0.02em;
    color: var(--color-text);
    background: none;
    border: none;
    cursor: pointer;
    padding: 0;
    transition: opacity 160ms ease-out;
    white-space: nowrap;
  }

  .dark .nav-explorer-btn {
    color: hsl(var(--foreground));
  }

  .nav-explorer-btn:hover,
  .nav-explorer-btn:focus-visible {
    opacity: 0.60;
    outline: none;
  }

  /* Chevron */
  .nav-chevron {
    width: 13px;
    height: 13px;
    flex-shrink: 0;
    transition: transform 200ms cubic-bezier(0.4, 0, 0.2, 1);
    color: var(--color-text);
  }

  .dark .nav-chevron {
    color: hsl(var(--foreground));
  }

  .nav-chevron--open {
    transform: rotate(180deg);
  }

  /* ── Inline search bar (desktop header) ──── */
  .nav-search-bar {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    width: clamp(260px, 30vw, 560px);
    height: 48px;
    padding: 0 6px 0 20px;
    background: color-mix(in srgb, var(--color-surface) 64%, var(--color-border));
    border: 1px solid transparent;
    border-radius: var(--radius-pill);
    cursor: pointer;
    text-decoration: none;
    transition: background 160ms ease-out, box-shadow 160ms ease-out;
    flex-shrink: 0;
  }

  .dark .nav-search-bar {
    background: hsl(0 0% 14%);
    border-color: hsl(0 0% 22%);
  }

  .nav-search-bar:hover {
    background: color-mix(in srgb, var(--color-surface) 52%, var(--color-border));
  }

  .dark .nav-search-bar:hover {
    background: hsl(0 0% 17%);
    border-color: hsl(0 0% 32%);
  }

  .nav-search-bar:focus-visible {
    outline: none;
    box-shadow: 0 0 0 4px color-mix(in srgb, var(--color-text) 14%, transparent);
  }

  /* Trailing action circle — the pill's actual "submit search" affordance,
     filling most of the pill's height instead of a plain leading icon. */
  .nav-search-bar-action {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    flex-shrink: 0;
    border-radius: var(--radius-circle);
    background: var(--color-text);
    transition: background 160ms ease-out;
  }

  .nav-search-bar:hover .nav-search-bar-action {
    background: color-mix(in srgb, var(--color-text) 88%, var(--color-bg));
  }

  .nav-search-bar-icon {
    width: 17px;
    height: 17px;
    flex-shrink: 0;
    color: var(--color-bg);
    stroke-width: 1.8;
  }

  .nav-search-placeholder {
    flex: 1;
    font-family: var(--font-ui);
    font-size: 0.9375rem;              /* 15px */
    font-weight: 600;
    color: color-mix(in srgb, var(--color-text) 68%, var(--color-muted));
    text-align: left;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .dark .nav-search-placeholder {
    color: hsl(var(--muted-foreground));
  }

  /* Keyboard shortcut badge */
  .nav-kbd {
    display: inline-flex;
    align-items: center;
    height: 22px;
    padding: 0 7px;
    border-radius: var(--radius-xs);
    border: 1px solid var(--color-border);
    background: var(--color-surface);
    font-family: var(--font-ui);
    font-size: 0.6875rem;              /* 11px */
    font-weight: 500;
    line-height: 1;
    color: var(--color-muted);
    letter-spacing: 0;
    flex-shrink: 0;
    white-space: nowrap;
  }

  .dark .nav-kbd {
    background: hsl(0 0% 16%);
    border-color: hsl(0 0% 24%);
    color: hsl(var(--muted-foreground));
  }

  /* (nav-submit-btn removed — Submit Tool link moved to the footer) */

  /* ── Mobile menu button ───────────────────── */
  .nav-menu-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    height: 40px;
    padding: 0 14px;
    border-radius: var(--radius-sm);
    border: 1px solid hsl(var(--border));
    background: transparent;
    color: hsl(var(--foreground));
    font-family: var(--font-ui);
    font-size: 0.875rem;
    font-weight: 500;
    cursor: pointer;
    text-decoration: none;
    transition: border-color 180ms ease-out, background 180ms ease-out;
    white-space: nowrap;
  }

  .nav-menu-btn:hover {
    border-color: hsl(var(--foreground));
    background: hsl(var(--secondary));
  }

  .nav-menu-btn--open {
    border-color: hsl(var(--foreground));
    background: hsl(var(--foreground));
    color: hsl(var(--background));
  }

  .nav-menu-btn--open:hover {
    background: hsl(var(--foreground) / 0.88);
  }

  .nav-menu-btn:focus-visible {
    outline: 2px solid hsl(var(--primary));
    outline-offset: 2px;
  }

  /* ── Editorial exploration panel ──────────── */

  /* Panel shell — floats 8px below the header, no duplicated header inside */
  .editorial-panel {
    --color-muted: #5f5f59;
    --color-muted-light: #5f5f59;
    border-radius: var(--radius-md);
    background: var(--color-surface-soft);
    border: 1px solid var(--color-border);
  }

  .editorial-panel .text-muted-foreground {
    color: var(--color-muted);
  }

  .dark .editorial-panel {
    background: hsl(0 0% 12%);
    border-color: hsl(0 0% 20%);
  }

  /* Enter: opacity + subtle lift, spring-free ease-out */
  .editorial-panel--opening {
    animation: panel-in 210ms cubic-bezier(0.22, 1, 0.36, 1) both;
  }

  /* Exit: faster, ease-in */
  .editorial-panel--closing {
    animation: panel-out 160ms ease-in both;
    pointer-events: none;
  }

  /* Body layout — fills the whole panel, no top row */
  .panel-body {
    display: flex;
    height: 100%;
    overflow: hidden;
  }

  /* Left rail */
  .panel-rail {
    width: 260px;
    flex-shrink: 0;
    display: flex;
    flex-direction: column;
    gap: 2px;
    padding: 28px 14px 24px;
    border-right: 1px solid var(--color-border);
    overflow-y: auto;
  }

  .dark .panel-rail {
    border-right-color: hsl(0 0% 18%);
  }

  .panel-rail-item {
    display: flex;
    align-items: center;
    gap: 9px;
    width: 100%;
    padding: 9px 14px;
    border-radius: var(--radius);
    border: none;
    background: transparent;
    color: var(--color-text);
    font-family: var(--font-ui);
    font-size: 0.9375rem;            /* 15px */
    font-weight: 400;
    letter-spacing: -0.01em;
    cursor: pointer;
    text-align: left;
    transition: background 140ms ease-out;
    white-space: nowrap;
    position: relative;
  }

  .dark .panel-rail-item {
    color: hsl(var(--foreground));
  }

  .panel-rail-item:hover {
    background: var(--color-bg);
  }

  .dark .panel-rail-item:hover {
    background: hsl(0 0% 18%);
  }

  .panel-rail-item--active {
    background: var(--color-surface);
    font-weight: 600;
  }

  .panel-rail-item--active::before {
    content: "";
    position: absolute;
    left: 0;
    top: 50%;
    transform: translateY(-50%);
    width: 2px;
    height: 18px;
    border-radius: var(--radius-xs);
    background: hsl(var(--primary));
  }

  .dark .panel-rail-item--active {
    background: hsl(0 0% 20%);
  }

  .dark .panel-rail-item--active::before {
    background: hsl(var(--primary));
  }

  .panel-rail-item--active:hover {
    background: var(--color-surface);
  }

  .dark .panel-rail-item--active:hover {
    background: hsl(0 0% 20%);
  }

  .panel-rail-item:focus-visible {
    outline: 1px solid hsl(var(--primary));
    outline-offset: -2px;
  }

  /* Content area */
  .panel-content {
    flex: 1;
    min-width: 0;
    overflow-y: auto;
    padding: 36px 48px 36px;
  }

  .panel-columns {
    display: flex;
    gap: 96px;
  }

  @media (max-width: 1023px) {
    .panel-columns {
      gap: 48px;
      flex-wrap: wrap;
    }
  }

  .panel-col {
    min-width: 0;
    flex-shrink: 0;
  }

  /* Column label */
  .panel-col-label {
    font-family: var(--font-ui);
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-muted);
    margin-bottom: 24px;
    white-space: nowrap;
  }

  .dark .panel-col-label {
    color: hsl(var(--muted-foreground));
  }

  .panel-col-links {
    display: flex;
    flex-direction: column;
    gap: 0px;
  }

  /* Individual link */
  .panel-link {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 24px;
    font-family: var(--font-ui);
    font-size: clamp(1.125rem, 1.35vw, 1.25rem);  /* 18px → 20px */
    font-weight: 400;
    line-height: 1.55;
    letter-spacing: -0.03em;
    color: var(--color-text);
    text-decoration: none;
    padding: 4px 0;
    transition: opacity 160ms ease-out;
    white-space: nowrap;
  }

  .dark .panel-link {
    color: hsl(var(--foreground));
  }

  .panel-link:hover {
    opacity: 0.72;
    text-decoration: underline;
    text-underline-offset: 4px;
    text-decoration-thickness: 1px;
  }

  .panel-link:focus-visible {
    outline: 1px solid var(--color-border-strong);
    outline-offset: 3px;
    border-radius: var(--radius-xs);
  }

  .dark .panel-link:focus-visible {
    outline-color: hsl(var(--foreground));
  }

  .panel-link-text {
    min-width: 0;
  }

  .panel-link-count {
    font-family: var(--font-ui);
    font-size: 0.875rem;
    font-variant-numeric: tabular-nums;
    color: var(--color-muted);
    flex-shrink: 0;
    letter-spacing: -0.01em;
  }

  .dark .panel-link-count {
    color: hsl(var(--muted-foreground));
  }

  /* Mobile / tablet: panel becomes full-width, stacked, scrollable */
  @media (max-width: 1023px) {
    /* Shell: no side rounding, no side borders — positioning handled in JS */
    .editorial-panel {
      border-radius: 0;
      border-left: none;
      border-right: none;
      border-bottom: none;
      max-width: 100vw;
      overflow-x: hidden;
    }

    /* Body: stack rail (top) + content (bottom), content scrolls */
    .panel-body {
      flex-direction: column;
      height: auto;
      flex: 1;
      min-height: 0;
    }

    /* Rail: horizontal tab row at the top */
    .panel-rail {
      width: 100%;
      flex-direction: row;
      flex-wrap: nowrap;
      overflow-x: auto;
      overflow-y: hidden;
      border-right: none;
      border-bottom: 1px solid var(--color-border);
      padding: 10px 16px;
      gap: 4px;
      flex-shrink: 0;
      height: auto;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
    }
    .panel-rail::-webkit-scrollbar { display: none; }

    .dark .panel-rail {
      border-bottom-color: hsl(0 0% 18%);
    }

    /* Rail items: horizontal chips */
    .panel-rail-item {
      white-space: nowrap;
      padding: 7px 12px;
      font-size: 0.875rem;    /* 14px */
      flex-shrink: 0;
      width: auto;
    }

    /* Active indicator: bottom underline instead of left bar */
    .panel-rail-item--active::before {
      left: 0;
      right: 0;
      top: auto;
      bottom: -10px;          /* aligns with rail border-bottom */
      width: auto;
      height: 2px;
      transform: none;
      border-radius: 0;
    }

    /* Hide footer controls (theme + lang) — available in mobile header */
    .panel-rail-footer {
      display: none;
    }

    /* Content: scrollable, full-width */
    .panel-content {
      flex: 1;
      min-height: 0;
      overflow-y: auto;
      overflow-x: hidden;
      padding: 28px 20px;
      -webkit-overflow-scrolling: touch;
    }

    /* Columns: wrap to allow narrower viewports */
    .panel-columns {
      flex-wrap: wrap;
      gap: 32px 40px;
    }

    /* Links: allow wrapping on narrow screens */
    .panel-link {
      font-size: 1rem;    /* 16px */
      white-space: normal;
    }
  }
}

/* ─────────────────────────────────────────────
   UTILITIES
───────────────────────────────────────────── */
@layer components {
  /* ── Section eyebrow tag ──────────────────────────────────────────────
     Dark filled pill. Use ONCE per section, directly before the h2.
     Auto-inverts in dark mode (foreground = near-white bg, bg = near-black text).
     Always left-aligned (parent alignment controls centering).
  ──────────────────────────────────────────────────────────────────── */
  /* Navigation-weight pill — 13px, weight 600, UI font */
  .section-tag {
    display: inline-block;
    font-family: var(--font-ui);
    font-size: 0.8125rem;                    /* 13px — nav scale */
    font-weight: 600;
    line-height: 1;
    letter-spacing: -0.01em;
    padding: 0.4rem 1rem;
    border-radius: var(--radius-pill);
    background: hsl(var(--foreground));
    color: hsl(var(--background));
    margin-bottom: 1.25rem;
  }
}

@layer utilities {
  /* Label inside panels / table columns — 11px, uppercase, UI font */
  .label-section {
    font-family: var(--font-ui);
    font-size: 0.6875rem;                    /* 11px */
    font-weight: 600;
    line-height: 1;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    color: hsl(var(--muted-foreground));
  }

  /* Brand font override — logo, wordmark, identity headlines */
  .font-display,
  .font-heading,
  .logo,
  .brand-font,
  .hero-brand-title {
    font-family: var(--font-brand);
  }

  /* Tabular numbers for stats / prices — UI font with tabular variant */
  .num-mono {
    font-family: var(--font-ui);
    font-variant-numeric: tabular-nums;
    letter-spacing: -0.04em;
  }

  /* Gradient text accent */
  .text-gradient {
    background-image: linear-gradient(135deg, hsl(224 76% 72%) 0%, hsl(210 90% 78%) 50%, hsl(224 76% 68%) 100%);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    color: transparent;
  }

  .no-scrollbar {
    scrollbar-width: none;
  }
  .no-scrollbar::-webkit-scrollbar {
    display: none;
  }
}

/* ─────────────────────────────────────────────
   TOOL CARD SHARED PRIMITIVES
   Image panel + responsive catalog grid.
───────────────────────────────────────────── */
@layer components {
  /* ── COVER IMAGE (ToolCardImage) ───────────────────────────────────────────
     Shared by .tc-card and .tce-card — same shape whether a real OG
     screenshot exists or it falls back to a centered logo, so every tool
     card on the site (homepage carousels included) reads as one system.
     Bleeds out of the card's own 24px padding via negative margin. */
  .tc-image {
    position: relative;
    aspect-ratio: 40 / 21;
    margin: -24px -24px 20px -24px;
    border-radius: var(--radius) var(--radius) 0 0;
    overflow: hidden;
    background: var(--color-surface-soft);
    border-bottom: 1px solid var(--color-border-soft);
  }
  .tc-image img {
    position: relative;
    z-index: 1;
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    opacity: 1;
    transition: opacity 180ms ease-out;
  }
  .tc-image.is-loading img {
    opacity: 0;
  }
  .tc-image.is-loading::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 0;
    background: linear-gradient(
      100deg,
      var(--color-surface-soft) 20%,
      color-mix(in srgb, var(--color-surface) 72%, white) 42%,
      var(--color-surface-soft) 64%
    );
    background-size: 220% 100%;
    animation: tc-image-loading 1.2s ease-in-out infinite;
  }
  .tc-image-fallback {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .tc-image--fallback .tc-image-fallback {
    background: var(--color-surface-soft);
  }
  .tc-image--fallback .tc-image-fallback > * {
    box-shadow: 0 0 0 8px var(--color-surface);
  }
  .tc-image.stack-detail-tool-image {
    aspect-ratio: 40 / 21;
    border: 0;
    border-bottom: 1px solid var(--color-border-soft);
    border-radius: var(--radius) var(--radius) 0 0;
    height: auto;
    margin: 0;
  }
  .tc-image.stack-detail-tool-image .tc-image-fallback {
    background: color-mix(in srgb, var(--color-surface-soft) 86%, white);
  }
  .tc-image.stack-detail-tool-image img {
    object-position: center;
  }
  .dark .tc-image { background: hsl(0 0% 14%); border-color: hsl(0 0% 22%); }

  @keyframes tc-image-loading {
    from { background-position: 100% 0; }
    to { background-position: -100% 0; }
  }

  @media (prefers-reduced-motion: reduce) {
    .tc-image.is-loading::before { animation: none; }
  }

  /* .tce-card uses a tighter 16px padding (see .tce-card below) — the
     shared .tc-image negative margin above is sized for .tc-card's 24px,
     so without this override the image bleeds past the card's own edges
     and reads as wider than the card. */
  .tce-card .tc-image {
    margin: -16px -16px 12px -16px;
  }

  /* Compact row variant (ListRow / tc-list-row) — small fixed thumbnail
     instead of a full-bleed panel, row height stays unchanged. */
  .tc-image--row {
    width: 64px;
    height: 44px;
    aspect-ratio: auto;
    margin: 0;
    border-radius: var(--radius-sm);
    border: 1px solid var(--color-border-soft);
    flex-shrink: 0;
  }

  .tc-body-top {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 8px;
  }

  /* ── TYPE LABEL ─────────────────────────────────────────────────────────── */
  .tc-type-label {
    font-family: var(--font-ui);
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-muted);
    line-height: 1;
    padding-top: 2px;
    white-space: nowrap;
  }

  .dark .tc-type-label {
    color: hsl(var(--muted-foreground));
  }

  /* ── CARD BODY ──────────────────────────────────────────────────────────── */
  .tc-card-body {
    flex: 1;
    display: flex;
    flex-direction: column;
  }

  /* Tool name */
  .tc-name {
    font-family: var(--font-ui);
    font-size: clamp(1.375rem, 2.2vw, 1.625rem);   /* 22px → 26px */
    font-weight: 600;
    line-height: 1.05;
    letter-spacing: -0.04em;
    color: var(--color-text);
    margin: 0;
  }

  .dark .tc-name {
    color: hsl(var(--foreground));
  }

  .tc-card--featured .tc-name {
    font-size: clamp(1.625rem, 2.5vw, 2rem);        /* 26px → 32px */
  }

  /* Category */
  .tc-category {
    font-family: var(--font-ui);
    font-size: 0.875rem;                             /* 14px */
    font-weight: 400;
    color: var(--color-muted);
    margin-top: 6px;
    line-height: 1.3;
  }

  .dark .tc-category {
    color: hsl(var(--muted-foreground));
  }

  /* Description */
  .tc-description {
    font-family: var(--font-ui);
    font-size: 0.9375rem;                            /* 15px */
    line-height: 1.45;
    color: var(--color-muted);
    margin-top: 20px;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }

  .dark .tc-description {
    color: hsl(var(--muted-foreground));
  }

  /* Verdict */
  .tc-verdict {
    font-family: var(--font-ui);
    font-size: 0.9375rem;                            /* 15px */
    font-weight: 500;
    color: var(--color-text);
    margin-top: 8px;
    line-height: 1.4;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }

  .dark .tc-verdict {
    color: hsl(var(--foreground));
  }

  /* ── CARD FOOTER ────────────────────────────────────────────────────────── */
  .tc-card-footer {
    margin-top: 24px;
    padding-top: 16px;
    border-top: 1px solid var(--color-border-soft);
    display: flex;
    flex-direction: column;
    gap: 12px;
  }

  .dark .tc-card-footer {
    border-top-color: hsl(0 0% 20%);
  }

  /* ── METADATA ROW ───────────────────────────────────────────────────────── */
  .tc-meta {
    display: flex;
    gap: 24px;
    flex-wrap: wrap;
  }

  .tc-meta-item {
    display: flex;
    flex-direction: column;
    gap: 3px;
  }

  .tc-meta-label {
    font-family: var(--font-ui);
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-muted);
    line-height: 1;
  }

  .dark .tc-meta-label {
    color: hsl(var(--muted-foreground));
  }

  .tc-meta-value {
    font-family: var(--font-ui);
    font-size: 0.8125rem;                            /* 13px */
    font-weight: 500;
    color: var(--color-text);
    line-height: 1.2;
  }

  .dark .tc-meta-value {
    color: hsl(var(--foreground));
  }

  /* ── BADGES ROW ─────────────────────────────────────────────────────────── */
  .tc-badges {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
  }

  .tc-badge {
    display: inline-flex;
    align-items: center;
    background: transparent;
    border: 1px solid var(--color-border);
    color: var(--color-text);
    border-radius: var(--radius-pill);
    padding: 4px 10px;
    font-family: var(--font-ui);
    font-size: 0.75rem;                              /* 12px */
    font-weight: 500;
    letter-spacing: -0.01em;
    line-height: 1;
    white-space: nowrap;
  }

  .dark .tc-badge {
    border-color: hsl(0 0% 28%);
    color: hsl(var(--foreground));
  }

  /* IA badge — blue accent */
  .tc-badge--ia {
    background: hsl(var(--primary) / 0.08);
    border-color: hsl(var(--primary) / 0.3);
    color: hsl(var(--primary));
  }

  .dark .tc-badge--ia {
    background: hsl(var(--primary) / 0.15);
    border-color: hsl(var(--primary) / 0.4);
    color: hsl(var(--primary));
  }

  /* Pick badge — dark fill */
  .tc-badge--pick {
    background: var(--color-text);
    border-color: var(--color-text);
    color: var(--color-surface);
  }

  .dark .tc-badge--pick {
    background: hsl(var(--foreground));
    border-color: hsl(var(--foreground));
    color: hsl(var(--background));
  }

  /* ── CTA LINK ───────────────────────────────────────────────────────────── */
  .tc-cta {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-family: var(--font-ui);
    font-size: 0.875rem;                             /* 14px */
    font-weight: 500;
    color: var(--color-text);
    text-decoration: none;
    letter-spacing: -0.01em;
    transition: gap 160ms ease-out;
  }

  .dark .tc-cta {
    color: hsl(var(--foreground));
  }

  .tc-card:hover .tc-cta,
  .tc-card:focus-visible .tc-cta {
    gap: 7px;    /* arrow moves 3px */
    text-decoration: underline;
    text-underline-offset: 2px;
  }

  /* ── FEATURED CTA BUTTON ────────────────────────────────────────────────── */
  .tc-cta-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: 42px;
    padding: 0 20px;
    background: var(--color-text);
    color: var(--color-surface);
    border: none;
    border-radius: var(--radius-sm);
    font-family: var(--font-ui);
    font-size: 0.875rem;
    font-weight: 500;
    letter-spacing: -0.01em;
    text-decoration: none;
    cursor: pointer;
    transition: background 160ms ease-out, gap 160ms ease-out;
    align-self: flex-start;
  }

  .tc-cta-btn:hover {
    background: var(--color-text-strong);
    gap: 9px;
  }

  .dark .tc-cta-btn {
    background: hsl(var(--foreground));
    color: hsl(var(--background));
  }

  .dark .tc-cta-btn:hover {
    background: hsl(var(--foreground) / 0.85);
  }

  /* ── LIST ROW ───────────────────────────────────────────────────────────── */
  .tc-list-row {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 20px 0;
    border-top: 1px solid var(--color-border);
    text-decoration: none;
    color: var(--color-text);
    cursor: pointer;
    transition: background 160ms ease-out;
  }

  .dark .tc-list-row {
    border-top-color: hsl(0 0% 18%);
    color: hsl(var(--foreground));
  }

  .tc-list-row:hover {
    background: var(--color-surface-soft);
    margin-left: -16px;
    margin-right: -16px;
    padding-left: 16px;
    padding-right: 16px;
    border-radius: var(--radius-xs);
  }

  .dark .tc-list-row:hover {
    background: hsl(0 0% 13%);
  }

  .tc-list-rank {
    font-family: var(--font-ui);
    font-size: 0.875rem;
    font-weight: 500;
    color: var(--color-muted-light);
    width: 28px;
    flex-shrink: 0;
    text-align: right;
    font-variant-numeric: tabular-nums;
    letter-spacing: -0.02em;
  }

  .dark .tc-list-rank {
    color: hsl(0 0% 40%);
  }

  .tc-list-info {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 2px;
  }

  .tc-list-name {
    font-family: var(--font-ui);
    font-size: 1rem;
    font-weight: 600;
    letter-spacing: -0.03em;
    color: var(--color-text);
    line-height: 1.15;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .dark .tc-list-name {
    color: hsl(var(--foreground));
  }

  .tc-list-category {
    font-family: var(--font-ui);
    font-size: 0.8125rem;
    color: var(--color-muted);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .dark .tc-list-category {
    color: hsl(var(--muted-foreground));
  }

  .tc-list-verdict {
    flex: 1;
    min-width: 0;
    font-family: var(--font-ui);
    font-size: 0.8125rem;
    color: var(--color-muted);
    line-height: 1.4;
    display: -webkit-box;
    -webkit-line-clamp: 1;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }

  .dark .tc-list-verdict {
    color: hsl(var(--muted-foreground));
  }

  .tc-list-right {
    display: flex;
    align-items: center;
    gap: 16px;
    flex-shrink: 0;
  }

  .tc-list-cta {
    font-family: var(--font-ui);
    font-size: 0.8125rem;
    font-weight: 500;
    color: var(--color-text);
    text-decoration: none;
    white-space: nowrap;
    transition: gap 160ms ease-out;
    display: inline-flex;
    align-items: center;
    gap: 4px;
  }

  .dark .tc-list-cta {
    color: hsl(var(--foreground));
  }

  .tc-list-row:hover .tc-list-cta {
    gap: 7px;
  }

  /* ── RESPONSIVE GRID ────────────────────────────────────────────────────── */
  .tc-grid {
    display: grid;
    column-gap: 18px;
    row-gap: 36px;
    grid-template-columns: 1fr;
  }

  @media (min-width: 640px) {
    .tc-grid {
      grid-template-columns: repeat(2, 1fr);
    }
  }

  @media (min-width: 1024px) {
    .tc-grid {
      grid-template-columns: repeat(3, 1fr);
    }
  }

  @media (min-width: 1280px) {
    .tc-grid {
      grid-template-columns: repeat(4, 1fr);
    }
  }
}

/* ─────────────────────────────────────────────
   EDITORIAL HERO SYSTEM (eh-*)
   Used by all main page heroes.
   No gradients. No grids. No floating logos.
   Typography + spacing + thin borders only.
───────────────────────────────────────────── */
@layer components {

  /* ── Root shell ──────────────────────────── */
  .eh-root {
    background: var(--color-bg);
    border-bottom: 1px solid var(--color-border);
  }

  .dark .eh-root {
    background: hsl(var(--background));
    border-bottom-color: hsl(var(--border));
  }

  /* ── Container ───────────────────────────── */
  .eh-container {
    max-width: var(--layout-content);   /* 1280px — aligns with gi-* / ga-* body */
    margin: 0 auto;
    padding: 88px 48px 72px;   /* internal pages — was 112/96 */
  }

  @media (max-width: 1023px) {
    .eh-container {
      padding: 64px var(--layout-gutter-tablet) 56px;
    }
  }

  @media (max-width: 639px) {
    .eh-container {
      padding: 52px var(--layout-gutter-mobile) 48px;
    }
  }

  /* ── 2-column layout (when rightModule present) ── */
  .eh-layout-2col {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 300px;
    gap: 64px;
    align-items: start;
  }

  @media (max-width: 1023px) {
    .eh-layout-2col {
      grid-template-columns: 1fr;
      gap: 36px;
    }
    .eh-layout-right { display: none; }
  }

  /* ── Eyebrow ─────────────────────────────── */
  .eh-eyebrow {
    display: block;
    font-family: var(--font-ui);
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-muted);
    margin-bottom: 20px;
    line-height: 1;
  }

  .dark .eh-eyebrow {
    color: hsl(var(--muted-foreground));
  }

  /* ── Badge ───────────────────────────────── */
  .eh-badge {
    display: inline-flex;
    align-items: center;
    height: 30px;
    padding: 0 12px;
    border: 1px solid var(--color-border);
    background: transparent;
    color: var(--color-text);
    font-family: var(--font-ui);
    font-size: 13px;
    font-weight: 500;
    letter-spacing: -0.01em;
    border-radius: var(--radius-pill);
    margin-bottom: 24px;
  }

  .dark .eh-badge {
    border-color: hsl(var(--border));
    color: hsl(var(--foreground));
  }

  /* ── Title ───────────────────────────────── */
  .eh-title {
    font-family: var(--font-ui);
    font-size: clamp(3.5rem, 5.5vw, 6rem);   /* 56px → 96px — was 52→112px */
    font-weight: 600;
    line-height: 0.98;
    letter-spacing: -0.055em;
    color: var(--color-text);
    max-width: 820px;
    margin: 0;
  }

  .dark .eh-title {
    color: hsl(var(--foreground));
  }

  @media (max-width: 639px) {
    .eh-title {
      font-size: clamp(2.75rem, 11vw, 3.5rem);
      letter-spacing: -0.045em;
    }
  }

  /* ── Description ─────────────────────────── */
  .eh-description {
    font-family: var(--font-ui);
    font-size: 19px;
    font-weight: 400;
    line-height: 1.45;
    letter-spacing: -0.015em;
    color: var(--color-muted);
    max-width: 680px;
    margin: 28px 0 0;
  }

  .dark .eh-description {
    color: hsl(var(--muted-foreground));
  }

  /* ── CTA group ───────────────────────────── */
  .eh-cta-group {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-top: 32px;
    flex-wrap: wrap;
  }

  .eh-cta-primary {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: 48px;
    padding: 0 22px;
    background: var(--color-text);
    color: var(--color-surface);
    border: 1px solid var(--color-border-strong);
    border-radius: var(--radius);
    font-family: var(--font-ui);
    font-size: 15px;
    font-weight: 500;
    letter-spacing: -0.02em;
    text-decoration: none;
    cursor: pointer;
    white-space: nowrap;
    transition: background 160ms ease-out, border-color 160ms ease-out;
  }

  .eh-cta-primary:hover {
    background: var(--color-hover-strong);
    border-color: var(--color-hover-strong);
  }

  .dark .eh-cta-primary {
    background: hsl(var(--foreground));
    border-color: hsl(var(--foreground));
    color: hsl(var(--background));
  }

  .eh-cta-secondary {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: 48px;
    padding: 0 22px;
    background: transparent;
    color: var(--color-text);
    border: 1px solid var(--color-border);
    border-radius: var(--radius);
    font-family: var(--font-ui);
    font-size: 15px;
    font-weight: 500;
    letter-spacing: -0.02em;
    text-decoration: none;
    cursor: pointer;
    white-space: nowrap;
    transition: border-color 160ms ease-out, color 160ms ease-out;
  }

  .eh-cta-secondary:hover {
    border-color: var(--color-text);
  }

  .dark .eh-cta-secondary {
    color: hsl(var(--foreground));
    border-color: hsl(var(--border));
  }

  .dark .eh-cta-secondary:hover {
    border-color: hsl(var(--foreground) / 0.6);
  }

  /* ── Metadata bar ────────────────────────── */
  .eh-meta {
    display: flex;
    gap: 40px;
    flex-wrap: wrap;
    border-top: 1px solid var(--color-border);
    margin-top: 48px;
    padding-top: 20px;
  }

  .dark .eh-meta {
    border-top-color: hsl(var(--border));
  }

  .eh-meta-item {
    display: flex;
    flex-direction: column;
    gap: 3px;
  }

  .eh-meta-label {
    font-family: var(--font-ui);
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-muted-light);
    line-height: 1;
  }

  .dark .eh-meta-label {
    color: hsl(var(--muted-foreground) / 0.7);
  }

  .eh-meta-value {
    font-family: var(--font-ui);
    font-size: 13px;
    font-weight: 500;
    color: var(--color-text);
    line-height: 1.2;
  }

  .dark .eh-meta-value {
    color: hsl(var(--foreground));
  }

  /* ── Children slot ───────────────────────── */
  .eh-body {
    margin-top: 32px;
  }

  /* ── Homepage variant — centered ─────────── */
  .eh-root--centered .eh-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    padding-top: 96px;
    padding-bottom: 80px;
  }

  .eh-root--centered .eh-title {
    max-width: 880px;
    font-size: clamp(3.5rem, 6vw, 6.5rem); /* homepage can go a touch larger */
  }

  .eh-root--centered .eh-description {
    max-width: 580px;
  }

  .eh-root--centered .eh-meta {
    justify-content: center;
  }

  /* ── Compact variant (tool detail, category) */
  .eh-root--compact .eh-container {
    padding-top: 64px;
    padding-bottom: 52px;
  }

  .eh-root--compact .eh-title {
    font-size: clamp(2.25rem, 4.5vw, 4rem);
    letter-spacing: -0.05em;
  }
}

/* ─────────────────────────────────────────────
   TOOL CARD EDITORIAL (tce-*)
   Benchmark card — Framer reference design.
   Replaces ToolCard "default" once validated.
───────────────────────────────────────────── */
@layer components {

  /* Squircle corners (corner-shape, see the global rule in @layer base)
     flash back to a plain square for one frame on any style recalc —
     border-color/background transition, hover-triggered transform, etc.
     Every card triggers one of those on hover, so cards opt back out to
     a plain border-radius here; static controls (buttons, tags, CTAs)
     keep the squircle since they only change on the separate, cheaper
     :active press-scale, which doesn't glitch. */
  [class*="-card"],
  [class*="-tile"],
  .tc-image {
    corner-shape: round;
  }

  /* ── Card shell ─────────────────────────────── */
  .tce-card {
    display: flex;
    flex-direction: column;
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: var(--tt-surface-radius-info);
    padding: 16px;
    text-decoration: none;
    color: var(--color-text);
    transition: border-color 180ms ease-out, background 180ms ease-out;
    cursor: default;
  }

  .tce-card:hover {
    border-color: var(--color-text);
    background: var(--color-bg);
  }

  .tce-card:focus-visible {
    outline: 1px solid hsl(var(--primary));
    outline-offset: 2px;
  }

  .tce-card--compact { cursor: pointer; }

  /* Catalog media card: the image is the recognition layer, while the
     identity lives on the page below it. It deliberately has no enclosing
     card shell: hierarchy comes from image, type and spacing, not another
     rectangle in an already dense catalog. */
  .tce-card--media {
    position: relative;
    overflow: visible;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
  }
  .tce-card--media:hover,
  .dark .tce-card--media:hover {
    border-color: transparent;
    background: transparent;
  }
  .tce-card--media:focus-within { border-color: transparent; }
  .tce-card--media .tc-image {
    margin: 0;
    border: 0;
    border-radius: var(--tt-surface-radius-media);
    background: var(--color-surface-soft);
  }
  .tce-card--media .tc-image::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 3;
    border: 1px solid rgba(34, 34, 34, 0.08);
    border-radius: inherit;
    pointer-events: none;
  }
  .tce-card--media .tc-image img {
    transition: transform 220ms ease-out;
  }
  .tce-card--media:hover .tc-image img,
  .tce-card--media:focus-within .tc-image img { transform: scale(1.012); }
  .tce-primary-link {
    position: absolute;
    z-index: 4;
    inset: 0;
    border-radius: var(--tt-surface-radius-media);
  }
  .tce-primary-link:focus-visible {
    outline: 2px solid var(--color-text);
    outline-offset: 3px;
  }
  .tce-cover { position: relative; }

  /* Contextual actions live on the media surface. They stay out of the
     browsing hierarchy until the card is hovered or focused, while coarse
     pointers keep them permanently available. */
  .tce-hover-actions {
    position: absolute;
    z-index: 7;
    right: 14px;
    bottom: 14px;
    display: flex;
    align-items: center;
    gap: 9px;
    opacity: 0;
    pointer-events: none;
    transform: translateY(8px);
    transition: opacity 160ms ease-out, transform 180ms cubic-bezier(.22,1,.36,1);
  }
  .tce-card--media:hover .tce-hover-actions,
  .tce-card--media:focus-within .tce-hover-actions {
    opacity: 1;
    pointer-events: auto;
    transform: translateY(0);
  }
  @media (hover: none), (pointer: coarse) {
    .tce-hover-actions { opacity: 1; pointer-events: auto; transform: none; }
  }
  .tce-cover::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 5;
    border-radius: var(--tt-surface-radius-media);
    background: linear-gradient(180deg, transparent 48%, rgba(18, 18, 16, .5) 100%);
    opacity: 0;
    pointer-events: none;
    transition: opacity 160ms ease-out;
  }
  .tce-card--media:hover .tce-cover::after,
  .tce-card--media:focus-within .tce-cover::after { opacity: 1; }
  .tce-hover-action,
  .tce-hover-actions .pin-tool-button {
    position: relative;
    inset: auto;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 46px;
    min-width: 46px;
    height: 46px;
    min-height: 46px;
    padding: 0;
    border: 1px solid rgba(255,255,255,.72);
    border-radius: var(--radius-circle);
    background: rgba(255,255,255,.94);
    color: #222;
    box-shadow: 0 7px 22px rgba(18,18,16,.18);
    text-decoration: none;
    transform: none;
    backdrop-filter: blur(10px);
  }
  .tce-hover-action:hover,
  .tce-hover-action:focus-visible,
  .tce-hover-actions .pin-tool-button:hover,
  .tce-hover-actions .pin-tool-button:focus-visible,
  .tce-hover-actions .pin-tool-button--active {
    background: #fff;
    color: #111;
    outline: 2px solid #fff;
    outline-offset: 2px;
    transform: translateY(-2px);
  }
  /* The icon alone doesn't say what it does ("bookmark" reads generically,
     not specifically "add to my stack") — surface each button's own
     title as a fast custom tooltip instead of waiting on the native
     ~1s browser delay. Reuses the existing title attr, no new prop. */
  .tce-hover-action::after,
  .tce-hover-actions .pin-tool-button::after {
    content: attr(title);
    position: absolute;
    bottom: calc(100% + 9px);
    left: 50%;
    padding: 5px 10px;
    border-radius: var(--radius-pill);
    background: var(--color-text);
    color: var(--color-surface);
    font-family: var(--font-ui);
    font-size: 11px;
    font-weight: 600;
    white-space: nowrap;
    opacity: 0;
    pointer-events: none;
    transform: translate(-50%, 4px);
    transition: opacity 140ms ease-out, transform 140ms ease-out;
  }
  .tce-hover-action:hover::after,
  .tce-hover-action:focus-visible::after,
  .tce-hover-actions .pin-tool-button:hover::after,
  .tce-hover-actions .pin-tool-button:focus-visible::after {
    opacity: 1;
    transform: translate(-50%, 0);
  }
  .tce-hover-actions .pin-tool-button--active {
    background: #f3d7ff;
    border-color: #f3d7ff;
  }

  .dark .tce-card {
    background: hsl(var(--card));
    border-color: hsl(var(--border));
    color: hsl(var(--foreground));
  }

  .dark .tce-card--media {
    background: transparent;
    border-color: transparent;
  }

  .dark .tce-card:hover {
    border-color: hsl(var(--foreground) / 0.6);
    background: hsl(var(--secondary));
  }

  /* ── Body ───────────────────────────────────── */
  .tce-body {
    flex: 1;
  }
  .tce-card--media .tce-body {
    padding: 8px 2px 0;
  }

  .tce-identity-row {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 7px;
  }
  .tce-identity-link {
    display: grid;
    grid-template-columns: 24px minmax(0, 1fr);
    align-items: center;
    min-width: 0;
    gap: 7px;
    color: inherit;
    text-decoration: none;
  }
  .tce-logo {
    border-radius: var(--radius-circle) !important;
    background: var(--color-surface) !important;
  }
  .tce-identity-copy {
    display: flex;
    align-items: baseline;
    min-width: 0;
    gap: 6px;
    overflow: hidden;
  }

  /* Name + price share one row — price is a small trailing label, not a
     second headline, so it doesn't compete with the tool name. */
  .tce-title-row {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 8px;
  }

  .tce-name {
    font-family: var(--font-ui);
    font-size: 15px;
    font-weight: 600;
    line-height: 1.25;
    letter-spacing: -0.015em;
    color: var(--color-text);
    margin: 0;
    min-width: 0;
    display: block;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .tce-card--media:hover .tce-name,
  .tce-card--media:focus-within .tce-name {
    text-decoration: underline;
    text-decoration-thickness: 1px;
    text-underline-offset: 3px;
  }

  .dark .tce-name {
    color: hsl(var(--foreground));
  }

  .tce-price {
    flex-shrink: 0;
    font-family: var(--font-ui);
    font-size: 12px;
    font-weight: 600;
    letter-spacing: -0.01em;
    color: var(--color-muted);
  }

  .dark .tce-price {
    color: hsl(var(--muted-foreground));
  }

  .tce-category {
    display: flex;
    align-items: center;
    min-width: 0;
    font-family: var(--font-ui);
    font-size: 13px;
    font-weight: 400;
    line-height: 1.25;
    letter-spacing: 0;
    color: var(--color-muted);
    margin: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .tce-category::before {
    content: "·";
    flex: 0 0 auto;
    margin-right: 6px;
    color: var(--color-muted-light);
  }

  .dark .tce-category {
    color: hsl(var(--muted-foreground));
  }

  /* Overlay layer shared by factual chips and optional hover content. */
  .tc-image-overlay {
    position: absolute;
    inset: 0;
    z-index: 2;
    display: flex;
    flex-direction: column;
    gap: 8px;
    transition: opacity 160ms ease-out;
    pointer-events: none;
  }

  .tc-image-overlay.tc-image-overlay--static {
    justify-content: flex-start;
    padding: 12px;
    background: transparent;
    opacity: 1;
  }
  .tc-image-overlay.tc-image-overlay--hover {
    justify-content: flex-end;
    padding: 14px;
    background: rgba(18, 18, 16, 0.78);
    opacity: 0;
  }
  .tce-cover-meta {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 8px;
    width: 100%;
  }
  .tce-cover-price {
    display: inline-flex;
    align-items: center;
    min-height: 22px;
    padding: 0 7px;
    border-radius: var(--radius-pill);
    border: 1px solid rgba(34, 34, 34, 0.12);
    background: rgba(255, 255, 255, 0.88);
    color: #222;
    font-family: var(--font-ui);
    font-size: 10px;
    font-weight: 600;
    line-height: 1;
    box-shadow: none;
    backdrop-filter: blur(8px);
  }
  .tce-cover-price { margin-left: auto; }

  .tce-card:hover .tc-image-overlay--hover,
  .tce-card:focus-within .tc-image-overlay--hover {
    opacity: 1;
  }

  @media (pointer: coarse) {
    .tce-hover-actions {
      opacity: 1;
      pointer-events: auto;
      transform: none;
    }
    .tce-cover::after { opacity: .72; }
    .tce-hover-action,
    .tce-hover-actions .pin-tool-button {
      width: 42px;
      min-width: 42px;
      height: 42px;
      min-height: 42px;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .tce-card,
    .tce-card--media .tc-image img,
    .tc-image-overlay,
    .tcc-card {
      transition-duration: 0ms;
    }

    .tce-card--media:hover .tc-image img,
    .tce-card--media:focus-within .tc-image img {
      transform: none;
    }
  }
}

/* ─────────────────────────────────────────────
   TOOL CARD COMPACT (tcc-*)
   Dense discovery row for search and constrained lists.
───────────────────────────────────────────── */
@layer components {
  .tcc-card {
    position: relative;
    box-sizing: border-box;
    display: grid;
    grid-template-columns: 36px minmax(0, 1fr) auto auto 36px;
    align-items: center;
    gap: 12px;
    height: 66px;
    min-height: 66px;
    padding: 13px 12px 13px 14px;
    border: 1px solid var(--color-border-soft);
    border-radius: var(--tt-surface-radius-info);
    background: var(--color-surface);
    transition: border-color 160ms ease-out, background 160ms ease-out;
  }
  .tcc-card:hover,
  .tcc-card:focus-within {
    border-color: var(--color-border);
    background: color-mix(in srgb, var(--color-surface-soft) 42%, var(--color-surface));
  }
  .tcc-primary-link {
    position: absolute;
    z-index: 1;
    inset: 0;
    border-radius: inherit;
  }
  .tcc-primary-link:focus-visible,
  .tcc-explore:focus-visible {
    outline: 2px solid var(--color-text);
    outline-offset: 2px;
  }
  .tcc-logo,
  .tcc-copy,
  .tcc-price,
  .tcc-arrow { pointer-events: none; }
  .tcc-copy { min-width: 0; }
  .tcc-name {
    margin: 0;
    overflow: hidden;
    color: var(--color-text);
    font-family: var(--font-ui);
    font-size: 14px;
    font-weight: 650;
    line-height: 1.25;
    letter-spacing: -0.012em;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .tcc-description {
    margin: 2px 0 0;
    overflow: hidden;
    color: var(--color-muted);
    font-family: var(--font-ui);
    font-size: 12px;
    line-height: 1.3;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .tcc-price {
    color: var(--color-muted);
    font-family: var(--font-ui);
    font-size: 12px;
    font-weight: 600;
    white-space: nowrap;
  }
  .tcc-arrow {
    color: var(--color-muted-light);
    transition: transform 160ms ease-out, color 160ms ease-out;
  }
  .tcc-card:hover .tcc-arrow,
  .tcc-card:focus-within .tcc-arrow {
    color: var(--color-text);
    transform: translateX(2px);
  }
  .tcc-explore {
    position: relative;
    z-index: 2;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-pill);
    background: var(--color-surface);
    color: var(--color-muted);
  }
  .tcc-explore:hover {
    border-color: var(--color-text);
    color: var(--color-text);
  }
  @media (max-width: 560px) {
    .tcc-card {
      grid-template-columns: 36px minmax(0, 1fr) 44px;
      gap: 10px;
    }
    .tcc-price,
    .tcc-arrow { display: none; }
    .tcc-explore {
      width: 44px;
      height: 44px;
    }
  }
}

/* ─────────────────────────────────────────────
   SEARCH PAGE (sp-*)
   One constrained editorial column. Horizontal tabs are the only element
   allowed to scroll; result cards always shrink to the viewport.
───────────────────────────────────────────── */
@layer components {
  .sp-page {
    width: min(100%, 768px);
    min-width: 0;
    margin: 0 auto;
    padding: var(--space-2xl) var(--space-md) var(--space-3xl);
    font-family: var(--font-ui);
  }
  .sp-search-field {
    position: relative;
    margin-bottom: var(--space-xl);
  }
  .sp-search-icon {
    position: absolute;
    left: 16px;
    top: 50%;
    width: 20px;
    height: 20px;
    color: var(--color-muted-light);
    pointer-events: none;
    transform: translateY(-50%);
  }
  .sp-search-input {
    width: 100%;
    min-height: 56px;
    padding: 0 48px;
    border: 1px solid var(--color-border);
    border-radius: var(--tt-radius-md);
    outline: none;
    background: var(--color-surface);
    color: var(--color-text);
    font-family: var(--font-ui);
    font-size: var(--tt-size-body);
    font-weight: 550;
    transition: border-color 150ms ease, box-shadow 150ms ease;
  }
  .sp-search-input::placeholder { color: var(--color-muted-light); font-weight: 400; }
  .sp-search-input:focus {
    border-color: var(--color-text);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--color-text) 10%, transparent);
  }
  .sp-search-clear {
    position: absolute;
    right: 8px;
    top: 50%;
    display: inline-flex;
    width: 44px;
    height: 44px;
    align-items: center;
    justify-content: center;
    padding: 0;
    border: 0;
    border-radius: var(--radius-pill);
    background: transparent;
    color: var(--color-muted);
    cursor: pointer;
    transform: translateY(-50%);
  }
  .sp-search-clear:hover { background: var(--color-surface-soft); color: var(--color-text); }
  .sp-query-hint,
  .sp-empty-query { color: var(--color-muted); font-size: 14px; text-align: center; }
  .sp-empty-query > p { margin: 0 0 var(--space-lg); }
  .sp-suggestions { display: flex; flex-wrap: wrap; justify-content: center; gap: var(--space-xs); }
  .sp-suggestion,
  .sp-tab {
    min-height: 40px;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-pill);
    background: var(--color-surface);
    color: var(--color-text);
    font: 600 14px/1 var(--font-ui);
    cursor: pointer;
  }
  .sp-suggestion { padding: 0 16px; }
  .sp-suggestion:hover { border-color: var(--color-text); }
  .sp-results-header { display: flex; align-items: center; margin-bottom: var(--space-lg); }
  .sp-results-header p { margin: 0; color: var(--color-muted); font-size: 14px; }
  .sp-results-header strong { color: var(--color-text); font-weight: 650; }
  .sp-tabs {
    display: flex;
    max-width: 100%;
    gap: 6px;
    margin: 0 0 var(--space-lg);
    padding: 0 0 4px;
    overflow-x: auto;
    overscroll-behavior-inline: contain;
    scrollbar-width: none;
  }
  .sp-tabs::-webkit-scrollbar { display: none; }
  .sp-tab {
    display: inline-flex;
    flex: 0 0 auto;
    align-items: center;
    gap: 6px;
    padding: 0 14px;
    border-color: transparent;
    background: var(--color-surface-soft);
    color: var(--color-muted);
  }
  .sp-tab:hover { color: var(--color-text); }
  .sp-tab.is-active { background: var(--color-text); color: var(--color-bg); }
  .sp-tab-count {
    display: inline-flex;
    min-width: 20px;
    min-height: 20px;
    align-items: center;
    justify-content: center;
    padding: 0 5px;
    border-radius: var(--radius-pill);
    background: var(--color-border);
    color: var(--color-muted);
    font-size: 11px;
    font-weight: 700;
  }
  .sp-tab.is-active .sp-tab-count { background: rgba(255, 255, 255, 0.18); color: inherit; }
  .sp-no-results {
    padding: var(--space-2xl) var(--space-lg);
    border: 1px solid var(--color-border);
    border-radius: var(--tt-radius-md);
    background: var(--color-surface);
    color: var(--color-muted-light);
    text-align: center;
  }
  .sp-no-results > svg { margin: 0 auto var(--space-sm); }
  .sp-no-results-title { margin: 0; color: var(--color-text); font-weight: 650; }
  .sp-no-results-copy { margin: 6px 0 0; color: var(--color-muted); font-size: 14px; }
  .sp-no-results-link {
    display: inline-flex;
    min-height: 44px;
    align-items: center;
    gap: 6px;
    margin-top: var(--space-md);
    padding: 0 16px;
    border-radius: var(--radius);
    background: var(--color-text);
    color: var(--color-bg);
    font-size: 14px;
    font-weight: 650;
    text-decoration: none;
  }
  .sp-result-groups { display: grid; gap: var(--space-xl); min-width: 0; }
  .sp-result-groups section,
  .sp-tool-results,
  .sp-category-results,
  .sp-guide-results { min-width: 0; }
  .sp-tool-results,
  .sp-guide-results { display: grid; gap: var(--space-xs); }
  .sp-category-results { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-xs); }
  .sp-section-header {
    display: flex;
    min-height: 32px;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-sm);
    margin-bottom: var(--space-sm);
  }
  .sp-section-title { display: flex; min-width: 0; align-items: center; gap: var(--space-xs); color: var(--color-text); font-size: 14px; font-weight: 650; }
  .sp-section-title > span:first-child { display: inline-flex; color: var(--color-muted); }
  .sp-section-count { padding: 3px 8px; border-radius: var(--radius-pill); background: var(--color-surface-soft); color: var(--color-muted); font-size: 11px; font-weight: 600; }
  .sp-section-more {
    min-height: 40px;
    flex: 0 0 auto;
    padding: 0 4px;
    border: 0;
    background: transparent;
    color: var(--color-text);
    font: 600 12px/1 var(--font-ui);
    cursor: pointer;
  }
  .sp-category-card,
  .sp-guide-card {
    display: flex;
    min-width: 0;
    align-items: center;
    gap: var(--space-sm);
    padding: 13px 14px;
    border: 1px solid var(--color-border-soft);
    border-radius: var(--tt-surface-radius-info);
    background: var(--color-surface);
    color: inherit;
    text-decoration: none;
    transition: border-color 160ms ease, background 160ms ease;
  }
  .sp-guide-card { align-items: flex-start; }
  .sp-category-card:hover,
  .sp-guide-card:hover { border-color: var(--color-border); background: color-mix(in srgb, var(--color-surface-soft) 42%, var(--color-surface)); }
  .sp-result-icon { display: inline-flex; width: 36px; height: 36px; flex: 0 0 36px; align-items: center; justify-content: center; border-radius: var(--radius); background: var(--color-surface-soft); color: var(--color-text); }
  .sp-result-copy { min-width: 0; flex: 1 1 auto; }
  .sp-result-name { margin: 0; color: var(--color-text); font-size: 14px; font-weight: 650; line-height: 1.3; }
  .sp-result-description { margin: 2px 0 0; overflow: hidden; color: var(--color-muted); font-size: 12px; text-overflow: ellipsis; white-space: nowrap; }
  .sp-guide-excerpt { display: -webkit-box; margin: 4px 0 0; overflow: hidden; color: var(--color-muted); font-size: 12px; line-height: 1.45; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
  .sp-guide-meta { margin: 6px 0 0; color: var(--color-muted-light); font-size: 11px; }
  .sp-result-arrow { flex: 0 0 auto; color: var(--color-muted-light); transition: color 160ms ease, transform 160ms ease; }
  .sp-category-card:hover .sp-result-arrow,
  .sp-guide-card:hover .sp-result-arrow { color: var(--color-text); transform: translateX(2px); }

  @media (max-width: 560px) {
    .sp-page { padding: var(--space-xl) var(--space-md) var(--space-3xl); }
    .sp-search-field { margin-bottom: var(--space-lg); }
    .sp-search-input { min-height: 52px; }
    .sp-results-header { margin-bottom: var(--space-md); }
    .sp-category-results { grid-template-columns: minmax(0, 1fr); }
    .sp-category-card,
    .sp-guide-card { width: 100%; }
  }
}

/* ─────────────────────────────────────────────
   EDITORIAL SECTION SYSTEM (es-*)
   Replaces old SaaS section patterns.
   No gradients. No blue backgrounds. No soft shadows.
   Border + typography + tight grid only.
───────────────────────────────────────────── */
@layer components {

  .es-section {
    background: var(--color-bg);
    border-top: 0;
    padding: 80px 0;
  }
  .es-section--white {
    background: var(--color-surface);
  }
  .es-section--band {
    background: var(--color-surface-soft);
    border-top: 0;
    border-bottom: 0;
    padding: 56px 0;
  }
  @media (max-width: 768px) {
    .es-section { padding: 56px 0; }
  }
  .es-container {
    max-width: 1440px;
    padding: 0 48px;
    margin: 0 auto;
  }
  @media (max-width: 768px) {
    .es-container { padding: 0 20px; }
  }
  .es-header {
    display: grid;
    grid-template-columns: 1fr auto;
    gap: 48px;
    align-items: end;
    margin-bottom: 40px;
  }
  @media (max-width: 640px) {
    .es-header { grid-template-columns: 1fr; gap: 16px; }
  }
  .es-eyebrow {
    display: block;
    font-family: var(--font-ui);
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-muted);
    margin-bottom: 8px;
  }
  .es-title {
    font-family: var(--font-ui);
    font-size: var(--tt-size-section-h);
    font-weight: 620;
    line-height: 1.08;
    letter-spacing: -0.035em;
    color: var(--color-text);
    max-width: 900px;
  }
  .es-description {
    font-family: var(--font-ui);
    font-size: var(--tt-size-section-intro);
    line-height: 1.45;
    letter-spacing: -0.025em;
    color: var(--color-muted);
    max-width: 620px;
    margin-top: 8px;
  }
  .es-cta-link {
    flex-shrink: 0;
  }

  /* Canonical secondary action used at the edge of editorial section heads. */
  .tt-section-action {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    color: var(--color-text);
    font-family: var(--font-ui);
    font-size: 14px;
    font-weight: 600;
    line-height: 1.2;
    text-decoration: none;
    white-space: nowrap;
  }
  .tt-section-action svg {
    width: 15px;
    height: 15px;
    flex: 0 0 auto;
    stroke-width: 2;
    transition: transform 160ms ease-out;
  }
  .tt-section-action:hover svg,
  .tt-section-action:focus-visible svg {
    transform: translateX(3px);
  }
  .tt-section-action:focus-visible {
    border-radius: var(--radius-xs);
    outline: 2px solid currentColor;
    outline-offset: 4px;
  }

  /* Shared controls for every public editorial carousel. */
  .tt-carousel-controls {
    display: inline-flex;
    align-items: center;
    gap: 6px;
  }
  .tt-carousel-arrow {
    display: inline-grid;
    width: 36px;
    height: 36px;
    padding: 0;
    place-items: center;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-circle);
    background: var(--color-surface);
    color: var(--color-text);
    cursor: pointer;
    transition: background 140ms ease-out, border-color 140ms ease-out, color 140ms ease-out;
  }
  .tt-carousel-arrow svg {
    width: 16px;
    height: 16px;
    stroke-width: 1.8;
  }
  .tt-carousel-arrow:hover:not(:disabled) {
    border-color: var(--color-text);
    background: var(--color-surface-soft);
  }
  .tt-carousel-arrow:focus-visible {
    outline: 2px solid var(--color-text);
    outline-offset: 3px;
  }
  .tt-carousel-arrow:disabled {
    opacity: 0.28;
    cursor: default;
  }
  .tt-carousel-pagination {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 24px;
    margin-top: 14px;
  }
  .tt-carousel-pagination button {
    display: grid;
    width: 24px;
    height: 24px;
    padding: 0;
    place-items: center;
    border: 0;
    background: transparent;
    cursor: pointer;
  }
  .tt-carousel-pagination button::before {
    width: 6px;
    height: 6px;
    border-radius: var(--radius-pill);
    background: var(--color-border);
    content: "";
    transition: width 160ms ease-out, background 160ms ease-out;
  }
  .tt-carousel-pagination button.is-active::before {
    width: 20px;
    background: var(--color-text);
  }
  .tt-carousel-pagination button:focus-visible {
    border-radius: var(--radius-circle);
    outline: 2px solid var(--color-text);
    outline-offset: 1px;
  }

/* ─────────────────────────────────────────────
   EDITORIAL CARD BASE (ec-*)
   All content cards: guides, stacks, comparisons, categories.
   White surface. Thin border. Black hover. No shadow.
───────────────────────────────────────────── */

  .ec-card {
    background: var(--color-surface);
    border: 1px solid var(--color-border-soft);
    border-radius: var(--tt-surface-radius-info);
    padding: 24px;
    transition: border-color 160ms ease-out, background 160ms ease-out;
    display: flex;
    flex-direction: column;
    text-decoration: none;
    color: var(--color-text);
    cursor: pointer;
  }
  .ec-card:hover {
    border-color: var(--color-border);
    background: var(--color-surface);
  }
  .ec-label {
    font-family: var(--font-ui);
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-muted);
    margin-bottom: 18px;
    display: block;
  }
  .ec-card .ec-title--guide { font-size: clamp(1.0625rem, 1.6vw, 1.3rem); }
  .ec-card .ec-text--guide { display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
  .ec-title {
    font-family: var(--font-brand);
    font-size: 24px;
    font-weight: 600;
    line-height: 1.05;
    letter-spacing: -0.045em;
    color: var(--color-text);
  }
  .ec-text {
    font-family: var(--font-ui);
    font-size: 15px;
    line-height: 1.45;
    letter-spacing: -0.02em;
    color: var(--color-muted);
    margin-top: 14px;
    flex: 1;
  }
  .ec-divider {
    border: none;
    border-top: 1px solid var(--color-border-soft);
    margin: 20px 0 0;
  }
  .ec-cta {
    font-family: var(--font-ui);
    font-size: 14px;
    font-weight: 500;
    color: var(--color-text);
    margin-top: 20px;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    flex-shrink: 0;
  }
  .ec-cta-arrow {
    display: inline-block;
    transition: transform 160ms ease-out;
  }
  .ec-card:hover .ec-cta { text-decoration: underline; text-underline-offset: 3px; }
  .ec-card:hover .ec-cta-arrow { transform: translateX(3px); }
}

/* ── Tool Detail page — td-* system ──────────────────────────────────────── */
@layer components {

  /* Page container */
  .td-container {
    max-width: var(--layout-max);   /* 1440px */
    margin-left: auto;
    margin-right: auto;
    padding-left: var(--layout-gutter);
    padding-right: var(--layout-gutter);
  }
  @media (min-width: 1200px) {
    .td-tool-page .td-container { padding-left: 32px; }
  }
  @media (max-width: 768px) {
    .td-container { padding-left: var(--layout-gutter-mobile); padding-right: var(--layout-gutter-mobile); }
  }

  /* Two-column body grid: content | sidebar */
  .td-body-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 300px;
    gap: 36px;
    align-items: start;
    padding-top: 0;
    padding-bottom: 80px;
  }
  .td-page-breadcrumb {
    padding-top: 40px;
    margin-bottom: 20px;
  }

  .td-main {
    --td-chapter-gap: clamp(52px, 6vw, 72px);
    --td-block-gap: clamp(32px, 4vw, 44px);
    min-width: 0;
    display: flow-root;
  }
  @media (max-width: 1350px) {
    .td-body-grid {
      grid-template-columns: minmax(0, 1fr);
      gap: 40px;
    }
  }

  /* Sticky sidebar — sticky must live on the GRID ITEM itself */
  .td-sidebar-desktop {
    position: sticky;
    top: 12px;
    align-self: start;      /* prevent grid stretch from killing sticky */
    height: fit-content;
    max-height: calc(100vh - var(--navbar-h, 68px) - 24px);
    overflow-y: auto;
    overscroll-behavior: contain;
    scrollbar-width: none;
  }
  .td-sidebar-desktop::-webkit-scrollbar { display: none; }
  @media (max-width: 1350px) {
    .td-sidebar-desktop {
      position: static;
      display: none;
    }
  }
  /* Below the wide desktop split, the decision card becomes part of the
     reading flow and appears before the local navigation. */
  .td-sidebar-mobile { margin-bottom: 32px; }
  .td-sidebar-mobile .td-decision-card { padding: 0; border: 0; gap: 16px; }
  .td-sidebar-mobile .td-decision-similar { display: none; }
  .td-sidebar-mobile .td-decision-utility-actions { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .td-sidebar-mobile .td-decision-share { margin-top: 0; }
  .td-opening-verdict { margin: 16px 0 0; }
  .td-scroll-body > .td-hero-media { margin: 0 0 28px; }
  .td-reading-actions { margin-top: 40px; padding-top: 24px; border-top: 1px solid var(--color-border); }
  .td-reading-actions h2 { margin-bottom: 16px; font-size: 22px; }
  .td-hero.is-compact .td-opening-verdict { display: none; }
  @media (min-width: 1351px) {
    .td-sidebar-mobile { display: none; }
  }
  /* td-sidebar is now just a semantic wrapper — no position override */

  /* The opening identity stays open; the editorial verdict owns the surface. */
  .td-tool-page .td-hero:not(.is-compact) .td-hero-card { background: transparent; overflow: visible; }
  .td-tool-page .td-hero:not(.is-compact) .td-hero-heading { padding: 16px 0 28px; }
  .td-tool-page .td-hero:not(.is-compact) .td-hero-identity-grid { grid-template-columns: 72px minmax(0, 1fr); align-items: start; gap: 20px 24px; }
  .td-tool-page .td-hero:not(.is-compact) .td-hero-actions { grid-column: 2; }
  .td-tool-page .td-hero:not(.is-compact) .td-hero-h1 { font-size: var(--tt-size-page-title); line-height: 1.05; letter-spacing: -.04em; }
  .td-tool-page .td-hero:not(.is-compact) .td-hero-desc { max-width: 48ch; margin-top: 8px; font-size: var(--tt-size-section-intro); }
  .td-decision-conclusion { grid-column: 1 / -1; margin: 12px 0 0; padding-top: 12px; border-top: 1px solid var(--color-border); font: 400 var(--tt-size-card-body)/1.55 var(--font-ui); color: var(--color-text); text-wrap: pretty; }
  .td-tool-page .td-tool-subnav { border-bottom: 1px solid var(--color-border); padding-bottom: 16px; }
  @media (max-width: 640px) {
    .td-tool-page .td-hero:not(.is-compact) .td-hero-identity-grid { grid-template-columns: 52px minmax(0, 1fr); gap: 16px; }
    .td-tool-page .td-hero:not(.is-compact) .td-hero-name-block { display: contents; }
    .td-tool-page .td-hero:not(.is-compact) .td-hero-h1 { align-self: center; font-size: 36px; overflow-wrap: anywhere; }
    .td-tool-page .td-hero:not(.is-compact) .td-hero-desc,
    .td-tool-page .td-hero:not(.is-compact) .td-hero-actions { grid-column: 1 / -1; margin: 0; }
  }

  /* Reading scale: chapter / functional subtitle / prose / metadata. */
  .td-tool-page :is(.td-title, .td-editorial-intro-title, .td-overview-title) { text-wrap: balance; max-width: 32ch; }
  .td-tool-page :is(.td-analysis-lead, .td-analysis-paragraph, .td-editorial-intro-copy) { max-width: 65ch; }
  .td-tool-page .td-analysis-paragraph { line-height: 1.65; letter-spacing: 0; }
  .td-tool-page .td-analysis-lead { line-height: 1.5; letter-spacing: -.015em; }
  .td-tool-page .td-subtitle { font-size: 22px; line-height: 1.3; font-weight: 600; }
  .td-tool-page :is(.td-eyebrow, .td-editorial-facts h3) { font-size: 12px; line-height: 1.5; letter-spacing: .06em; }
  .td-tool-page :is(.td-title, .td-editorial-intro-title) { margin-bottom: 20px; }
  .td-tool-page .td-editorial-intro-head { gap: 8px; margin-bottom: 24px; }
  .td-tool-page .td-editorial-intro-head .td-editorial-intro-title { margin-bottom: 0; }
  .td-tool-page .td-reading-actions h2 { line-height: 1.3; }
  .td-tool-page :is(button, a, summary):focus-visible { outline: 2px solid hsl(var(--primary)); outline-offset: 4px; }
  .td-faq-heading { margin-bottom: 24px; }
  .td-faq-heading > p { font: 400 var(--tt-size-body)/1.6 var(--font-ui); color: var(--color-text); max-width: 60ch; }
  .td-faq-list details { border-bottom: 1px solid var(--color-border); }
  .td-faq-list details:first-child { border-top: 1px solid var(--color-border); }
  .td-faq-list summary { padding: 20px 0; font: 600 var(--tt-size-body)/1.5 var(--font-ui); color: var(--color-text); cursor: pointer; }
  .td-faq-list details > p { padding: 0 0 24px; margin: 0; max-width: 65ch; font: 400 var(--tt-size-body)/1.65 var(--font-ui); color: var(--color-text); }
  @media (max-width: 640px) {
    .td-tool-page .td-subtitle { font-size: 20px; }
    .td-tool-page .td-main { --td-chapter-gap: 48px; --td-block-gap: 28px; }
  }

  /* Hero — single column: identity + positioning only (legacy, unused) */

  /* ── Hero CARD — Ma-stack inspector gabarit (.stack-tool-profile-hero):
     a bordered rounded card, cover image on top, heading below. Cleaner and
     far more scannable than the giant poster name it replaces. ── */
  .td-hero-card {
    border: 0;
    border-radius: var(--tt-surface-radius-panel);
    overflow: hidden;
    background: var(--color-surface-soft);
    box-shadow: none;
  }
  /* Keep the identity visible while reading on both tablet and desktop.
     768px and below retain the simpler non-sticky mobile flow. */
  @media (min-width: 769px) {
    .td-page-grid { --td-hero-compact-h: 80px; }
    .td-page-grid .td-hero {
      position: sticky;
      top: 12px;
      z-index: 40;
      isolation: isolate;
      transform-origin: top center;
      transition: height 260ms cubic-bezier(0.22, 1, 0.36, 1), top 260ms cubic-bezier(0.22, 1, 0.36, 1);
    }
    .td-scroll-body {
      min-width: 0;
      padding-top: 0;
      transition: padding-top 260ms cubic-bezier(0.22, 1, 0.36, 1);
    }
    .td-hero.is-compact + .td-scroll-body {
      padding-top: calc(var(--td-hero-compact-h) + 12px + 8px);
    }
    .td-hero-card {
      position: static;
      max-height: 680px;
      transition:
        grid-template-columns 260ms cubic-bezier(0.22, 1, 0.36, 1),
        min-height 260ms cubic-bezier(0.22, 1, 0.36, 1),
        max-height 260ms cubic-bezier(0.22, 1, 0.36, 1),
        border-radius 260ms cubic-bezier(0.22, 1, 0.36, 1),
        box-shadow 260ms cubic-bezier(0.22, 1, 0.36, 1);
    }
    .td-hero-cover,
    .td-hero-media,
    .td-hero-heading,
    .td-hero-name-block,
    .td-hero-cat,
    .td-hero-h1,
    .td-hero-desc {
      transition:
        width 260ms cubic-bezier(0.22, 1, 0.36, 1),
        height 260ms cubic-bezier(0.22, 1, 0.36, 1),
        min-height 260ms cubic-bezier(0.22, 1, 0.36, 1),
        max-height 220ms ease-out,
        padding 260ms cubic-bezier(0.22, 1, 0.36, 1),
        font-size 220ms ease-out,
        opacity 150ms ease-out,
        transform 260ms cubic-bezier(0.22, 1, 0.36, 1),
        margin-top 260ms cubic-bezier(0.22, 1, 0.36, 1);
    }
    .td-hero.is-compact { pointer-events: none; }
    .td-hero.is-compact::before {
      content: "";
      position: absolute;
      top: -12px;
      right: -1px;
      bottom: -12px;
      left: -1px;
      z-index: -1;
      background: var(--color-bg);
    }
    .td-hero.is-compact .td-hero-card { pointer-events: auto; }
    .td-hero.is-compact .td-hero-card {
      display: block;
      min-height: var(--td-hero-compact-h);
      max-height: var(--td-hero-compact-h);
      border-radius: var(--radius-lg);
      border: 1px solid var(--color-border);
      box-shadow: none;
    }
    .td-hero.is-compact .td-hero-media {
      max-height: 0;
      margin-top: 0;
      opacity: 0;
      overflow: hidden;
      pointer-events: none;
    }
    .td-hero.is-compact .td-hero-heading {
      min-width: 0;
      min-height: var(--td-hero-compact-h);
      height: var(--td-hero-compact-h);
      padding: 12px 20px;
      box-sizing: border-box;
    }
    .td-hero.is-compact .td-hero-identity-grid {
      grid-template-columns: 56px minmax(0, 1fr) auto;
      gap: 16px;
      height: 56px;
    }
    .td-hero.is-compact .td-hero-name-block {
      grid-template-rows: 1fr;
      align-items: center;
      gap: 0;
      height: 56px;
      overflow: hidden;
    }
    .td-hero.is-compact .td-hero-cat {
      font-size: 16px;
      font-weight: 500;
      letter-spacing: 0;
      text-transform: none;
    }
    .td-hero.is-compact .td-hero-cat svg { display: none; }
    .td-hero.is-compact .td-hero-desc { display: none; }
    .td-hero.is-compact .td-hero-h1 {
      overflow: hidden;
      font-size: 30px;
      line-height: 1;
      text-overflow: ellipsis;
      white-space: nowrap;
    }
    .td-hero.is-compact .td-hero-logo {
      width: 56px;
      height: 56px;
      border-radius: var(--radius-md);
    }
    .td-hero.is-compact .td-hero-logo-image {
      width: 56px !important;
      height: 56px !important;
      min-width: 56px !important;
      min-height: 56px !important;
    }
    .td-hero.is-compact .td-hero-site-link {
      min-height: 40px;
      padding-inline: 16px;
      font-size: 14px;
    }
  }
  .td-hero-media {
    margin-top: 20px;
    max-height: var(--td-hero-media-h, 480px);
    overflow: hidden;
    opacity: 1;
  }
  .td-hero-cover {
    display: block;
    width: 100%;
    height: clamp(190px, 22vw, 300px);
    object-fit: cover;
    object-position: center;
    background: var(--color-bg);
  }
  .td-hero-heading {
    display: grid;
    align-content: center;
    min-height: 156px;
    padding: clamp(28px, 3vw, 38px);
    border-radius: 10px;
  }
  @media (max-width: 640px) {
    .td-hero-heading { padding: 24px 22px 26px; }
    .td-hero-cover { height: clamp(180px, 44vw, 240px); }
  }
  @media (prefers-reduced-motion: reduce) {
    .td-hero-card { transition: none; }
  }
  .td-hero-identity-grid {
    display: grid;
    grid-template-columns: 72px minmax(0, 1fr) auto;
    align-items: center;
    gap: 24px;
    min-width: 0;
  }
  .td-hero-name-block {
    display: grid;
    grid-template-rows: auto auto;
    gap: 7px;
    align-self: center;
    height: auto;
    min-width: 0;
  }
  .td-hero-title-row { display: flex; align-items: center; gap: 16px; width: 100%; min-width: 0; }
  .td-hero-title-row .td-hero-h1 { min-width: 0; }
  @media (max-width: 640px) { .td-hero-title-row { flex-wrap: wrap; } }
  .td-hero-logo {
    display: grid;
    place-items: center;
    width: 72px;
    height: 72px;
    flex: 0 0 auto;
    overflow: hidden;
    border-radius: var(--radius-md);
    border: 0;
    background: var(--color-surface);
    box-shadow: 0 8px 24px color-mix(in srgb, var(--color-text) 6%, transparent);
  }
  .td-hero-logo-image {
    width: 58px !important;
    height: 58px !important;
    min-width: 58px !important;
    min-height: 58px !important;
  }
  .td-hero-logo-image { transition: width 220ms ease-out, height 220ms ease-out; }
  .td-hero-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
  .td-hero-promo { display: inline-flex; flex: 0 0 auto; align-items: center; gap: 10px; margin-left: auto; padding: 8px 12px; border: 1px solid hsl(var(--primary) / .28); border-radius: 8px; background: hsl(var(--primary) / .08); color: hsl(var(--primary)); font: 600 14px/1.2 var(--font-ui); white-space: nowrap; }
  .td-hero-promo-label { padding-right: 10px; border-right: 1px solid hsl(var(--primary) / .28); font-size: 15px; font-weight: 700; }
  .td-hero-promo-code { color: var(--color-text); font: 650 12px/1.2 var(--font-ui); letter-spacing: .035em; user-select: all; }
  .td-hero.is-compact .td-hero-promo { padding: 7px 10px; font-size: 12px; }
  .td-hero.is-compact .td-hero-promo-label { font-size: 13px; }
  .td-hero.is-compact .td-hero-promo-code { font-size: 11px; }
