  }
  .td-hero-cat:hover { color: var(--color-text); }
  .td-hero-cat svg { display: none; }
  .td-hero-h1 {
    font-family: var(--font-ui);
    font-size: clamp(34px, 3vw, 42px);
    font-weight: 700;
    letter-spacing: -0.05em;
    line-height: 1;
    color: var(--color-text);
