  }
  .td-editorial-intro-features { margin-top: 36px; }
  .td-editorial-intro-features .td-eyebrow { margin-bottom: 16px; }
  .td-editorial-intro-features .td-feature-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
