  }
  .td-editorial-official-link {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    min-height: 38px;
    color: var(--color-text);
    font-family: var(--font-ui);
    font-size: 13px;
    font-weight: 600;
    text-decoration: none;
  }
  .td-editorial-official-link:hover { text-decoration: underline; text-underline-offset: 3px; }
  .td-editorial-official-link svg { width: 14px; height: 14px; color: var(--color-muted); }
  .td-editorial-facts .td-audience-tags { gap: 6px; margin-bottom: 10px; }
  .td-editorial-facts .td-chip { padding: 5px 8px; font-size: 11px; }
  .td-editorial-facts .td-relevance { display: grid; grid-template-columns: 1fr; gap: 7px; }
  .td-editorial-facts .td-relevance-item { padding: 9px 10px; }
  @media (max-width: 760px) {
