  .td-tutorials-head .td-eyebrow { margin-bottom: 10px; }
  .td-tutorials-head .td-title { margin: 0; }
  .td-tutorials-intro {
    margin: 0;
    color: var(--color-muted);
    font-size: 15px;
    line-height: 1.55;
  }
  .td-tutorials-grid { display: grid; gap: 20px; }
  .td-tutorial-card {
    overflow: hidden;
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
  }
  .td-tutorial-media {
    position: relative;
    aspect-ratio: 16 / 9;
    overflow: hidden;
    background: var(--color-text);
