  .td-tutorial-poster {
    position: relative;
    padding: 0;
    cursor: pointer;
    background: var(--color-text);
  }
  .td-tutorial-poster img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 180ms ease, opacity 180ms ease;
  }
  .td-tutorial-poster::after {
    content: "";
    position: absolute;
    inset: 0;
    background: rgba(0, 0, 0, 0.12);
    transition: background 180ms ease;
  }
  .td-tutorial-poster:hover img { transform: scale(1.015); }
  .td-tutorial-poster:hover::after { background: rgba(0, 0, 0, 0.2); }
