    padding: 10px 14px;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-pill);
  }
  /* Arrow nudges on hover — a small tactile cue, no layout animation */
  .sk-card-cta span[aria-hidden] {
    display: inline-block;
    transition: transform 220ms cubic-bezier(0.16, 1, 0.3, 1);
  }
  .sk-card:hover .sk-card-cta span[aria-hidden] { transform: translateX(4px); }
  .sk-card-gallery {
    display: grid;
