  }
  .sk-card:hover .sk-card-gallery-item .tc-image img { transform: scale(1.018); }
  .sk-card-gallery-caption {
    position: absolute;
    inset: auto 0 0;
    padding: 9px 10px;
    background: rgba(16,16,16,0.82);
    color: #fff;
    font-family: var(--font-ui);
    line-height: 1.15;
  }
  .sk-card-gallery-caption strong,
  .sk-card-gallery-caption small {
    display: block;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .sk-card-gallery-caption strong { font-size: 12px; font-weight: 650; }
  .sk-card-gallery-caption small { margin-top: 3px; font-size: 10px; color: rgba(255,255,255,0.72); }
  .sk-card-gallery-more {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 5px;
    padding: 14px;
    text-align: center;
