    color: var(--color-text);
  }
  .sk-card-roles > small {
    font-family: var(--font-ui);
    font-size: 12px;
    color: var(--color-muted);
  }
  .sk-empty-state { margin-top: 0; }
  @media (max-width: 1180px) {
    .sk-card-gallery { grid-template-columns: repeat(4, minmax(0, 1fr)); }
    .sk-card-gallery-more { display: none; }
  }
  @media (max-width: 1023px) {
    .sk-listing-layout { grid-template-columns: 1fr; }
    .sk-results-grid { grid-template-columns: 1fr; }
  }
  @media (max-width: 767px) {
    .sk-section { padding: 56px 0; }
