    .sk-results-grid { grid-template-columns: 1fr; }
    .sk-card { padding: 20px; }
    .sk-card-title { font-size: 1.4rem; }
    .sk-card-header { display: block; }
    .sk-card-header .sk-card-cta { margin-top: 16px; }
    .sk-card-gallery {
      grid-template-columns: repeat(2, minmax(0, 1fr));
      min-height: 116px;
    }
    .sk-card-gallery-item:nth-child(n+3) { display: none; }
    .sk-card-gallery-item .tc-image.sk-card-tool-image {
      height: 116px;
      min-height: 116px;
    }
  }
}

/* ─────────────────────────────────────────────
   STACK DETAIL (sd-*)
   /fr/stacks/:slug editorial detail page.
───────────────────────────────────────────── */
@layer components {

  /* ── Body container ──────────────────────── */
  .sd-container {
    max-width: var(--layout-content);
    margin: 0 auto;
    padding: 0 var(--layout-gutter);
  }

  /* ── Section ─────────────────────────────── */
  .sd-section {
    padding: 56px 0;
    border-bottom: 1px solid var(--color-border);
  }
  .sd-section:last-child { border-bottom: none; }
  .sd-section-eyebrow {
    font-family: var(--font-ui);
    font-size: var(--tt-size-kicker);
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-muted);
    margin-bottom: 16px;
    display: block;
  }
  .sd-section-title {
    font-family: var(--font-ui);
    font-size: var(--tt-size-section-h);
    font-weight: 620;
    letter-spacing: -0.035em;
    line-height: 1.08;
    color: var(--color-text);
    margin: 0 0 28px;
  }

  .sd-tool-name { font-family: var(--font-ui); font-size: 15px; font-weight: 600; letter-spacing: -0.02em; color: var(--color-text); }

  .sd-risk-problem { font-family: var(--font-ui); font-size: 15px; font-weight: 600; color: var(--color-text); letter-spacing: -0.02em; }

  /* ── CTA band ────────────────────────────── */
  .sd-cta-band {
    background: var(--color-bg);
    border-top: 1px solid var(--color-border);
    border-bottom: 1px solid var(--color-border);
    padding: 56px 0;
  }

  /* ── Related stacks ──────────────────────── */
  .sd-related-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
    margin-top: 24px;
  }
  @media (max-width: 900px) { .sd-related-grid { grid-template-columns: repeat(2, 1fr); } }
  @media (max-width: 560px) { .sd-related-grid { grid-template-columns: 1fr; } }

  .sd-related-card {
    border: 1px solid var(--color-border-soft);
    border-radius: var(--tt-surface-radius-info);
    padding: 20px;
    text-decoration: none;
    color: var(--color-text);
    transition: border-color 160ms ease-out, background 160ms ease-out;
    display: flex;
    flex-direction: column;
    gap: 8px;
  }
  .sd-related-card:hover { border-color: var(--color-border); background: color-mix(in srgb, var(--color-surface-soft) 42%, var(--color-surface)); }
  .sd-related-name { font-family: var(--font-ui); font-size: 14px; font-weight: 600; letter-spacing: -0.02em; line-height: 1.3; color: var(--color-text); }
  .sd-related-sub { font-family: var(--font-ui); font-size: 12px; line-height: 1.4; color: var(--color-muted); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
  .sd-related-footer { display: flex; align-items: center; justify-content: space-between; margin-top: 6px; }
  .sd-related-budget { font-family: var(--font-ui); font-size: 12px; font-weight: 600; color: var(--color-text); }
  .sd-related-cta { font-family: var(--font-ui); font-size: 12px; font-weight: 500; color: var(--color-muted); display: flex; align-items: center; gap: 3px; transition: color 140ms; }
  .sd-related-card:hover .sd-related-cta { color: var(--color-text); }
}

