}

  /* ═══════════════════════════════════════════════════════════════════════════
     cp-* — ComparePage (comparatif éditorial)
     Sprint Comparatif 2026-05-15
  ═══════════════════════════════════════════════════════════════════════════ */

  /* ── Hero ──────────────────────────────────────────────────── */
  .cp-hero {
    background: var(--color-bg);
    padding: var(--tt-hero-pt, 72px) 0 var(--tt-hero-pb, 64px);
  }
  .cp-hero-inner {
    max-width: var(--layout-content, 1280px);
    margin: 0 auto;
    padding: 0 var(--layout-gutter, 48px);
  }
  /* Hero meta row — breadcrumb left, "Reviewed · month year" stamp right.
     Editorial signature: monospace stamp signals fact-checked, dated verdict. */
  .cp-hero-meta {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 24px;
    margin-bottom: 24px;
  }
  .cp-hero-checked {
    flex-shrink: 0;
    font-family: ui-monospace, "SF Mono", "Roboto Mono", Menlo, Consolas, monospace;
    font-size: var(--tt-size-kicker);
    font-weight: 500;
    letter-spacing: 0.02em;
    color: var(--color-muted);
    white-space: nowrap;
  }
  @media (max-width: 640px) {
    .cp-hero-meta { flex-direction: column; align-items: flex-start; gap: 12px; }
  }

  /* ── Breadcrumb — editorial publication mark ──────────────
     Signature: tiny filled square ▪ prefix (same shape that closes
     the verdict-statement and the article lede) + monospace
     uppercase publication mark for the parent path + sans-serif
     current section. Wirecutter / Stripe Press pattern, scaled down. */
  .cp-breadcrumb {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 6px 10px;
    margin-bottom: 0;
    font-family: var(--font-ui);
    font-size: 13px;
    color: var(--color-muted);
  }
  .cp-breadcrumb::before {
    content: "";
    display: inline-block;
    width: 0.6em;
    height: 0.6em;
    background: var(--color-text-strong);
    flex-shrink: 0;
    margin-right: 2px;
    transform: translateY(-0.04em);
  }
  .cp-breadcrumb a {
    font-family: ui-monospace, "SF Mono", "Roboto Mono", Menlo, Consolas, monospace;
    font-size: 11px;
    font-weight: 500;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--color-muted);
    text-decoration: underline;
    text-decoration-color: transparent;
    text-underline-offset: 4px;
    text-decoration-thickness: 1px;
    transition: color 180ms cubic-bezier(0.25, 1, 0.5, 1),
                text-decoration-color 180ms cubic-bezier(0.25, 1, 0.5, 1);
  }
  .cp-breadcrumb a:hover {
    color: var(--color-text-strong);
    text-decoration-color: var(--color-text-strong);
  }
  /* Separator span (any span that's not the last one) */
  .cp-breadcrumb > span:not(:last-child) {
    color: var(--color-border);
    font-family: var(--font-ui);
    font-size: 13px;
    user-select: none;
  }
  /* Current section — sans-serif, real weight, normal case */
  .cp-breadcrumb > span:last-child {
    font-family: var(--font-ui);
    font-size: 13px;
    font-weight: 600;
    letter-spacing: -0.01em;
    color: var(--color-text-strong);
    text-transform: none;
  }
  /* Uses tt-hero-title scale — no page-specific overrides above 124px */
  .cp-hero-title {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    column-gap: 0.22em;
    row-gap: 0.1em;
    max-width: 1040px;
    margin: 0 0 36px;
    font-family: var(--font-brand);
    font-size: var(--tt-size-hero);
    font-weight: 700;
    letter-spacing: -0.07em;
    line-height: 0.92;
    color: var(--color-text);
  }
  .cp-hero-title-tool {
    display: inline-flex;
    align-items: center;
    gap: 0.18em;
    white-space: nowrap;
  }
  .cp-hero-title-logo { flex-shrink: 0; }
  .cp-hero-title-vs {
    color: var(--color-muted-light);
    font-weight: 700;
  }
  /* Uses tt-hero-subtitle scale */
  /* Hero promise — section "promise" peak, bolded sub-headline */
  .cp-hero-promise {
    max-width: 68ch;
    margin: 0 0 32px;
    font-family: var(--font-ui);
    font-size: var(--tt-size-hero-sub);
    line-height: 1.35;
    letter-spacing: -0.02em;
    color: var(--color-text-strong);
  }
  /* TIER 1 — lede paragraph (one or two sentences under a heading) */
  .cp-hero-intro {
    max-width: 68ch;
    margin: 0 0 32px;
    font-family: var(--font-ui);
    font-size: var(--tt-size-body-large);
    line-height: 1.5;
    letter-spacing: -0.015em;
    color: var(--color-text);
  }

  @media (max-width: 640px) {
    .cp-hero { padding: 56px 0 48px; }
    .cp-hero-inner { padding: 0 24px; }
    .cp-hero-title { font-size: clamp(44px, 12vw, 64px); }
    .cp-hero-promise { margin-bottom: 28px; }
  }

  /* (cp-vs-module, cp-decision-panel, cp-decision-facts, cp-decision-tools,
     cp-vs-row/logo/name/sep/verdict — all removed: orphaned by previous
     redesigns, no JSX references remained) */

  /* ── Generic section wrapper ───────────────────────────────── */
  /* Sections are separated by vertical rhythm only — no hairline borders.
     Strong dividers (2px) are reserved for editorial moments inside a
     section (sub-section, table header), not for section boundaries. */
  .cp-section { padding: var(--tt-section-y) 0; }
  .cp-section[id] { scroll-margin-top: 96px; }
  .cp-section--last { /* kept for semantic compat */ }
  .cp-container {
    max-width: var(--layout-content, 1280px);
    margin: 0 auto;
    padding: 0 var(--layout-gutter, 48px);
  }
  /* Kicker / section number — uses tt-kicker scale */
  .cp-eyebrow {
    font-family: var(--font-ui);
    font-size: var(--tt-size-kicker); font-weight: 700;
    letter-spacing: 0.08em; text-transform: uppercase;
    color: var(--color-muted, var(--color-muted)); display: block; margin-bottom: 16px;
  }
  /* Section heading — headline scale, compressed */
  .cp-title {
    font-family: var(--font-ui);
    font-size: var(--tt-size-section-h);
    font-weight: 620; letter-spacing: -0.035em;
    line-height: 1.08; color: var(--color-text, var(--color-text));
    max-width: none; margin-bottom: 0;
  }
  @media (max-width: 640px) {
    .cp-title { font-size: var(--tt-size-section-h); line-height: 1.08; }
  }
  /* ── Verdict: editorial recommendation statement ────────────── */
  .cp-verdict-statement {
    /* No padding-top — matrix-header margin-bottom carries the upper gap.
       No border-bottom either — the editorial endmark (▪) marks the close;
       a hairline below would be double-marking. */
    padding: 0;
    margin-bottom: clamp(48px, 4.5vw, 64px);
    background: transparent;
  }
  /* Statement is a pull-quote, NOT a competing headline.
     Must read smaller than the section H2 (40-56px).
     Editorial endmark: a filled square sits after the last word, like
     the "fin d'article" marks magazines use to close a verdict. */
  .cp-verdict-statement p {
    margin: 0;
    font-family: var(--font-ui);
    font-size: var(--tt-size-section-intro);
    line-height: 1.3;
    font-weight: 700;
    letter-spacing: -0.025em;
    color: var(--color-text-strong);
    max-width: 760px;
  }
  .cp-verdict-statement p::after {
    content: "";
    display: inline-block;
    width: 0.42em;
    height: 0.42em;
    background: var(--color-text-strong);
    margin-left: 0.28em;
    vertical-align: 0.08em;
  }
  /* (cp-decision-columns / cp-decision-col / cp-decision-label / cp-decision-text /
     cp-decision-note: removed — never rendered in JSX. The active
     cp-decision-list/-item/-condition/-answer family lives further down.) */

  /* ── Usage scores ────────────────────────────────────────── */
  /* (cp-tipping-panel span shared rule removed Sprint 75) */

  /* ── Decision matrix — Critères décisionnels (Sprint 73) ──────── */
  .cp-matrix-header {
    margin-bottom: clamp(44px, 4.5vw, 64px);
  }
  .cp-matrix-header .cp-eyebrow { margin-bottom: 12px; }
  .cp-matrix-header .cp-title { margin-bottom: 0; max-width: none; }
  /* TIER 1 — lede paragraph under matrix-header H2 (same tier as section-intro) */
  .cp-matrix-intro {
    max-width: 68ch;
    margin: 20px 0 0;
    font-family: var(--font-ui);
    font-size: var(--tt-size-body-large);
    line-height: 1.5;
    letter-spacing: -0.015em;
    color: var(--color-text);
  }

  .cp-profile-reason {
    font-family: var(--font-ui);
    font-size: 14px; line-height: 1.5; color: var(--color-muted);
  }
  .cp-profile-limit {
    font-family: var(--font-ui);
    font-size: 13px; color: var(--color-muted);
    margin-top: 10px; padding-top: 10px;
    border-top: 1px solid var(--color-border-soft);
  }

  /* ── Tipping point — Sprint 75 ───────────────────────────── */
  /* (cp-tipping-panel, cp-tipping-signals removed Sprint 75) */

  /* Verdict logic — two parallel editorial blocks, no card, no arrow gimmick */
  .cp-tipping-card {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: clamp(40px, 5vw, 80px);
    background: transparent;
    border: none;
    border-radius: 0;
    margin-bottom: clamp(56px, 5vw, 80px);
  }
  .cp-tipping-card-state {
    padding: 0;
    border: none;
    background: transparent;
  }
  .cp-tipping-card-state--switch {
    border: none;
    background: transparent;
  }
  .cp-tipping-card-arrow {
    display: none;
  }
  /* TIER 1 — body-large in the verdict logic blocks (par défaut / bascule si) */
  .cp-tipping-card-text {
    margin: 12px 0 0;
    font-family: var(--font-ui);
    font-size: var(--tt-size-body-large);
    line-height: 1.5;
    letter-spacing: -0.015em;
    font-weight: 500;
    color: var(--color-text-strong);
  }
  @media (max-width: 768px) {
    .cp-tipping-card {
      grid-template-columns: 1fr;
      gap: 32px;
    }
  }

  /* Rules — open editorial list, no frame, no number column */
  .cp-tipping-rules {
    margin-top: 0;
    border-top: 2px solid var(--color-border-strong);
  }
  .cp-tipping-rules-heading {
    display: block;
    padding-top: 20px;
    margin-bottom: 8px;
  }
  .cp-tipping-rules-list {
    display: block;
    margin: 0;
    padding: 0;
    list-style: none;
    border: none;
    border-radius: 0;
  }
  .cp-tipping-rule {
    display: block;
    padding: 0;
    background: transparent;
    border-bottom: 1px solid var(--color-border-soft);
  }
  /* TIER 2 — body standard */
  .cp-tipping-rule p {
    margin: 0;
    padding: 20px 0;
    font-family: var(--font-ui);
    font-size: var(--tt-size-body);
    line-height: 1.55;
    letter-spacing: -0.01em;
    color: var(--color-text);
  }

  /* CTA row */
  .cp-tipping-cta {
    display: flex;
    align-items: center;
    margin-top: clamp(40px, 4vw, 56px);
  }
  @media (max-width: 640px) {
    .cp-tipping-cta { flex-direction: column; align-items: stretch; }
    .cp-tipping-cta .tt-button-secondary { justify-content: center; }
  }
  /* (cp-cost-grid / cp-cost-row / cp-cost-label / cp-cost-reco / cp-cost-note removed Sprint 74) */

  /* Cost section — no longer needs its own surface or var overrides
     (the page is already light-themed). Kept as a hook for future
     cost-specific styling if needed. */
  .cp-section--cost {
    /* background continuity with the rest of the page */
  }
  /* Recommendation embedded in left column (section 03) */
  .cp-cost-reco {
    margin-top: 24px;
    padding-top: 20px;
    border-top: 1px solid var(--color-border-soft, var(--color-border-soft));
  }
  .cp-cost-reco .tt-fact-label { margin-bottom: 10px; }
  .cp-cost-reco .tt-body-large { margin: 0; color: var(--color-text, var(--color-text)); }

  /* ── Sections 02, 03, 04 — grille 3 colonnes : critère | outil A | outil B */
  /* Editorial pricing-table pattern: no top wall, anchored under-header line */
  .cp-compare-table {
    /* gap from matrix-header is carried by cp-matrix-header margin-bottom */
  }
  /* Header row — generous vertical air, logo prominent, upright bold name */
  .cp-compare-header {
    display: grid;
    grid-template-columns: 1.4fr 1fr 1fr;
    padding: 0 0 28px;
    border-bottom: 2px solid var(--color-border-strong);
    align-items: end;
  }
  .cp-compare-header-label {
    /* empty spacer — aligns with criterion column */
  }
  .cp-compare-header-tool {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 16px;
    padding-left: 28px;
  }
  .cp-compare-header-name {
    font-family: var(--font-ui);
    font-size: var(--tt-size-body-large);
    font-weight: 700;
    letter-spacing: -0.02em;
    line-height: 1;
    color: var(--color-text-strong);
  }
  /* Criterion rows — open, single rhythm, with editorial hover wash */
  .cp-compare-row {
    display: grid;
    grid-template-columns: 1.4fr 1fr 1fr;
    border-bottom: 1px solid var(--color-border-soft);
    align-items: start;
    transition: background-color 0.25s cubic-bezier(0.25, 1, 0.5, 1);
  }
  .cp-compare-row:hover { background-color: var(--color-surface-soft); }
  .cp-compare-row-label {
    padding: 28px 28px 28px 0;
  }
  /* Criterion title — clear row anchor, body-large bold */
  .cp-compare-row-title {
    margin: 0;
    font-family: var(--font-ui);
    font-size: var(--tt-size-body-large); font-weight: 700; letter-spacing: -0.02em; line-height: 1.3;
    color: var(--color-text-strong);
  }
  /* Editorial verdict — tertiary note under the title, same style as tool note */
  .cp-compare-row-verdict {
    margin: 8px 0 0;
    font-family: var(--font-ui);
    font-size: var(--tt-size-card-body); font-weight: 400; line-height: 1.5; letter-spacing: -0.01em;
    color: var(--color-muted);
    max-width: 42ch;
  }
  /* Tool value columns — clean, single value per cell like the reference */
  .cp-compare-row-tool {
    padding: 28px 0 28px 28px;
  }
  .cp-compare-row-tool-val {
    margin: 0;
    font-family: var(--font-ui);
    font-size: var(--tt-size-body); font-weight: 400; letter-spacing: -0.015em; line-height: 1.5;
    color: var(--color-text);
  }
  .cp-compare-row-tool-note {
    margin: 4px 0 0;
    font-family: var(--font-ui);
    font-size: var(--tt-size-card-body); font-weight: 400; line-height: 1.5; letter-spacing: -0.01em;
    color: var(--color-muted);
  }
  /* Winner: emphasis through weight + color only, never size — both columns stay at body */
  .cp-compare-row-tool--win .cp-compare-row-tool-val {
    font-weight: 600; color: var(--color-text-strong);
  }
  .cp-compare-row-tool--win .cp-compare-row-tool-note { color: var(--color-muted); }
  /* Equal (cost section — no winner, both shown at readable weight) */
  .cp-compare-row-tool--eq .cp-compare-row-tool-val {
    color: var(--color-text); font-weight: 400;
  }
  /* Responsive — 768px: label full-width, tools side by side */
  @media (max-width: 768px) {
    .cp-compare-header { grid-template-columns: 1fr 1fr; }
    .cp-compare-header-label { display: none; }
    .cp-compare-header-tool:first-of-type { border-left: none; padding-left: 0; }
    .cp-compare-row { grid-template-columns: 1fr 1fr; }
    .cp-compare-row-label { grid-column: 1 / -1; padding-bottom: 18px; border-bottom: 1px solid var(--color-border-soft); }
    .cp-compare-row-tool:first-of-type { border-left: none; padding-left: 0; }
    .cp-compare-row-tool { padding-top: 18px; padding-bottom: 28px; }
  }
  @media (max-width: 480px) {
    .cp-compare-header { grid-template-columns: 1fr; }
    .cp-compare-header-tool + .cp-compare-header-tool { border-top: 1px solid var(--color-border-soft); margin-top: 16px; padding-top: 16px; border-left: none; padding-left: 0; }
    .cp-compare-row { grid-template-columns: 1fr; }
    .cp-compare-row-tool { border-left: none; padding-left: 0; padding-top: 0; }
    .cp-compare-row-tool + .cp-compare-row-tool { padding-top: 14px; }
  }

  /* ── Section 01 — quick decision list ─────────────────────── */
  /* 30-second scan: condition + verdict tight on one line.
     Capped width so the pair stays visually locked on wide screens. */
  .cp-decision-list {
    max-width: 920px;
    border-top: 2px solid var(--color-border-strong);
  }
  .cp-decision-item {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    column-gap: 40px;
    align-items: baseline;
    padding: 22px 0;
    border-bottom: 1px solid var(--color-border-soft);
    transition: background-color 0.25s cubic-bezier(0.25, 1, 0.5, 1);
  }
  .cp-decision-item:hover { background-color: var(--color-surface-soft); }
  /* TIER 1 — lede pair (condition + answer) on the "Ma situation" list */
  .cp-decision-condition {
    margin: 0;
    font-family: var(--font-ui);
    font-size: var(--tt-size-body-large);
    font-weight: 400;
    letter-spacing: -0.015em;
    line-height: 1.5;
    color: var(--color-text);
  }
  .cp-decision-answer {
    margin: 0;
    font-family: var(--font-ui);
    font-size: var(--tt-size-body-large);
    font-weight: 700;
    letter-spacing: -0.02em;
    line-height: 1.4;
    color: var(--color-text-strong);
    white-space: nowrap;
  }
  .cp-decision-answer::before {
    content: "→ ";
    color: var(--color-muted-light);
    font-weight: 400;
    margin-right: 6px;
  }
  @media (max-width: 600px) {
    .cp-decision-item { grid-template-columns: 1fr; row-gap: 8px; padding: 18px 0; }
    .cp-decision-answer { white-space: normal; }
    .cp-decision-answer::before { display: none; }
  }

  /* ── Sub-section divider (content blocks within a section) ── */
  .cp-sub-section {
    margin-top: clamp(64px, 6vw, 96px);
  }
  .cp-sub-section-eyebrow {
    display: block;
    font-family: var(--font-ui);
    font-size: var(--tt-size-kicker); font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase;
    color: var(--color-muted);
    padding-top: 48px;
    border-top: 1px solid var(--color-border);
    margin-bottom: 10px;
  }
  .cp-sub-section-title {
    margin: 0 0 32px;
    font-family: var(--font-ui);
    font-size: var(--tt-size-body-large); font-weight: 600; letter-spacing: -0.02em;
    color: var(--color-text);
    line-height: 1.32;
  }

  /* ── Section counter — large architectural number ──────────── */
  /* (cp-section-counter removed — decorative numbering dropped) */

  /* ── Alternative rows ──────────────────────────────────────── */
  .cp-alt-row {
    display: flex; align-items: center; gap: 16px;
    padding: 16px 8px; border-bottom: 1px solid var(--color-border);
    text-decoration: none; border-radius: var(--radius-sm);
    transition: background 140ms; cursor: pointer;
  }
  .cp-alt-row:first-child { border-top: 1px solid var(--color-border); }
  .cp-alt-row:last-child { border-bottom: none; }
  .cp-alt-row:hover { background: var(--color-bg); }
  .cp-alt-logo {
    width: 40px; height: 40px; border-radius: var(--radius);
    background: var(--color-bg); border: 1px solid var(--color-border-soft);
    display: flex; align-items: center; justify-content: center;
    overflow: hidden; flex-shrink: 0;
  }
  .cp-alt-content { flex: 1; min-width: 0; }
  .cp-alt-name {
    font-family: var(--font-ui); font-size: var(--tt-size-card-body);
    font-weight: 600; color: var(--color-text); letter-spacing: -0.02em;
  }
  .cp-alt-reason { font-family: var(--font-ui); font-size: var(--tt-size-card-body); line-height: 1.5; letter-spacing: -0.01em; color: var(--color-muted); margin-top: 2px; }
  .cp-alt-right { display: flex; flex-direction: column; align-items: flex-end; gap: 4px; flex-shrink: 0; }
  .cp-alt-price { font-family: var(--font-ui); font-size: var(--tt-size-card-body); font-weight: 600; letter-spacing: -0.02em; color: var(--color-text); }
  .cp-alt-cta {
    font-family: var(--font-ui); font-size: var(--tt-size-kicker);
    font-weight: 600; color: var(--color-muted);
    letter-spacing: 0.02em;
    transition: color 140ms;
  }
  .cp-alt-row:hover .cp-alt-cta { color: var(--color-text); }

  /* ── CTA band ──────────────────────────────────────────────── */
  .cp-cta-band {
    background: transparent;
    border: 0;
    padding: 0 0 72px;
  }
  .cp-cta-band .cp-container {
    background: transparent;
    border: none;
    border-radius: 0;
    padding-top: 48px;
    padding-bottom: 0;
  }
  /* TIER 1 — lede paragraph under CTA heading */
  .cp-cta-band-desc {
    font-family: var(--font-ui);
    font-size: var(--tt-size-body-large);
    line-height: 1.5;
    letter-spacing: -0.015em;
    color: var(--color-text);
    max-width: 56ch;
    margin: 12px 0 28px;
  }
  @media (max-width: 640px) {
    .cp-cta-band .cp-container { padding: 28px 20px; }
    .cp-cta-band .tt-button-primary { justify-content: center; width: 100%; }
  }

  /* ── FAQ ───────────────────────────────────────────────────── */

  /* Theme nav — opt-in, only renders when all items declare a theme */
  .cp-faq-nav {
    display: flex;
    flex-wrap: wrap;
    gap: 24px;
    padding: 0 0 24px;
    margin-bottom: clamp(28px, 3vw, 40px);
    border-bottom: 1px solid var(--color-border);
  }
  .cp-faq-nav-link {
    font-family: var(--font-ui);
    font-size: var(--tt-size-kicker);
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-muted);
    text-decoration: underline;
    text-decoration-color: transparent;
    text-underline-offset: 4px;
    text-decoration-thickness: 1px;
    transition: color 180ms cubic-bezier(0.25, 1, 0.5, 1),
                text-decoration-color 180ms cubic-bezier(0.25, 1, 0.5, 1);
  }
  .cp-faq-nav-link:hover {
    color: var(--color-text);
    text-decoration-color: var(--color-text);
  }

  /* Theme group wrapper — opt-in */
  .cp-faq-theme { scroll-margin-top: 96px; }
  .cp-faq-theme + .cp-faq-theme { margin-top: clamp(40px, 4vw, 56px); }
  .cp-faq-theme-title {
    margin: 0 0 12px;
    font-family: var(--font-ui);
    font-size: var(--tt-size-body-large);
    font-weight: 700;
    letter-spacing: -0.02em;
    line-height: 1.3;
    color: var(--color-text-strong);
  }

  /* Existing flat-accordion styles — unchanged from the original */
  .cp-faq-item { border-top: 1px solid var(--color-border); }
  .cp-faq-summary {
    font-family: var(--font-ui);
    font-size: 16px; font-weight: 600;
    color: var(--color-text); letter-spacing: -0.02em;
    cursor: pointer; list-style: none;
    display: flex; justify-content: space-between;
    align-items: center; gap: 16px;
    padding: 18px 0; width: 100%;
  }
  .cp-faq-summary::-webkit-details-marker { display: none; }
  .cp-faq-answer {
    font-family: var(--font-ui);
    font-size: 15px; line-height: 1.65;
    color: var(--color-muted); padding-bottom: 18px;
    max-width: 720px;
  }

  /* ── Pitfall / Erreurs fréquentes — Sprint 76 ────────────── */
  /* (cp-watchout-list / cp-watchout-row / cp-watchout-title / cp-watchout-copy / cp-watchout-reco removed Sprint 76) */

  /* --tt-warning: #C8600A (burnt orange, subtle attention accent — no token needed beyond this block) */

  /* ── Limites & alternatives — compact fused section ─── */
  .cp-limites-risks {
    display: flex;
    flex-direction: column;
    margin-bottom: 48px;
  }
  .cp-limites-risk-row {
    display: flex;
    gap: 20px;
    align-items: flex-start;
    padding: 16px 0;
    border-bottom: 1px solid var(--color-border-soft);
  }
  .cp-limites-risk-row:first-child { border-top: 1px solid var(--color-border-soft); }
  /* (cp-limites-risk-num removed — decorative numbering dropped) */
  .cp-limites-risk-title {
    margin: 0 0 4px;
    font-family: var(--font-ui);
    font-size: var(--tt-size-card-title);
    font-weight: 600;
    line-height: 1.4;
    letter-spacing: -0.02em;
    color: var(--color-text);
  }
  /* TIER 3 — body compact */
  .cp-limites-risk-fix {
    margin: 0;
    font-family: var(--font-ui);
    font-size: var(--tt-size-card-body);
    line-height: 1.5;
    letter-spacing: -0.01em;
    color: var(--color-muted);
  }
  .cp-limites-alts { display: flex; flex-direction: column; }

  .cp-profile-reason {
    font-family: var(--font-ui);
    font-size: 14px;
    line-height: 1.55;
    color: var(--color-muted);
    flex: 1;
    margin: 0 0 16px;
  }
  .cp-profile-limit {
    padding: 12px 16px;
    background: var(--color-bg);
    border: 1px solid var(--color-border-soft);
    border-radius: var(--radius-sm);
  }
  .cp-profile-limit .tt-fact-label { display: block; margin-bottom: 6px; }
  .cp-profile-limit p {
    margin: 0;
    font-family: var(--font-ui);
    font-size: 14px;
    line-height: 1.5;
    color: var(--color-muted);
  }

  /* Hero jump-to-verdict — escape hatch for users who know what they want */
  .cp-hero-verdict-jump {
    display: inline-block;
    margin-top: 16px;
    font-family: var(--font-ui);
    font-size: var(--tt-size-kicker);
    font-weight: 600;
    letter-spacing: 0.04em;
    color: var(--color-muted);
    text-decoration: underline;
    text-decoration-color: transparent;
    text-underline-offset: 4px;
    text-decoration-thickness: 1px;
    transition: color 180ms cubic-bezier(0.25, 1, 0.5, 1),
                text-decoration-color 180ms cubic-bezier(0.25, 1, 0.5, 1);
  }
  .cp-hero-verdict-jump:hover {
    color: var(--color-text);
    text-decoration-color: var(--color-text);
  }

  /* Methodology footnote — sits below the CTA band, no hairline (CTA padding carries the gap) */
  .cp-methodology-note {
    padding: 20px 0;
    text-align: center;
  }
  .cp-methodology-link {
    font-family: var(--font-ui);
    font-size: var(--tt-size-kicker);
    font-weight: 500;
    letter-spacing: 0.04em;
    color: var(--color-muted);
    text-decoration: underline;
    text-decoration-color: transparent;
    text-underline-offset: 4px;
    text-decoration-thickness: 1px;
    transition: color 180ms cubic-bezier(0.25, 1, 0.5, 1),
                text-decoration-color 180ms cubic-bezier(0.25, 1, 0.5, 1);
  }
  .cp-methodology-link:hover {
    color: var(--color-text);
    text-decoration-color: var(--color-text);
  }


  /* Profile accordion — replaces grid of identical cards */
  .cp-profile-accordion {
    border: 1px solid var(--color-border-strong);
    border-radius: var(--radius-md);
    overflow: hidden;
  }
  .cp-profile-row {
    border-bottom: 1px solid var(--color-border);
  }
  .cp-profile-row:last-child { border-bottom: none; }
  .cp-profile-row--open { background: var(--color-bg); }
  .cp-profile-trigger {
    display: flex;
    align-items: center;
    gap: 12px;
    width: 100%;
    padding: 16px 20px;
    background: none;
    border: none;
    cursor: pointer;
    text-align: left;
  }
  .cp-profile-trigger:hover { background: var(--color-surface-soft); }
  .cp-profile-row--open .cp-profile-trigger { background: var(--color-bg); }
  .cp-profile-trigger-name {
    font-family: var(--font-ui);
    font-size: var(--tt-size-card-title);
    font-weight: 600;
    letter-spacing: -0.02em;
    color: var(--color-text);
    flex: 1;
    min-width: 0;
  }
  .cp-profile-trigger-choice {
    font-family: var(--font-ui);
    font-size: 13px;
    font-weight: 700;
    letter-spacing: -0.01em;
    color: var(--color-muted);
    white-space: nowrap;
    flex-shrink: 0;
  }
  .cp-profile-trigger-icon {
    width: 14px;
    height: 14px;
    color: var(--color-muted-light);
    flex-shrink: 0;
    transition: transform 0.15s ease;
  }
  .cp-profile-row--open .cp-profile-trigger-icon { transform: rotate(180deg); }
  .cp-profile-detail {
    padding: 0 20px 20px;
  }
  .cp-profile-detail .cp-profile-reason {
    margin: 0 0 16px;
    font-family: var(--font-ui);
    font-size: 14px;
    line-height: 1.55;
    color: var(--color-muted);
  }
  .cp-profile-detail .cp-profile-limit {
    padding: 12px 16px;
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-sm);
  }
  .cp-profile-detail .cp-profile-limit .tt-fact-label { display: block; margin-bottom: 6px; }
  .cp-profile-detail .cp-profile-limit p {
    margin: 0;
    font-family: var(--font-ui);
    font-size: 14px;
    line-height: 1.5;
    color: var(--color-muted);
  }

/* ─────────────────────────────────────────────
   COMPARATIFS INDEX (cix-*)
   /fr/comparatifs — search, filters, editorial rows
───────────────────────────────────────────── */
@layer components {

  .cix-hero {
    padding: var(--space-xl) 0;
    border-bottom: 1px solid var(--color-border);
  }
  .cix-hero-title {
    max-width: 780px;
    margin: var(--space-lg) 0 0;
    font-family: var(--font-brand);
    font-size: var(--tt-size-page-title);
    font-weight: 700;
    letter-spacing: -0.055em;
    line-height: 0.98;
    color: var(--color-text);
  }
  /* ── Compact discovery command bar ───────────────────── */
  .cix-toolbar {
    margin-bottom: var(--space-lg);
  }
  .cix-filter-group {
    flex: 0 0 auto;
  }
  .cix-popular {
    display: flex;
    flex: 1 1 auto;
    flex-wrap: nowrap;
    align-items: center;
    gap: var(--space-xs);
    justify-content: flex-start;
    min-width: 0;
    margin: 0;
    padding-left: var(--space-md);
    border-left: 1px solid var(--color-border-soft);
    overflow-x: auto;
    scrollbar-width: none;
  }
  .cix-popular::-webkit-scrollbar {
    display: none;
  }
  .cix-popular-label {
    flex: 0 0 auto;
    font-family: var(--font-ui);
    font-size: var(--tt-size-kicker);
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-muted);
    margin-right: var(--space-2xs);
  }
  .cix-suggestion-chip {
    flex: 0 0 auto;
    display: inline-flex;
    align-items: center;
    padding: 6px 12px;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-pill);
    font-family: var(--font-ui);
    font-size: 13px;
    font-weight: 500;
    color: var(--color-text);
    text-decoration: none;
    transition: border-color 140ms ease-out, color 140ms ease-out;
  }
  .cix-suggestion-logos {
    display: inline-flex;
    align-items: center;
    margin-right: var(--space-xs);
  }
  .cix-suggestion-logos > * {
    border: 2px solid var(--color-surface);
    border-radius: var(--radius-circle);
  }
  .cix-suggestion-logos > * + * {
    margin-left: -6px;
  }
  .cix-suggestion-chip:hover {
    border-color: var(--color-text-strong);
    color: var(--color-text-strong);
  }
  .cix-controls-count {
    flex: 0 0 auto;
    padding-left: var(--space-md);
    border-left: 1px solid var(--color-border-soft);
    font-family: var(--font-ui);
    font-size: var(--tt-size-card-body);
    font-weight: 600;
    color: var(--color-muted);
    white-space: nowrap;
  }
  @media (max-width: 1400px) {
    .cix-controls-count-label {
      display: none;
    }
    .cix-suggestion-chip:nth-last-child(-n + 2) {
      display: none;
    }
  }

  /* ── Section / container shared ──────────────────────── */
  /* Top padding 40px to match the other catalog pages' hero offset
     (.tt-catalog-container / .cat-body / .sk-listing-section all = 40px);
     was 56px, which pushed the Comparatifs header lower than the rest. */
  .cix-section {
    padding: 0 0 var(--space-3xl);
    background: var(--color-bg);
  }
  .cix-container {
    max-width: var(--layout-content, 1280px);
    margin: 0 auto;
    padding: 0 var(--layout-gutter, 48px);
  }

  /* ── Listing header ──────────────────────────────────── */
  .cix-listing-header {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 16px;
    flex-wrap: wrap;
    margin: var(--space-xl) 0 var(--space-md);
  }
  .cix-listing-title {
    font-family: var(--font-brand);
    font-size: clamp(1.5rem, 3vw, 2.25rem);
    font-weight: 600;
    letter-spacing: -0.04em;
    line-height: 1.05;
    color: var(--color-text);
    margin: 0;
  }


  /* ── Decision grid ───────────────────────────────────── */
  .cix-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: var(--space-md);
    align-items: start;
    list-style: none;
    padding: 0;
    margin: 0;
  }
  .cix-grid-item {
    min-width: 0;
    align-self: start;
  }
  .cix-card {
    position: relative;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    border: 1px solid var(--color-border);
    border-radius: var(--tt-surface-radius-info, 12px);
    background: var(--color-surface);
    text-decoration: none;
    color: inherit;
    box-shadow: 0 4px 14px color-mix(in srgb, var(--color-text) 4%, transparent);
    transition:
      transform 180ms ease-out,
      border-color 180ms ease-out,
      box-shadow 180ms ease-out;
  }
  .cix-card:hover {
    border-color: var(--color-border-strong);
    box-shadow: 0 8px 22px color-mix(in srgb, var(--color-text) 8%, transparent);
    transform: translateY(-2px);
  }
  .cix-card-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: var(--space-md);
    padding: var(--space-md) var(--space-lg);
    background: var(--color-surface-soft);
  }
  .cix-card-identity {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--space-sm);
    min-width: 0;
  }
  .cix-card-logos {
    display: flex;
    align-items: center;
    flex-shrink: 0;
  }
  .cix-card-logo {
    display: inline-flex;
    padding: 6px;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-sm);
    background: var(--color-surface);
  }
  .cix-card-logo--second {
    margin-left: -10px;
  }
  .cix-card-eyebrow {
    display: block;
    margin-bottom: var(--space-2xs);
    font-family: var(--font-ui);
    font-size: var(--tt-size-kicker);
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-muted);
  }
  .cix-card-title {
    margin: 0;
    font-family: var(--font-brand);
    font-size: 19px;
    font-weight: 700;
    letter-spacing: -0.03em;
    line-height: 1.15;
    color: var(--color-text-strong);
  }
  .cix-card-title span {
    color: var(--color-muted-light);
    font-weight: 500;
  }
  .cix-card-summary {
    display: block;
    margin: var(--space-sm) 0 0;
    font-family: var(--font-ui);
    font-size: 14px;
    font-weight: 450;
    line-height: 1.4;
    color: var(--color-muted);

  }
  .cix-card-arrow {
    flex: 0 0 auto;
    color: var(--color-muted);
    transition: transform 180ms ease-out, color 180ms ease-out;
  }
  .cix-card:hover .cix-card-arrow {
    color: var(--color-text);
    transform: translate(2px, -2px);
  }
  .cix-load-more {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--space-xs);
    padding-top: var(--space-xl);
  }
  .cix-load-more-button {
    min-height: 44px;
    padding: 0 var(--space-lg);
    border: 1px solid var(--color-text);
    border-radius: var(--radius-pill);
    background: var(--color-text);
    font-family: var(--font-ui);
    font-size: 15px;
    font-weight: 650;
    color: var(--color-surface);
    cursor: pointer;
    transition: transform 160ms ease-out, background 160ms ease-out;
  }
  .cix-load-more-button:hover {
    transform: translateY(-1px);
    background: var(--color-text-strong);
  }
  .cix-load-more-button:active {
    transform: translateY(-1px) scale(0.97);
  }
  .cix-load-more-button:focus-visible {
    outline: 2px solid var(--color-text);
    outline-offset: 3px;
  }
  .cix-load-more-meta {
    margin: 0;
    font-family: var(--font-ui);
    font-size: 13px;
    color: var(--color-muted);
  }
  @media (max-width: 1100px) {
    .cix-toolbar {
      flex-wrap: wrap;
    }
    .cix-filter-group {
      flex: 1 1 auto;
    }
    .cix-popular {
      order: 3;
      flex-basis: 100%;
      padding: var(--space-sm) 0 0;
      border-top: 1px solid var(--color-border-soft);
      border-left: 0;
    }
    .cix-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  }
  @media (max-width: 640px) {
    .cix-grid { grid-template-columns: 1fr; }
    .cix-hero {
      padding: var(--space-lg) 0;
    }
    .cix-card {
      border-radius: var(--radius-lg);
    }
    .cix-card-head {
      padding: var(--space-md);
    }
    .cix-toolbar {
      align-items: stretch;
    }
    .cix-filter-group,
    .cix-filter-group .tt-catalog-toolbar-filters {
      width: 100%;
    }
    .cix-controls-count {
      padding-left: 0;
      border-left: 0;
      text-align: right;
    }
    .cix-card-identity { align-items: flex-start; }
    .cix-card-logos { margin-top: 2px; }
  }

  /* ── Empty state ─────────────────────────────────────── */
  .cix-empty {
    padding: 48px 0;
    border-top: 1px solid var(--color-border);
    max-width: 640px;
  }
  .cix-empty-title {
    font-family: var(--font-brand);
    font-size: clamp(1.25rem, 2.5vw, 1.75rem);
    font-weight: 600;
    letter-spacing: -0.03em;
    color: var(--color-text);
    margin: 0 0 8px;
  }
  .cix-empty-desc {
    font-family: var(--font-ui);
    font-size: var(--tt-size-body);
    color: var(--color-muted);
    margin: 0 0 20px;
  }
  .cix-empty-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-bottom: 24px;
  }
  .cix-empty-reset {
    display: inline-flex;
    align-items: center;
    height: 38px;
    padding: 0 18px;
    border: 1px solid var(--color-border-strong);
    border-radius: var(--radius-sm);
    background: transparent;
    font-family: var(--font-ui);
    font-size: 14px;
    font-weight: 500;
    color: var(--color-text);
    cursor: pointer;
    transition: background 140ms, color 140ms;
  }
  .cix-empty-reset:hover {
    background: var(--color-text);
    color: var(--color-surface);
  }

}

/* ─────────────────────────────────────────────
   HOME PAGE REPOSITIONNEMENT (hp-*)
   Sprint Home — sections spécifiques à la home
   repositionnée autour de l'audit de stack.
───────────────────────────────────────────── */
@layer components {

  /* ── What we cut — "Ce que ToolTrim coupe" ── */
  .hp-cuts {
    border-top: 1px solid var(--color-border);
    background: var(--color-surface);
  }

  .hp-cuts-inner {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 80px;
    align-items: start;
  }

  @media (max-width: 899px) {
    .hp-cuts-inner {
      grid-template-columns: 1fr;
      gap: 40px;
    }
  }

  .hp-cuts-heading {
    font-family: var(--font-brand);
    font-size: clamp(1.75rem, 3vw, 2.75rem);
    font-weight: 600;
    color: var(--color-text);
    letter-spacing: -0.04em;
    line-height: 1.15;
  }

  .hp-cuts-label {
    font-family: var(--font-ui);
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-muted-light);
    margin-bottom: 20px;
  }

  .hp-cuts-cta {
    margin-top: 36px;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    height: 48px;
    padding: 0 24px;
    background: var(--color-text);
    color: var(--color-surface);
    border-radius: var(--radius);
    font-family: var(--font-ui);
    font-size: 15px;
    font-weight: 500;
    text-decoration: none;
    letter-spacing: -0.01em;
    transition: opacity 160ms ease-out;
  }
  .hp-cuts-cta:hover {
    opacity: 0.8;
  }

}

/* ─────────────────────────────────────────────
   HOME PAGE IDENTITÉ (hp-* Sprint 4)
   Hero 2-col, Audit Preview, Decisions,
   Cut Rows, Avant/Après, Méthode
───────────────────────────────────────────── */
@layer components {

  /* ── Hero 2-col layout ─────────────────────────────────────────── */
  .hp-hero-2col {
    display: grid;
    grid-template-columns: 1fr 420px;
    gap: 64px;
    align-items: center;
    width: 100%;
    padding-top: 80px;
    padding-bottom: 72px;
  }

  @media (max-width: 1100px) {
    .hp-hero-2col {
      grid-template-columns: 1fr;
      gap: 48px;
      padding-top: 60px;
      padding-bottom: 60px;
    }
  }

  .hp-hero-left {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
  }

  .hp-hero-right {
    display: flex;
    flex-direction: column;
  }

  @media (max-width: 1100px) {
    .hp-hero-right {
      max-width: 480px;
    }
  }

  /* ── Stack Audit Preview ──────────────────────────────────────── */
  .hp-audit {
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
    overflow: hidden;
    box-shadow: 0 2px 12px rgba(0,0,0,0.06);
  }

  .hp-audit-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 18px;
    border-bottom: 1px solid var(--color-border-soft);
    background: var(--color-bg);
  }

  .hp-audit-header-label {
    font-family: var(--font-ui);
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-muted-light);
  }

  .hp-audit-header-budget {
    font-family: var(--font-ui);
    font-size: 12px;
    font-weight: 500;
    color: var(--color-muted);
  }

  .hp-audit-row {
    display: grid;
    grid-template-columns: 28px 1fr auto auto;
    align-items: center;
    gap: 10px;
    padding: 12px 18px;
    border-bottom: 1px solid var(--color-border-soft);
    position: relative;
    cursor: default;
  }

  .hp-audit-row:last-of-type {
    border-bottom: none;
  }

  .hp-audit-logo {
    width: 28px;
    height: 28px;
    border-radius: var(--radius-circle);
    background: var(--color-bg);
    border: 1px solid var(--color-border-soft);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    overflow: hidden;
  }

  .hp-audit-logo img {
    width: 18px;
    height: 18px;
    object-fit: contain;
  }

  .hp-audit-logo-letter {
    font-family: var(--font-ui);
    font-size: 11px;
    font-weight: 700;
    color: var(--color-muted);
    line-height: 1;
  }

  .hp-audit-tool-name {
    font-family: var(--font-ui);
    font-size: 13px;
    font-weight: 500;
    color: var(--color-text);
    white-space: nowrap;
  }

  .hp-audit-badge {
    font-family: var(--font-ui);
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.04em;
    padding: 3px 8px;
    border-radius: var(--radius-pill);
    white-space: nowrap;
    flex-shrink: 0;
  }

  .hp-audit-price {
    font-family: var(--font-ui);
    font-size: 12px;
    color: var(--color-muted-light);
    white-space: nowrap;
    flex-shrink: 0;
    min-width: 38px;
    text-align: right;
  }

  /* Hover "Pourquoi?" reveal — pure CSS */
  .hp-audit-why {
    position: absolute;
    inset: 0;
    background: rgba(255,255,255,0.96);
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: var(--font-ui);
    font-size: 12px;
    color: var(--color-muted);
    opacity: 0;
    transition: opacity 140ms ease-out;
    pointer-events: none;
    padding: 0 18px;
    text-align: center;
    border-bottom: 1px solid var(--color-border-soft);
  }

  .hp-audit-row:hover .hp-audit-why {
    opacity: 1;
  }

  .hp-audit-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 18px;
    background: var(--color-bg);
  }

  .hp-audit-footer-budget {
    display: flex;
    flex-direction: column;
    gap: 2px;
  }

  .hp-audit-footer-label {
    font-family: var(--font-ui);
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    color: var(--color-muted-light);
  }

  .hp-audit-footer-amount {
    font-family: var(--font-brand);
    font-size: 17px;
    font-weight: 600;
    color: var(--color-text);
    letter-spacing: -0.03em;
    line-height: 1;
  }

  .hp-audit-footer-saving {
    font-family: var(--font-ui);
    font-size: 11px;
    font-weight: 600;
    color: #166534;
    background: #ECFDF0;
    padding: 4px 10px;
    border-radius: var(--radius-pill);
  }

  .hp-audit-mini-cta {
    margin: 14px 18px 0;
    display: flex;
    align-items: center;
    justify-content: center;
    height: 38px;
    border: 1px solid var(--color-border);
    border-radius: var(--radius);
    font-family: var(--font-ui);
    font-size: 13px;
    font-weight: 500;
    color: var(--color-text);
    text-decoration: none;
    gap: 6px;
    transition: background 160ms ease-out, border-color 160ms ease-out;
    margin-bottom: 14px;
  }

  .hp-audit-mini-cta:hover {
    background: var(--color-bg);
    border-color: var(--color-text);
  }

  .hp-audit-disclaimer {
    padding: 0 18px 14px;
    font-family: var(--font-ui);
    font-size: 10px;
    color: var(--color-muted-light);
    text-align: center;
    font-style: italic;
  }

  /* hp-entry-example now defined in hp-entries block (Sprint 4c) */

  /* ── Cut rows — decision-style list ────────────────────────────── */
  .hp-cut-rows {
    display: flex;
    flex-direction: column;
    gap: 0;
  }

  .hp-cut-row {
    padding: 20px 0;
    border-bottom: 1px solid var(--color-border-soft);
    display: flex;
    flex-direction: column;
    gap: 4px;
  }

  .hp-cut-row:first-child {
    border-top: 1px solid var(--color-border-soft);
  }

  .hp-cut-row-example {
    font-family: var(--font-ui);
    font-size: 13px;
    color: var(--color-muted-light);
    font-style: italic;
    padding-left: 18px;
    line-height: 1.4;
  }

  /* ── Méthode section ────────────────────────────────────────────── */
  .hp-methode {
    background: var(--color-surface);
    border-top: 1px solid var(--color-border);
  }

  .hp-methode-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 0;
    border-top: 1px solid var(--color-border);
    margin-top: 48px;
  }

  .hp-methode-subtitle {
    font-family: var(--font-ui);
    font-size: 18px;
    line-height: 1.45;
    color: var(--color-muted);
    max-width: 680px;
    margin: 18px 0 0;
  }

  @media (max-width: 767px) {
    .hp-methode-grid {
      grid-template-columns: 1fr;
    }
    .hp-methode-step + .hp-methode-step {
      border-top: 1px solid var(--color-border);
      border-left: none !important;
    }
  }

  .hp-methode-step {
    padding: 36px 32px;
    display: flex;
    flex-direction: column;
    gap: 14px;
  }

  .hp-methode-step + .hp-methode-step {
    border-left: 1px solid var(--color-border);
  }

  .hp-methode-num {
    font-family: var(--font-brand);
    font-size: clamp(2rem, 4vw, 3.25rem);
    font-weight: 600;
    color: var(--color-border-soft);
    letter-spacing: -0.06em;
    line-height: 1;
  }

  .hp-methode-title {
    font-family: var(--font-brand);
    font-size: clamp(1rem, 1.5vw, 1.1875rem);
    font-weight: 600;
    color: var(--color-text);
    letter-spacing: -0.025em;
    line-height: 1.25;
  }

  .hp-methode-desc {
    font-family: var(--font-ui);
    font-size: 14px;
    line-height: 1.65;
    color: var(--color-muted);
    flex: 1;
  }

  .hp-methode-example {
    font-family: var(--font-ui);
    font-size: 12px;
    color: var(--color-muted-light);
    font-style: italic;
    line-height: 1.4;
    padding: 10px 14px;
    background: var(--color-bg);
    border-radius: var(--radius-sm);
    border-left: 2px solid var(--color-border);
  }

}

/* ─────────────────────────────────────────────
   HOME ACTION CARDS (hac-*) Sprint 4d
   3 cards contour noir · header tableau
   logos outils · scénario · capsule verdict
───────────────────────────────────────────── */
@layer components {

  /* ── Card ────────────────────────────────── */
  .hac-card {
    background: var(--color-bg);
    border: 1.5px solid var(--color-border-strong);
    border-radius: var(--radius-md);
    overflow: hidden;
    display: flex;
    flex-direction: column;
    text-decoration: none;
    transition: background 160ms ease-out, transform 160ms ease-out;
    cursor: pointer;
  }

  .hac-card:hover {
    background: var(--color-surface);
    transform: translateY(-1px);
  }

  /* ── Header — style tableau ──────────────── */
  .hac-header {
    display: grid;
    grid-template-columns: 1fr auto;
    align-items: center;
    border-bottom: 1.5px solid var(--color-border-strong);
    padding: 12px 16px;
    background: inherit;
  }

  .hac-header-label,
  .hac-header-num {
    font-family: var(--font-ui);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-text);
    line-height: 1;
  }

  /* ── Body ────────────────────────────────── */
  .hac-body {
    padding: 20px 16px 18px;
    display: flex;
    flex-direction: column;
    flex: 1;
  }

  .hac-title {
    font-family: var(--font-brand);
    font-size: clamp(1.5rem, 2.2vw, 1.75rem);
    line-height: 1.05;
    letter-spacing: -0.04em;
    font-weight: 600;
    color: var(--color-text);
    margin: 0 0 12px;
  }

  .hac-desc {
    font-family: var(--font-ui);
    font-size: 15px;
    line-height: 1.45;
    color: var(--color-muted);
    max-width: 340px;
    margin: 0;
  }

  /* ── Scénario block ──────────────────────── */
  .hac-scenario {
    border-top: 1px solid var(--color-border);
    padding-top: 14px;
    margin-top: 18px;
    display: flex;
    flex-direction: column;
  }

  .hac-scenario-label {
    font-family: var(--font-ui);
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-muted-light);
    margin-bottom: 10px;
    display: block;
  }

  /* Logo pills row */
  .hac-logos {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
  }

  .hac-logo {
    width: 30px;
    height: 30px;
    border-radius: var(--radius-pill);
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    flex-shrink: 0;
  }

  .hac-logo img {
    max-width: 18px;
    max-height: 18px;
    object-fit: contain;
    display: block;
  }

  .hac-logo-letter {
    font-family: var(--font-ui);
    font-size: 12px;
    font-weight: 700;
    color: var(--color-muted);
    line-height: 1;
  }

  .hac-vs-sep {
    font-family: var(--font-ui);
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--color-muted-light);
    flex-shrink: 0;
  }

  .hac-scenario-text {
    font-family: var(--font-ui);
    font-size: 13px;
    line-height: 1.4;
    color: var(--color-muted);
    margin: 8px 0 0;
  }

  /* Verdict capsule */
  .hac-capsule {
    display: inline-flex;
    align-items: center;
    height: 26px;
    padding: 0 10px;
    border: 1px solid var(--color-border-strong);
    border-radius: var(--radius-pill);
    font-family: var(--font-ui);
    font-size: 12px;
    font-weight: 600;
    color: var(--color-text);
    background: transparent;
    width: fit-content;
    margin-top: 12px;
    flex-shrink: 0;
  }

  /* ── CTA ─────────────────────────────────── */
  .hac-cta {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-family: var(--font-ui);
    font-size: 15px;
    font-weight: 700;
    color: var(--color-text);
    text-decoration: none;
    margin-top: auto;
    padding-top: 18px;
  }

  .hac-card:hover .hac-cta {
    text-decoration: underline;
    text-underline-offset: 4px;
  }

  .hac-cta-arrow {
    transition: transform 160ms ease-out;
    flex-shrink: 0;
  }

  .hac-card:hover .hac-cta-arrow {
    transform: translateX(3px);
  }

}

/* ─────────────────────────────────────────────
   HOME ACTIONS SECTION (Sprint 5)
   Remplace hac-section : titre éditorial +
   espacement design-system
───────────────────────────────────────────── */
@layer components {

  /* ── Section wrapper ─────────────────────── */
  .home-actions-section {
    background: var(--color-bg);
    padding: var(--space-3xl) 0 72px;
    border-bottom: 1px solid var(--color-border);
  }

  @media (max-width: 767px) {
    .home-actions-section {
      padding: var(--space-2xl) 0 56px;
    }
  }

  /* ── Section header ──────────────────────── */
  .home-actions-header {
    max-width: 760px;
    margin-bottom: var(--space-2xl);
  }

  .home-actions-eyebrow {
    font-family: var(--font-ui);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-muted-light);
    margin-bottom: 14px;
    display: block;
  }

  .home-actions-title {
    font-family: var(--font-brand);
    font-size: clamp(2.25rem, 4vw, 3.5rem);
    line-height: 1;
    letter-spacing: -0.05em;
    font-weight: 600;
    color: var(--color-text);
    margin: 0;
  }

  .home-actions-desc {
    font-family: var(--font-ui);
    font-size: 17px;
    line-height: 1.45;
    color: var(--color-muted);
    margin-top: 16px;
    max-width: 680px;
  }

  /* ── Cards grid ──────────────────────────── */
  .home-actions-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 16px;
  }

  @media (max-width: 767px) {
    .home-actions-grid {
      grid-template-columns: 1fr;
      gap: 14px;
    }
  }

}

/* ─────────────────────────────────────────────
   SPRINT 7 — Grille globale homepage
   Alignement horizontal · H1 responsive · Spacing
   Règle : toutes les sections partagent le même axe visuel.
───────────────────────────────────────────── */
@layer components {

  /* ── 1. Container : aligner es-container sur eh-container ── */
  /* es-container était 1440px, eh-container est 1280px → même axe */
  .es-container {
    max-width: 1280px;
  }

  /* ── 2. Hero 2-col : grille contrôlée et padding clamp ── */
  .hp-hero-2col {
    grid-template-columns: minmax(0, 1fr) minmax(360px, 440px);
    gap: clamp(3.5rem, 6vw, 6rem);          /* 56px → 96px */
    padding-top:    clamp(4.5rem, 7vw, 7rem);  /* 72px → 112px */
    padding-bottom: clamp(4rem, 6vw, 6rem);    /* 64px → 96px */
  }

  /* Collapse tablet — reprend le 1100px du bloc Sprint 4 */
  @media (max-width: 1100px) {
    .hp-hero-2col {
      grid-template-columns: 1fr;
      gap: 48px;
      padding-top:    clamp(2.5rem, 8vw, 3.75rem);
      padding-bottom: clamp(2rem,   6vw, 3rem);
    }
  }

  @media (max-width: 639px) {
    .hp-hero-2col {
      padding-top:    clamp(2rem, 8vw, 3rem);
      padding-bottom: clamp(1.75rem, 6vw, 2.5rem);
    }
  }

  /* ── 3. Preview card droite ── */
  .hp-hero-right {
    max-width: 440px;
    width: 100%;
    align-self: center;
    justify-self: end;
  }

  /* Single-col : réaligner à gauche */
  @media (max-width: 1100px) {
    .hp-hero-right {
      justify-self: start;
      max-width: 480px;
    }
  }

  /* ── 4. H1 hero home — override scoped ── */
  .hp-hero-left .eh-title {
    font-size: clamp(4rem, 6.5vw, 7rem);  /* 64px → 112px */
    line-height: 0.9;
    letter-spacing: -0.07em;
    max-width: 720px;
  }

  /* Cap sur très grands écrans ≥ 1600px → 108px max */
  @media (min-width: 1600px) {
    .hp-hero-left .eh-title {
      font-size: clamp(4rem, 6.5vw, 6.75rem);
    }
  }

  @media (max-width: 639px) {
    .hp-hero-left .eh-title {
      font-size: clamp(2.75rem, 11vw, 3.5rem);
      letter-spacing: -0.05em;
      max-width: 100%;
    }
  }

  /* ── 5. H2 section "Commence par la bonne question" ── */
  .home-actions-title {
    font-size: clamp(2.5rem, 4vw, 4rem);  /* 40px → 64px */
    line-height: 0.98;
    letter-spacing: -0.055em;
    max-width: 720px;
  }

  /* ── 6. Section actions : padding tokens corrects ── */
  .home-actions-section {
    padding: var(--space-3xl) 0 var(--space-4xl);  /* 64px 0 96px */
  }

  @media (max-width: 767px) {
    .home-actions-section {
      padding: var(--space-2xl) 0 var(--space-3xl);  /* 48px 0 64px */
    }
  }

  /* ── 7. Cards : hauteur cohérente ── */
  .home-actions-grid {
    align-items: stretch;
  }

  .hac-card {
    height: 100%;
  }

}

/* ─────────────────────────────────────────────
   SPRINT 7b — Correction H1 hero et padding
   Override Sprint 7 : font-size trop grand.
   5 <br /> forcés → la taille contrôle tout.
───────────────────────────────────────────── */
@layer components {

  /* H1 hero : 44px → 68px (spectaculaire mais contenu) */
  .hp-hero-left .eh-title {
    font-size: clamp(2.75rem, 4.5vw, 4.25rem);
    line-height: 0.92;
    letter-spacing: -0.065em;
    max-width: 640px;
  }

  /* Reset du cap 1600px — le clamp gère déjà */
  @media (min-width: 1600px) {
    .hp-hero-left .eh-title {
      font-size: clamp(2.75rem, 4.5vw, 4.5rem);
    }
  }

  /* Mobile */
  @media (max-width: 639px) {
    .hp-hero-left .eh-title {
      font-size: clamp(2rem, 9vw, 2.75rem);
      letter-spacing: -0.05em;
      max-width: 100%;
    }
  }

  /* Hero padding : moins agressif */
  .hp-hero-2col {
    padding-top:    clamp(3rem, 4.5vw, 4.5rem);   /* 48px → 72px */
    padding-bottom: clamp(2.5rem, 4vw, 4rem);      /* 40px → 64px */
  }

  @media (max-width: 1100px) {
    .hp-hero-2col {
      padding-top:    clamp(2.5rem, 6vw, 3.5rem);
