@layer components {
  /* Recherche globale (refonte du 9 oct. 2026) : une colonne façon Spotlight,
     posée vers le haut de l'écran. Avant la frappe elle guide (exemples,
     besoins, duels, stacks), pendant la frappe elle range par type. */
  .gs-overlay {
    position: fixed;
    inset: 0;
    z-index: 1100;
    display: flex;
    align-items: flex-start;
    justify-content: center;
    padding: min(12vh, 120px) var(--space-lg) var(--space-lg);
    background: color-mix(in srgb, var(--color-text-strong) 32%, transparent);
    backdrop-filter: blur(8px);
  }
  /* Une seule surface de carte, chaude comme la palette du site (#F6F5F4,
     survol #EDEBE9) ; en sombre, un cran au-dessus du fond du dialogue. */
  .gs-dialog {
    --gs-fill: var(--color-bg-warm);
    --gs-fill-hover: var(--color-surface-warm);
    display: flex;
    flex-direction: column;
    width: min(720px, 100%);
    max-height: min(720px, calc(100dvh - min(12vh, 120px) - var(--space-lg)));
    overflow: hidden;
    border: 1px solid var(--color-border-soft);
    border-radius: var(--radius-xl);
    background: var(--color-surface);
    box-shadow: 0 24px 64px color-mix(in srgb, var(--color-text-strong) 18%, transparent);
    animation: gs-enter 180ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
  }

  .gs-searchbar {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
    flex: none;
    min-height: 60px;
    padding: 0 var(--space-sm) 0 var(--space-lg);
    border-bottom: 1px solid var(--color-border-soft);
    color: var(--color-text-meta);
  }
  .gs-searchbar > svg { flex: none; width: 20px; height: 20px; }
  .gs-searchbar input {
    flex: 1;
    min-width: 0;
    border: 0;
    outline: 0;
    background: transparent;
    color: var(--color-text-strong);
    font-family: var(--font-ui);
    font-size: 18px;
    font-weight: 450;
    letter-spacing: -0.015em;
  }
  .gs-searchbar input::placeholder { color: var(--color-text-meta); }
  .gs-clear {
    flex: none;
    min-height: 32px;
    padding: 0 var(--space-xs);
    border: 0;
    border-radius: var(--radius-sm);
    background: transparent;
    color: var(--color-text-meta);
    font: 500 13px/1 var(--font-ui);
    cursor: pointer;
  }
  .gs-clear:hover { color: var(--color-text-strong); }
  .gs-icon-button {
    display: grid;
    flex: none;
    width: 36px;
    height: 36px;
    place-items: center;
    border: 0;
    border-radius: var(--radius-pill);
    background: transparent;
    color: var(--color-text-meta);
    cursor: pointer;
    transition: background-color 140ms ease-out, color 140ms ease-out;
  }
  .gs-icon-button:hover { background: var(--gs-fill); color: var(--color-text-strong); }
  .gs-icon-button svg { width: 18px; height: 18px; }

  .gs-body { flex: 1; min-height: 0; overflow-y: auto; overscroll-behavior: contain; }

  /* Libellé de section : le surtitre du site (--tt-size-kicker, capitales),
     comme « PRÉFÉRENCES » dans le menu mobile. */
  .gs-label {
    margin: 0 0 var(--space-xs);
    color: var(--color-text-meta);
    font: 600 var(--tt-size-kicker)/1.2 var(--font-ui);
    letter-spacing: 0.06em;
    text-transform: uppercase;
  }

  /* Avant la frappe : le corps passe sur le fond chaud du site et les
     éléments deviennent des cartes blanches, légèrement surélevées. Le
     contraste naît de la profondeur, la couleur des vrais logos ; chaque
     section a sa forme (pastilles, tuiles, face-à-face, lignes). */
  .gs-body:has(.gs-guide) { background: var(--gs-fill); }
  .gs-guide { display: grid; gap: var(--space-lg); padding: var(--space-md) var(--space-lg) var(--space-lg); }
  .gs-card {
    border-radius: var(--radius-md);
    background: var(--color-surface);
    box-shadow: 0 0 0 1px var(--color-border-soft), 0 1px 2px color-mix(in srgb, var(--color-text-strong) 6%, transparent);
    transition: box-shadow 160ms ease-out, transform 160ms cubic-bezier(0.2, 0.8, 0.2, 1);
  }
  .gs-chips { display: flex; flex-wrap: wrap; gap: var(--space-xs); }
  .gs-chip {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2xs);
    min-height: 32px;
    padding: 0 var(--space-sm);
    border: 0;
    border-radius: var(--radius-pill);
    background: var(--color-surface);
    box-shadow: 0 0 0 1px var(--color-border-soft);
    color: var(--color-text-strong);
    font: 500 var(--tt-size-card-body)/1 var(--font-ui);
    text-decoration: none;
    cursor: pointer;
    transition: box-shadow 140ms ease-out, background-color 140ms ease-out;
  }
  .gs-chip:hover, .gs-chip:focus-visible { box-shadow: 0 0 0 1px var(--color-muted); }
  .gs-chip svg { width: 14px; height: 14px; color: var(--color-text-meta); }

  /* Besoins : trois logos des outils les plus demandés, puis le libellé. */
  .gs-needs { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: var(--space-xs); margin: 0; padding: 0; list-style: none; }
  .gs-need {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: space-between;
    gap: var(--space-sm);
    height: 100%;
    padding: var(--space-sm);
    color: var(--color-text-strong);
    text-decoration: none;
  }
  .gs-need-logos { display: flex; min-height: 22px; }
  .gs-need-logo { display: grid; border-radius: var(--radius-sm); box-shadow: 0 0 0 2px var(--color-surface); transition: transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1); }
  .gs-need-logo + .gs-need-logo { margin-left: -5px; }
  .gs-need:is(:hover, :focus-visible) .gs-need-logo:nth-child(1) { transform: translateX(-2px) rotate(-6deg); }
  .gs-need:is(:hover, :focus-visible) .gs-need-logo:nth-child(3) { transform: translateX(2px) rotate(6deg); }
  .gs-need-label { font: 600 var(--tt-size-card-body)/1.2 var(--font-ui); text-wrap: balance; }

  /* Duels : le point focal. Deux grands logos en face-à-face, inclinés,
     qui s'écartent au survol comme les cartes « Lequel garder ? ». */
  .gs-duels { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--space-xs); margin: 0; padding: 0; list-style: none; }
  .gs-duel {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--space-sm);
    padding: var(--space-md) var(--space-xs) var(--space-sm);
    color: var(--color-text-strong);
    text-align: center;
    text-decoration: none;
  }
  .gs-duel-logos { position: relative; display: flex; align-items: center; }
  .gs-duel-logo { display: grid; border-radius: var(--radius-md); box-shadow: 0 0 0 3px var(--color-surface), 0 4px 10px color-mix(in srgb, var(--color-text-strong) 10%, transparent); transition: transform 200ms cubic-bezier(0.2, 0.8, 0.2, 1); }
  .gs-duel-logo--a { transform: rotate(-7deg); }
  .gs-duel-logo--b { margin-left: -8px; transform: rotate(6deg); }
  .gs-duel-vs {
    position: absolute;
    left: 50%;
    bottom: -6px;
    z-index: 1;
    padding: 1px 6px;
    border-radius: var(--radius-pill);
    background: var(--color-text-strong);
    color: var(--color-surface);
    font: 700 10px/1.4 var(--font-ui);
    letter-spacing: 0.02em;
    transform: translateX(-50%);
    transition: transform 200ms cubic-bezier(0.2, 0.8, 0.2, 1);
  }
  .gs-duel:is(:hover, :focus-visible) .gs-duel-logo--a { transform: translateX(-6px) rotate(-11deg); }
  .gs-duel:is(:hover, :focus-visible) .gs-duel-logo--b { transform: translateX(6px) rotate(10deg); }
  .gs-duel:is(:hover, :focus-visible) .gs-duel-vs { transform: translateX(-50%) scale(1.08); }
  .gs-duel-name { max-width: 100%; overflow: hidden; font: 600 13px/1.3 var(--font-ui); text-overflow: ellipsis; white-space: nowrap; }
  .gs-duel-name span { color: var(--color-text-meta); font-weight: 400; }

  /* Stacks : lignes, le dossier iOS de l'accueil en tête. */
  .gs-stacks { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-xs); margin: 0; padding: 0; list-style: none; }
  .gs-stack, .gs-mystack {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
    min-height: 56px;
    padding: var(--space-xs) var(--space-sm);
    color: var(--color-text-strong);
    text-decoration: none;
  }
  .gs-stack-folder {
    display: grid;
    flex: none;
    grid-template-columns: repeat(2, 18px);
    gap: var(--space-2xs);
    padding: 5px;
    border-radius: var(--radius-md);
    background: var(--gs-fill);
  }
  .gs-stack-app { display: grid; }

  /* Survol commun : la carte se soulève d'un pixel, l'ombre s'allonge. */
  .gs-card:is(:hover, :focus-visible) {
    box-shadow: 0 0 0 1px var(--color-border-soft), 0 6px 16px color-mix(in srgb, var(--color-text-strong) 10%, transparent);
    transform: translateY(-1px);
  }

  /* Pendant la frappe */
  .gs-results { padding: var(--space-md) var(--space-xs) var(--space-xs); }
  .gs-group + .gs-group { margin-top: var(--space-md); }
  .gs-group .gs-label { margin: 0 var(--space-md) var(--space-2xs); }
  .gs-result {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
    width: 100%;
    min-height: 48px;
    padding: var(--space-xs) var(--space-md);
    border: 0;
    border-radius: var(--radius-md);
    background: transparent;
    color: var(--color-text-strong);
    text-align: left;
    cursor: pointer;
  }
  .gs-result.is-active { background: var(--gs-fill); }
  .gs-result-icon {
    display: grid;
    flex: none;
    width: 32px;
    height: 32px;
    place-items: center;
    border-radius: var(--radius-sm);
    background: var(--gs-fill);
    color: var(--color-text-strong);
  }
  .gs-result.is-active .gs-result-icon { background: var(--color-surface); }
  .gs-result-icon svg { width: 16px; height: 16px; }
  .gs-result-text { display: grid; flex: 1; min-width: 0; gap: 2px; }
  .gs-result-text strong { overflow: hidden; font: 600 var(--tt-size-card-body)/1.25 var(--font-ui); text-overflow: ellipsis; white-space: nowrap; }
  .gs-result-text small { overflow: hidden; color: var(--color-text-meta); font: 400 12px/1.3 var(--font-ui); text-overflow: ellipsis; white-space: nowrap; }
  .gs-result-arrow { flex: none; width: 16px; height: 16px; color: var(--color-text-meta); opacity: 0; transition: opacity 120ms ease-out, transform 120ms ease-out; transform: translateX(-4px); }
  /* Même règle partout : la flèche apparaît sur l'élément visé (survol,
     focus clavier, option active), jamais en permanence. */
  .gs-result.is-active .gs-result-arrow,
  :is(.gs-duel, .gs-stack, .gs-mystack):is(:hover, :focus-visible) .gs-result-arrow { opacity: 1; transform: none; }
  .gs-view-all {
    display: flex;
    align-items: center;
    gap: var(--space-2xs);
    width: 100%;
    min-height: 44px;
    margin-top: var(--space-xs);
    padding: 0 var(--space-md);
    border: 0;
    border-top: 1px solid var(--color-border-soft);
    background: transparent;
    color: var(--color-text-secondary);
    font: 500 13px/1.2 var(--font-ui);
    text-align: left;
    cursor: pointer;
  }
  .gs-view-all:hover { color: var(--color-text-strong); }
  .gs-view-all svg { width: 14px; height: 14px; }

  .gs-empty { display: grid; gap: var(--space-xs); padding: var(--space-lg); }
  .gs-empty-title { margin: 0; color: var(--color-text-strong); font: 600 var(--tt-size-card-title)/1.3 var(--font-ui); }
  .gs-empty-text { margin: 0 0 4px; color: var(--color-text-meta); font: 400 13px/1.4 var(--font-ui); }

  .dark .gs-body:has(.gs-guide) { background: var(--color-bg); }
  .dark .gs-dialog { --gs-fill: var(--color-surface-warm); --gs-fill-hover: color-mix(in srgb, var(--color-text-strong) 12%, var(--color-surface)); }

  .gs-dialog :where(a, button, input):focus-visible { outline: 2px solid var(--color-text-strong); outline-offset: 2px; }
  .gs-searchbar input:focus-visible { outline: 0; }

  @keyframes gs-enter {
    from { opacity: 0; transform: translateY(-8px) scale(0.985); }
    to { opacity: 1; transform: none; }
  }
  /* Sortie : plus courte que l'entrée, accélérée (ease-in). */
  @keyframes gs-leave { to { opacity: 0; transform: translateY(-4px) scale(0.99); } }
  @keyframes gs-fade-out { to { opacity: 0; } }
  .gs-overlay.is-closing { animation: gs-fade-out 120ms ease-in both; }
  .gs-overlay.is-closing .gs-dialog { animation: gs-leave 120ms ease-in both; }
  @media (prefers-reduced-motion: reduce) {
    .gs-dialog, .gs-overlay.is-closing, .gs-overlay.is-closing .gs-dialog { animation: none; }
    .gs-result-arrow, .gs-need-icon, .gs-duel-logo { transition: none; }
  }

  @media (max-width: 640px) {
    .gs-overlay { padding: 0; }
    .gs-dialog { width: 100%; max-height: none; height: 100dvh; border: 0; border-radius: 0; }
    .gs-searchbar { padding-left: var(--space-md); }
    .gs-searchbar input { font-size: 17px; }
    .gs-guide { padding: var(--space-md) var(--space-md) var(--space-lg); }
    .gs-stacks { grid-template-columns: minmax(0, 1fr); }
    .gs-duels, .gs-needs { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    /* Cibles tactiles de 44 px au doigt. */
    .gs-icon-button, .gs-clear { min-width: 44px; min-height: 44px; }
    .gs-icon-button { width: 44px; height: 44px; }
    .gs-chip { min-height: 44px; padding: 0 var(--space-md); }
  }
}

