/* ── Shared floating capsule section nav (tool / stack / comparatif) ──────
   Single source of truth. Was duplicated as .stack-sticky-nav and
   .compare-sticky-nav; now one .tt-pillnav system, tokenized on --color-ink. */
.tt-pillnav {
  position: fixed;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%) translateY(0);
  z-index: 60;
  display: flex;
  align-items: center;
  gap: 8px;
  max-width: min(calc(100vw - 32px), 860px);
  background: var(--color-ink);
  border-radius: var(--radius-xl);
  padding: 8px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.24), 0 2px 8px rgba(0, 0, 0, 0.12);
  border: 1px solid var(--color-ink-border);
  opacity: 1;
  transition: opacity 220ms ease, transform 220ms ease;
  /* A fixed + rounded + shadowed element whose transform/opacity animates
     during an active scroll (the hero-visibility observer can flip mid
     smooth-scroll) is a known trigger for a brief black compositor flash
     on Chrome/Android. Promoting it to its own stable GPU layer up front
     avoids the mid-scroll re-rasterization that causes it. */
  will-change: transform, opacity;
  backface-visibility: hidden;
}

.tt-pillnav--hidden {
  opacity: 0;
  pointer-events: none;
  transform: translateX(-50%) translateY(12px);
}

.tt-pillnav-logo {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  text-decoration: none;
  transition: opacity 150ms ease;
}

.tt-pillnav-logo:hover {
  opacity: 0.85;
}

.ex-filter-pillnav button.tt-pillnav-logo {
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
}

.tt-pillnav-logo-img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.tt-pillnav-items {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  padding: 4px;
  background: rgba(255, 255, 255, 0.04);
  border-radius: var(--radius-lg);
  overflow-x: auto;
  scrollbar-width: none;
}

.tt-pillnav-items::-webkit-scrollbar { display: none; }

.tt-pillnav-item {
  display: flex;
  align-items: center;
  height: 44px;
  padding: 0 16px;
  border-radius: var(--radius-md);
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.6);
  border: 1px solid transparent;
  text-decoration: none;
  white-space: nowrap;
  transition: background 150ms ease, color 150ms ease, border-color 150ms ease;
  cursor: pointer;
  background: transparent;
}

/* Scoped to real pointer devices — without this, a tap on touch screens
   leaves the item visually "stuck" hovered until the user taps elsewhere. */
@media (hover: hover) and (pointer: fine) {
  .tt-pillnav-item:hover {
    background: rgba(255, 255, 255, 0.08);
    color: rgba(255, 255, 255, 0.9);
  }
}

.tt-pillnav-item--active {
  color: var(--color-surface);
  border-color: rgba(255, 255, 255, 0.80);
  background: rgba(255, 255, 255, 0.06);
  font-weight: 600;
}

.tt-pillnav-item:focus-visible {
  outline: 2px solid rgba(255, 255, 255, 0.7);
  outline-offset: 2px;
}

/* Mobile: keep the floating bottom capsule, just sized down — a full-width
   top bar competed with the site header and felt out of place (2026-06-21). */
@media (max-width: 767px) {
  .tt-pillnav {
    bottom: 16px;
    max-width: calc(100vw - 24px);
    padding: 6px;
    gap: 4px;
  }
  .tt-pillnav--hidden {
    transform: translateX(-50%) translateY(12px);
    opacity: 0;
  }
  .tt-pillnav-logo {
    width: 44px;
    height: 44px;
    border-radius: var(--radius-md);
  }
  .tt-pillnav-item {
    height: 38px;
    padding: 0 12px;
    font-size: 12px;
  }
}

/* Respect prefers-reduced-motion */
@media (prefers-reduced-motion: reduce) {
  .tt-pillnav {
    transition: opacity 0ms;
  }
}

