  text-align: center;
  text-wrap: balance;
}
.stp-page .sp-hero > p:not(.sp-hero-integrity) {
  max-width: 58ch;
  margin-inline: auto;
  text-align: center;
  text-wrap: balance;
}
.sp-hero-actions {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 12px;
  margin-top: 28px;
}
.sp-hero-actions button { min-height: 48px; justify-content: center; }
.sp-hero-actions .tt-button-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.stp-page .sp-hero > .sp-hero-integrity {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: fit-content;
  max-width: calc(100% - 40px);
  margin: 17px auto 0;
  font-family: var(--font-ui);
  font-size: 13px;
  line-height: 1.45;
  text-align: left;
  color: var(--color-muted);
}
.stp-page .sp-hero > .sp-hero-integrity svg { flex: 0 0 auto; color: var(--color-text-strong); }
.sp-overview-inner,
.sp-faq-section {
  max-width: 1120px;
  margin: 0 auto;
  padding-inline: var(--layout-gutter, 48px);
}
.sp-section-intro h2,
.sp-overview-heading h2 {
  margin: var(--space-xs) 0;
  font-family: var(--font-brand);
  font-size: var(--tt-size-section-h);
  font-weight: 600;
  line-height: 1.02;
  letter-spacing: -0.04em;
  color: var(--color-text-strong);
}
.sp-section-intro > p,
.sp-overview-heading > p {
  max-width: 660px;
  margin: 0;
  font-family: var(--font-ui);
  font-size: var(--tt-size-section-intro);
  line-height: 1.45;
  color: var(--color-muted);
}
.stp-page .sp-overview { padding: var(--space-2xl) 0; border-top: 1px solid var(--color-border); }
.sp-overview-heading { max-width: 790px; margin: 0 auto var(--space-xl); text-align: center; }
.sp-overview-heading h2,
.sp-overview-heading > p { text-wrap: balance; }
.sp-overview-heading > p { max-width: 62ch; margin-inline: auto; }
.sp-rating-proof { display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(360px, .95fr); gap: var(--space-xl); align-items: center; margin-top: var(--space-xl); padding: var(--space-xl); background: var(--color-surface-soft); border-radius: var(--tt-surface-radius-panel); scroll-margin-top: var(--space-lg); }
.sp-rating-proof-copy h3 { max-width: 18ch; margin: var(--space-sm) 0; font: 600 var(--tt-size-section-h)/1.1 var(--font-brand); letter-spacing: -.035em; text-wrap: balance; }
.sp-rating-proof-copy p { max-width: 55ch; margin: 0; font: 400 var(--tt-size-card-body)/1.6 var(--font-ui); color: var(--color-text); }
.sp-rating-example { padding: var(--space-lg); background: var(--color-surface); border: 1px solid var(--color-border); border-radius: var(--tt-surface-radius-info); }
.sp-rating-example-head { display: flex; align-items: flex-end; justify-content: space-between; gap: var(--space-md); padding-bottom: var(--space-md); border-bottom: 1px solid var(--color-border); }
.sp-rating-example-head > div:first-child { display: grid; gap: var(--space-2xs); }
.sp-rating-example-head > div:first-child span { font: 700 var(--tt-size-kicker)/1.2 var(--font-ui); letter-spacing: .07em; }
.sp-rating-example-head > div:first-child strong { font: 600 var(--tt-size-body-large)/1.2 var(--font-brand); }
.sp-rating-total { display: flex; align-items: baseline; gap: 4px; color: hsl(var(--primary)); white-space: nowrap; }
.sp-rating-total svg { align-self: center; fill: currentColor; }
.sp-rating-total strong { font: 650 28px/1 var(--font-brand); letter-spacing: -.04em; }
.sp-rating-total span { font: 600 12px/1 var(--font-ui); }
.sp-rating-example-note { margin: var(--space-md) 0; font: 400 var(--tt-size-card-body)/1.55 var(--font-ui); color: var(--color-text); }
.sp-rating-example-link { display: flex; align-items: center; justify-content: space-between; gap: var(--space-sm); padding-top: var(--space-md); border-top: 1px solid var(--color-border); color: hsl(var(--primary)); font: 600 var(--tt-size-card-body)/1.4 var(--font-ui); text-decoration: none; }
.sp-rating-example-link:hover { text-decoration: underline; text-underline-offset: 4px; }
.sp-plan-grid { display: grid; grid-template-columns: minmax(0, 1.08fr) minmax(0, .92fr); gap: var(--space-lg); }
.sp-plan-card {
  display: grid;
  grid-row: span 5;
  grid-template-rows: subgrid;
  row-gap: 0;
  min-height: 0;
  padding: var(--space-xl);
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--tt-surface-radius-info);
