.sp-plan-args li { display: flex; gap: 10px; align-items: flex-start; font: 14px/1.4 var(--font-ui); color: var(--color-text); }
.sp-plan-args svg { flex: 0 0 auto; margin-top: 2px; color: var(--color-text-strong); }
.sp-plan-args li:nth-child(2) svg { color: hsl(var(--primary)); }
.sp-plan-cta { width: 100%; justify-content: center; min-height: 48px; }
.sp-partnership-note {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
  margin-top: 20px;
  padding: var(--space-lg) 0;
  background: transparent;
  border-bottom: 1px solid var(--color-border);
}
.sp-partnership-note > div { min-width: 0; }
.sp-partnership-note strong { display: block; font: 600 16px/1.25 var(--font-ui); color: var(--color-text-strong); }
.sp-partnership-note p { margin: 6px 0 0; font: 14px/1.5 var(--font-ui); color: var(--color-muted); }
.sp-partnership-note .tt-button-secondary { flex: 0 0 auto; min-height: 44px; }
.sp-upgrade-note {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
  padding: 22px 24px;
  border-radius: 12px;
  background: var(--color-text-strong);
  color: var(--color-bg);
}
.sp-upgrade-note > div { min-width: 0; }
.sp-upgrade-note span { display: block; margin-bottom: 7px; font: 700 10px/1.2 var(--font-ui); letter-spacing: .08em; text-transform: uppercase; opacity: .66; }
.sp-upgrade-note strong { display: block; font: 600 19px/1.25 var(--font-brand); }
.sp-upgrade-note p { margin: 7px 0 0; font: 14px/1.5 var(--font-ui); opacity: .74; }
.sp-upgrade-cta {
  flex: 0 0 auto;
  min-height: 44px;
  padding: 0 18px;
  border: 1px solid var(--color-bg);
  border-radius: var(--radius-pill);
  background: var(--color-bg);
  font: 600 13px/1 var(--font-ui);
  color: var(--color-text-strong);
  cursor: pointer;
}
.sp-upgrade-cta:hover { background: transparent; color: var(--color-bg); }
.sp-editorial-rule {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  max-width: 790px;
  margin: var(--space-lg) auto 0;
  padding: 0;
  background: transparent;
}
.sp-editorial-rule svg { flex: 0 0 auto; }
.sp-editorial-rule p { margin: 0; font: 14px/1.55 var(--font-ui); color: var(--color-muted); }
.sp-editorial-rule strong,
.sp-editorial-rule a { color: var(--color-text-strong); }
.sp-editorial-rule a { font-weight: 600; text-underline-offset: 3px; }
.sp-guarantees {
  display: grid;
  grid-template-columns: minmax(160px, .65fr) minmax(0, 2fr);
  gap: var(--space-lg);
  align-items: start;
  margin-top: var(--space-lg);
  padding: var(--space-lg);
  border: 1px solid var(--color-border);
  border-radius: var(--tt-surface-radius-info);
  background: var(--color-surface);
}
.sp-guarantees > strong { font: 600 var(--tt-size-card-title)/1.4 var(--font-ui); color: var(--color-text-strong); }
.sp-guarantees ul { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-sm) var(--space-lg); margin: 0; padding: 0; list-style: none; }
.sp-guarantees li { display: flex; align-items: flex-start; gap: var(--space-xs); font: 400 var(--tt-size-card-body)/1.5 var(--font-ui); color: var(--color-muted); }
.sp-guarantees li svg { flex: 0 0 auto; margin-top: 2px; color: var(--color-text-strong); }

.stp-page .sp-shell { max-width: 900px; padding-top: var(--space-2xl); scroll-margin-top: var(--space-lg); }
.sp-input-wrap { position: relative; }
.sp-input-wrap > svg { position: absolute; z-index: 1; left: 14px; top: 50%; transform: translateY(-50%); color: var(--color-muted-light); pointer-events: none; }
.sp-input-wrap .tt-form-input { padding-left: 42px; }
.sp-verified { display: flex; align-items: center; justify-content: center; gap: 8px; }
.sp-payment-summary { display: flex; justify-content: space-between; gap: 24px; padding: 24px; background: var(--color-surface-soft); border: 1px solid var(--color-border); border-radius: 12px; }
.sp-payment-summary > div { display: grid; gap: 5px; }
.sp-payment-summary span { font: 700 10px/1 var(--font-ui); letter-spacing: .09em; color: var(--color-muted); }
.sp-payment-summary strong { font: 600 22px/1.2 var(--font-brand); color: var(--color-text-strong); }
.sp-payment-summary small { font: 13px/1.4 var(--font-ui); color: var(--color-muted); overflow-wrap: anywhere; }
.sp-payment-promise { display: flex; gap: 12px; padding: 18px; border-left: 2px solid var(--color-text-strong); background: var(--color-surface-soft); }
.sp-payment-promise svg { flex: 0 0 auto; }
.sp-payment-promise p { margin: 0; font: 14px/1.55 var(--font-ui); color: var(--color-muted); }
.sp-payment-cta { display: flex; width: 100%; justify-content: center; gap: 9px; min-height: 50px; }
.sp-payment-meta { margin: -10px 0 0; text-align: center; font: 12px/1.4 var(--font-ui); color: var(--color-muted-light); }
.sp-payment-urgency { display: flex; align-items: center; justify-content: center; gap: var(--space-xs); margin: 0; font: 600 13px/1.4 var(--font-ui); color: var(--color-text-strong); }
.sp-payment-urgency svg { flex: 0 0 auto; }

.sp-faq-section { padding-top: var(--space-2xl); padding-bottom: var(--space-3xl); }
.sp-faq-section .sp-section-intro { max-width: 760px; }
.sp-faq-list { margin-top: var(--space-xl); border-top: 1px solid var(--color-border); }
.sp-faq-list details { border-bottom: 1px solid var(--color-border); }
.sp-faq-list summary { position: relative; padding: 23px 42px 23px 0; font: 600 16px/1.4 var(--font-ui); color: var(--color-text-strong); cursor: pointer; list-style: none; }
.sp-faq-list summary::-webkit-details-marker { display: none; }
.sp-faq-list summary::after { content: "+"; position: absolute; right: 4px; top: 20px; font: 300 24px/1 var(--font-ui); color: var(--color-muted); }
.sp-faq-list details[open] summary::after { content: "−"; }
.sp-faq-list details p { max-width: 760px; margin: -5px 0 24px; font: 15px/1.6 var(--font-ui); color: var(--color-muted); }

@media (max-width: 820px) {
  .sp-plan-card { min-height: auto; }
}
@media (max-width: 640px) {
  .stp-page .sp-hero { padding-bottom: var(--space-2xl); }
  .sp-hero-actions { align-items: stretch; flex-direction: column; }
  .sp-hero-actions button { width: 100%; }
  .sp-overview-inner,
  .sp-faq-section { padding-left: 20px; padding-right: 20px; }
  .sp-plan-grid { grid-template-columns: 1fr; }
  .sp-plan-card { padding: var(--space-lg); }
  .sp-plan-card { grid-row: auto; grid-template-rows: auto; }
  .sp-partnership-note { align-items: stretch; flex-direction: column; gap: 18px; }
  .sp-partnership-note .tt-button-secondary { width: 100%; justify-content: center; }
  .sp-upgrade-note { align-items: stretch; flex-direction: column; gap: 18px; }
  .sp-upgrade-cta { width: 100%; }
  .sp-plan-desc { min-height: 0; }
  .sp-payment-summary { align-items: flex-start; }
}

/* Submission: current white canvas and an offer led by the editorial deliverable. */
.sp-assurance { width: 100%; max-width: 1120px; margin-inline: auto; padding: 0 var(--layout-gutter, 48px) var(--space-2xl); }
:root:not(.dark) .stp-page {
  --color-bg: #FFFFFF;
  --color-surface-soft: #F5F5F7;
  --color-text: #1D1D1F;
  --color-text-strong: #1D1D1F;
  --color-muted: #1D1D1F;
  --color-muted-light: #1D1D1F;
}
.tt-title-muted { color: #86868B; }
.stp-page .sp-hero { padding-bottom: 0; }
.sp-pitch {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr);
  align-items: center;
  gap: var(--space-2xl);
  padding-block: var(--space-2xl);
  text-align: left;
}
.stp-page .sp-pitch .tt-page-hero-eyebrow { margin: 0 0 var(--space-md); text-align: left; }
.stp-page .sp-pitch h1 { margin: 0; text-align: left; line-height: 1.04; }
.sp-pitch-lead { margin: var(--space-lg) 0 0; font: 400 var(--tt-size-section-intro)/1.55 var(--font-ui); color: var(--color-muted); text-wrap: pretty; }
.sp-pitch .sp-hero-actions { align-items: flex-start; flex-direction: column; gap: var(--space-md); margin-top: var(--space-lg); }
.sp-pitch .tt-button-primary, .sp-closing .tt-button-primary { gap: var(--space-sm); min-height: 48px; }
.stp-page :is(.tt-button-primary, .tt-button-secondary, .sp-button-secondary) { border-radius: var(--radius-pill); }
.sp-text-link { display: inline-flex; align-items: center; gap: var(--space-xs); font: 600 var(--tt-size-card-body)/1.5 var(--font-ui); color: var(--color-text); text-decoration: none; }
.sp-text-link:hover { text-decoration: underline; text-underline-offset: 4px; }
.stp-page :is(.sp-text-link, .sp-example-link, .sp-editorial-rule a) { color: hsl(var(--primary)); }
.sp-pitch-reassurance { display: flex; align-items: flex-start; gap: var(--space-xs); margin: var(--space-md) 0 0; font: 400 12px/1.6 var(--font-ui); color: var(--color-muted); }
.sp-pitch-reassurance svg { flex-shrink: 0; margin-top: 2px; }
.sp-listing-preview { padding: var(--space-xl); background: var(--color-surface-soft); border-radius: var(--tt-surface-radius-panel); }
.sp-preview-caption { display: flex; align-items: center; gap: var(--space-xs); font: 600 var(--tt-size-kicker)/1.5 var(--font-ui); letter-spacing: .05em; color: var(--color-muted); }
.sp-preview-caption svg { flex-shrink: 0; }
.sp-preview-identity { display: flex; align-items: center; gap: var(--space-sm); margin-block: var(--space-lg); }
.sp-preview-icon { display: grid; place-items: center; width: 48px; height: 48px; flex-shrink: 0; border-radius: var(--tt-radius-sm); background: var(--color-surface); }
.sp-preview-identity strong { display: block; font: 600 var(--tt-size-body-large)/1.2 var(--font-brand); }
.sp-preview-identity div > span { display: block; margin-top: var(--space-2xs); font: 400 12px/1.5 var(--font-ui); color: var(--color-muted); }
.sp-listing-preview dl { margin: 0; }
.sp-listing-preview dl > div { padding-block: var(--space-md); border-top: 1px solid var(--color-border); }
.sp-listing-preview dt { font: 600 var(--tt-size-card-body)/1.5 var(--font-ui); }
.sp-listing-preview dd { margin: var(--space-2xs) 0 0; font: 400 var(--tt-size-card-body)/1.5 var(--font-ui); color: var(--color-muted); }
.sp-preview-footer { display: flex; align-items: center; gap: var(--space-xs); margin-top: var(--space-sm); font: 500 12px/1.5 var(--font-ui); }
.sp-preview-footer svg { flex-shrink: 0; }
.sp-proof-line { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 0; padding: var(--space-lg); background: var(--color-surface-soft); border-radius: var(--tt-surface-radius-panel); text-align: left; }
.sp-proof-line > div { display: grid; align-content: start; gap: var(--space-xs); padding-inline: var(--space-lg); }
.sp-proof-line > div + div { border-left: 1px solid var(--color-border); }
.sp-proof-line strong { color: var(--color-text); font: 600 var(--tt-size-metric)/1.2 var(--font-brand); }
.sp-proof-line span { color: var(--color-muted); font: 400 12px/1.5 var(--font-ui); }
.sp-example-description { margin: 0; color: var(--color-muted); font: 400 var(--tt-size-card-body)/1.6 var(--font-ui); }
.sp-example-topics { display: grid; gap: var(--space-sm); margin: var(--space-lg) 0; padding: var(--space-lg) 0; border-block: 1px solid var(--color-border); list-style: none; font: 500 var(--tt-size-card-body)/1.5 var(--font-ui); }
.sp-example-link { display: flex; align-items: center; justify-content: space-between; gap: var(--space-sm); font: 600 var(--tt-size-card-body)/1.5 var(--font-ui); color: var(--color-text); text-decoration: none; }
.sp-example-link:hover { text-decoration: underline; text-underline-offset: 4px; }
.stp-page .sp-overview { border-top: 0; padding-block: var(--space-3xl); }
.sp-plan-card--highlight { background: var(--color-surface-soft); }
.sp-plan-tag { letter-spacing: .04em; }
.sp-plan-name { font-family: var(--font-brand); }
.sp-plan-cta { white-space: normal; height: auto; padding-block: var(--space-sm); text-align: center; }
.sp-delivery, .sp-closing, .sp-contact-line { max-width: 1120px; margin-inline: auto; padding-inline: var(--layout-gutter, 48px); }
.sp-delivery { padding-block: var(--space-lg) var(--space-2xl); }
.sp-delivery-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-md); margin: var(--space-lg) 0 0; padding: 0; list-style: none; }
.sp-delivery-grid li { padding: var(--space-lg); background: var(--color-surface-soft); border-radius: var(--tt-surface-radius-info); }
.sp-delivery-grid li > span { display: grid; place-items: center; width: 36px; height: 36px; border-radius: var(--radius-circle); background: var(--color-text); font: 600 12px/1 var(--font-ui); color: var(--color-surface); }
.sp-delivery-grid h3 { margin: var(--space-md) 0 var(--space-xs); font: 600 var(--tt-size-body)/1.3 var(--font-ui); }
.sp-delivery-grid p { margin: 0; font: 400 var(--tt-size-card-body)/1.6 var(--font-ui); color: var(--color-muted); }
.sp-selected-plan { display: flex; align-items: center; justify-content: space-between; gap: var(--space-md); margin-bottom: var(--space-lg); font: 400 var(--tt-size-card-body)/1.5 var(--font-ui); color: var(--color-muted); }
.sp-selected-plan strong { display: block; color: var(--color-text); font-weight: 600; }
.sp-closing { display: flex; align-items: center; justify-content: space-between; gap: var(--space-xl); padding-block: var(--space-xl); }
.sp-closing h2 { max-width: 24ch; margin: 0; font: 600 var(--tt-size-section-h)/1.15 var(--font-brand); letter-spacing: -.035em; text-wrap: balance; }
.sp-closing p { max-width: 48ch; margin: var(--space-sm) 0 0; font: 400 var(--tt-size-card-body)/1.6 var(--font-ui); color: var(--color-muted); }
.stp-page + .tt-footer { --tt-footer-margin-top: 0px; }
.sp-contact-line { margin-block: var(--space-md) 0; padding-bottom: var(--space-2xl); font: 400 var(--tt-size-card-body)/1.6 var(--font-ui); color: var(--color-muted); }
.sp-faq-section { padding-bottom: var(--space-xl); }
#submit-plans-title { scroll-margin-top: var(--space-lg); }
@media (max-width: 1000px) {
  .sp-pitch { gap: var(--space-lg); }
  .sp-listing-preview { padding: var(--space-lg); }

  .sp-closing { align-items: flex-start; flex-direction: column; }
}
@media (max-width: 760px) {
  .sp-pitch { grid-template-columns: minmax(0, 1fr); padding-block: var(--space-xl); }
  .sp-listing-preview { margin-top: var(--space-md); }
  .sp-rating-proof { grid-template-columns: minmax(0, 1fr); }
  .sp-delivery-grid { grid-template-columns: minmax(0, 1fr); gap: var(--space-lg); }
  .sp-guarantees { grid-template-columns: minmax(0, 1fr); }
}
@media (max-width: 640px) {
  .sp-delivery, .sp-closing, .sp-contact-line { padding-inline: var(--space-lg); }
  .stp-page .sp-hero { padding-bottom: 0; }
  .sp-pitch .sp-hero-actions { align-items: stretch; }
  .sp-pitch .sp-hero-actions .sp-text-link { justify-content: center; }
  .sp-pitch .tt-button-primary, .sp-closing .tt-button-primary { white-space: normal; height: auto; padding-block: var(--space-sm); }
  .sp-closing .tt-button-primary { width: 100%; justify-content: center; }
  .sp-pitch h1 { text-wrap: pretty; }
  .sp-proof-line { grid-template-columns: minmax(0, 1fr); padding: var(--space-xs) var(--space-lg); }
  .sp-proof-line > div { grid-template-columns: 100px minmax(0, 1fr); align-items: center; padding: var(--space-md) 0; gap: var(--space-md); }
  .sp-proof-line > div + div { border-left: 0; border-top: 1px solid var(--color-border); }
  .sp-rating-proof { padding: var(--space-lg); }
  .sp-rating-example { padding: var(--space-md); }
  .stp-page .sp-overview { padding-block: var(--space-2xl); }
  .sp-guarantees ul { grid-template-columns: minmax(0, 1fr); }
}

/* ─────────────────────────────────────────────────────────────────────────
   Methodology — contrast table + inline stats + CARS framework
   ─────────────────────────────────────────────────────────────────────────
   Page reuses .ab-* (long-form article) classes from About. These me-*
   classes cover the 3 page-specific patterns: 2-col contrast table,
   inline monospace stats line, and the CARS framework list.
   ───────────────────────────────────────────────────────────────────────── */

/* ── Contrast table (Annuaire vs Diagnostic) — open editorial pattern ── */
.me-contrast {
  margin: 24px 0 0;
  border-top: 2px solid var(--color-border-strong);
}
.me-contrast-head {
  display: grid;
  grid-template-columns: 1fr 1fr;
  padding: 16px 0;
  border-bottom: 2px solid var(--color-border-strong);
}
.me-contrast-head-col {
  font-family: var(--font-ui);
  font-size: var(--tt-size-kicker);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-muted);
  padding-right: 16px;
}
.me-contrast-head-col--us {
  padding-left: 16px;
  padding-right: 0;
  color: var(--color-text-strong);
}
.me-contrast-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border-bottom: 1px solid var(--color-border-soft);
}
.me-contrast-row:last-child {
  border-bottom: 1px solid var(--color-border);
}
.me-contrast-them {
  padding: 18px 16px 18px 0;
  font-family: var(--font-ui);
  font-size: var(--tt-size-body);
  line-height: 1.5;
  letter-spacing: -0.01em;
  color: var(--color-muted);
  text-decoration: line-through;
  text-decoration-color: var(--color-border);
  text-decoration-thickness: 1px;
}
.me-contrast-us {
  padding: 18px 0 18px 16px;
  font-family: var(--font-ui);
  font-size: var(--tt-size-body);
  font-weight: 600;
  line-height: 1.5;
  letter-spacing: -0.015em;
  color: var(--color-text-strong);
}
@media (max-width: 560px) {
  .me-contrast-head,
  .me-contrast-row {
    grid-template-columns: 1fr;
  }
  .me-contrast-them,
  .me-contrast-us {
    padding: 14px 0;
  }
  .me-contrast-head-col--us {
    padding-left: 0;
    padding-top: 14px;
    border-top: 1px solid var(--color-border-soft);
  }
}

/* ── Inline stats — monospace, "·" separator, same as hero stamps ── */
.me-stats {
  margin: 28px 0 0;
  font-family: ui-monospace, "SF Mono", "Roboto Mono", Menlo, Consolas, monospace;
  font-size: var(--tt-size-kicker);
  font-weight: 500;
  letter-spacing: 0.02em;
  color: var(--color-muted);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}
.me-stats-sep {
  color: var(--color-border);
}

/* ── CARS framework — definition list with monospace letter anchors ── */
.me-cars {
  margin: 24px 0 0;
  display: flex;
  flex-direction: column;
  gap: 0;
  border-top: 1px solid var(--color-border);
}
.me-cars-row {
  display: grid;
  grid-template-columns: 56px 1fr;
  gap: 24px;
  padding: 20px 0;
  border-bottom: 1px solid var(--color-border-soft);
  align-items: baseline;
}
.me-cars-row:last-child {
  border-bottom: 1px solid var(--color-border);
}
.me-cars-letter {
  margin: 0;
  font-family: var(--font-brand);
  font-size: clamp(2rem, 3vw, 2.5rem);
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 1;
  color: var(--color-text-strong);
}
.me-cars-body {
  min-width: 0;
}
.me-cars-word {
  margin: 0 0 4px;
  font-family: var(--font-ui);
  font-size: var(--tt-size-body-large);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text-strong);
}
.me-cars-desc {
  margin: 0;
  font-family: var(--font-ui);
  font-size: var(--tt-size-body);
  line-height: 1.5;
  letter-spacing: -0.01em;
  color: var(--color-muted);
}
.me-cars-aside {
  margin: 24px 0 0;
  font-family: var(--font-ui);
  font-size: var(--tt-size-body);
  font-style: italic;
  line-height: 1.5;
  color: var(--color-muted);
}
.me-axis-detail-title {
  margin: 32px 0 4px;
  font-family: var(--font-ui);
  font-size: 15px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--color-text-strong);
}

/* ─────────────────────────────────────────────────────────────────────────
   CategoryPage — editorial alignment of hero + related categories
   ─────────────────────────────────────────────────────────────────────────
   Replaces the SaaS-cliché hero (giant icon top-right, hsl tinted bg) with
   the editorial pattern used on ComparePage and ComparesIndex. Replaces the
   related-categories card-grid (banned identical-card pattern) with an
   editorial list. Sidebar logic and tool-list rendering are untouched —
   only the surrounding chrome is brand-aligned.
   ───────────────────────────────────────────────────────────────────────── */
.cat-hero {
  background: var(--color-bg);
  padding: 80px 0 56px;
}
.cat-hero-inner,
.cat-body {
  max-width: var(--layout-content, 1280px);
  margin: 0 auto;
  padding: 0 var(--layout-gutter, 48px);
}
.cat-body {
  padding-top: 40px;
  padding-bottom: 40px;
}
.cat-index-card {
  display: block;
  min-width: 0;
  padding: 18px;
  border: 1px solid var(--color-border-soft);
  border-radius: var(--tt-surface-radius-info);
  background: var(--color-surface);
  color: inherit;
  text-decoration: none;
  transition: border-color 160ms ease-out, background 160ms ease-out;
}
.cat-index-card:hover {
  border-color: var(--color-border);
  background: color-mix(in srgb, var(--color-surface-soft) 42%, var(--color-surface));
}
.cat-index-card-layout {
  display: flex;
  align-items: flex-start;
  gap: 14px;
}
.cat-index-card-icon {
  display: inline-flex;
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius);
  background: var(--color-surface-soft);
  color: var(--color-text);
}
.cat-index-card-copy { min-width: 0; flex: 1 1 auto; }
.cat-index-card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}
.cat-index-card-title {
  margin: 0;
  font-family: var(--font-ui);
  font-size: var(--tt-size-card-title);
  font-weight: 650;
  letter-spacing: -0.018em;
  line-height: 1.3;
  color: var(--color-text);
}
.cat-index-card-arrow {
  width: 16px;
  height: 16px;
  flex: 0 0 16px;
  margin-top: 2px;
  color: var(--color-muted-light);
  transition: color 160ms ease-out, transform 160ms ease-out;
}
.cat-index-card:hover .cat-index-card-arrow {
  color: var(--color-text);
  transform: translateX(2px);
}
.cat-index-card-description {
  display: -webkit-box;
  margin: 4px 0 0;
  overflow: hidden;
  font-family: var(--font-ui);
  font-size: 13px;
  line-height: 1.45;
  color: var(--color-muted);
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}
.cat-index-card-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 5px 12px;
  margin-top: 12px;
  font-family: var(--font-ui);
  font-size: 12px;
  line-height: 1.35;
  color: var(--color-muted);
}
.cat-index-card-count {
  font-weight: 650;
  color: var(--color-text);
}
@media (max-width: 1023px) {
  .cat-hero-inner,
  .cat-body { padding-left: var(--layout-gutter-tablet, 32px); padding-right: var(--layout-gutter-tablet, 32px); }
}
@media (max-width: 639px) {
  .cat-hero-inner,
  .cat-body { padding-left: var(--layout-gutter-mobile, 20px); padding-right: var(--layout-gutter-mobile, 20px); }
}
.cat-hero-eyebrow {
  display: block;
  margin-top: 24px;
  font-family: var(--font-ui);
  font-size: var(--tt-size-kicker);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-muted);
}
.cat-hero-title {
  margin: 14px 0 0;
  font-family: var(--font-brand);
  font-size: clamp(2.75rem, 5vw, 4.5rem);
  font-weight: 700;
  letter-spacing: -0.05em;
  line-height: 0.98;
  color: var(--color-text-strong);
}
.cat-hero-desc {
  margin: 20px 0 0;
  max-width: 56ch;
  font-family: var(--font-ui);
  font-size: var(--tt-size-body-large);
  line-height: 1.5;
  letter-spacing: -0.015em;
  color: var(--color-text);
}
.cat-hero-stats {
  margin: 24px 0 0;
  font-family: ui-monospace, "SF Mono", "Roboto Mono", Menlo, Consolas, monospace;
  font-size: var(--tt-size-kicker);
  font-weight: 500;
  letter-spacing: 0.02em;
  color: var(--color-muted);
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
}
.cat-hero-stats-sep {
  color: var(--color-border);
}

/* ── Related categories — editorial list ─────────────────── */
.cat-article-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 24px;
}
@media (max-width: 860px) {
  .cat-article-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 640px) {
  .cat-article-grid {
    grid-template-columns: 1fr;
  }
}

.cat-related {
  margin-top: clamp(48px, 5vw, 80px);
  padding-top: clamp(40px, 4vw, 56px);
  border-top: 2px solid var(--color-border-strong);
}
.cat-related-eyebrow {
  display: block;
  margin-bottom: 16px;
  font-family: var(--font-ui);
  font-size: var(--tt-size-kicker);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-muted);
}
.cat-related-list {
  list-style: none;
  padding: 0;
  margin: 0;
}
.cat-related-item {
  border-bottom: 1px solid var(--color-border-soft);
}
.cat-related-row {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: baseline;
  gap: 24px;
  padding: 20px 16px;
  margin: 0 -16px;
  border-radius: var(--radius-xs);
  text-decoration: none;
  color: inherit;
  transition: background-color 0.25s cubic-bezier(0.25, 1, 0.5, 1);
}
.cat-related-row:hover {
  background-color: var(--color-surface-soft);
}
.cat-related-name {
  font-family: var(--font-ui);
  font-size: var(--tt-size-body-large);
  font-weight: 600;
  letter-spacing: -0.015em;
  color: var(--color-text-strong);
}
.cat-related-count {
  font-family: ui-monospace, "SF Mono", "Roboto Mono", Menlo, Consolas, monospace;
  font-size: var(--tt-size-kicker);
  font-weight: 500;
  letter-spacing: 0.02em;
  color: var(--color-muted);
  white-space: nowrap;
}

/* ─────────────────────────────────────────────────────────────────────────
   Reading progress bar — ComparePage long-form signal
   ─────────────────────────────────────────────────────────────────────────
   2px bar at top, scales from 0 to full as the user scrolls the document.
   CSS-only via animation-timeline: scroll(root) — gracefully invisible
   on browsers without support (Firefox limited as of 2026, others OK).
   ───────────────────────────────────────────────────────────────────────── */
.cp-reading-progress {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--color-text-strong);
  transform: scaleX(0);
  transform-origin: 0 50%;
  z-index: 100;
  pointer-events: none;
  animation: cpReadingProgress linear;
  animation-timeline: scroll(root);
}
@keyframes cpReadingProgress {
  to { transform: scaleX(1); }
}
@media (prefers-reduced-motion: reduce) {
  .cp-reading-progress { animation: none; transform: scaleX(0); }
}
@media print {
  .cp-reading-progress { display: none; }
}

/* ─────────────────────────────────────────────────────────────────────────
   Print stylesheet — ComparePage as a 2-page editorial brief
   ─────────────────────────────────────────────────────────────────────────
   Goal: someone reading a comparison can print it as a clean, dated brief
   to share with their team or keep offline. B&W friendly, typography-led,
   no decorative UI noise.
   ───────────────────────────────────────────────────────────────────────── */
@media print {
  /* Page setup — A4 with editorial margins */
  @page {
    size: A4;
    margin: 18mm 16mm 20mm 16mm;
  }

  /* Reset to print-friendly base */
  html, body {
    background: #FFFFFF !important;
    color: #000000 !important;
    font-size: 11pt;
    line-height: 1.45;
  }

  /* Hide all chrome and non-editorial UI — applies across all pages */
  nav.cp-breadcrumb,
  .cp-cta-band,
  .cp-tipping-cta,
  .cp-methodology-note,
  .cp-hero-verdict-jump,
  .cp-faq-nav,
  .td-sidebar-desktop,
  .td-sidebar-mobile,
  .gi-cta-band,
  .ga-tab-nav,
  .ga-cta-band,
  .skip-to-content,
  header[role="banner"],
  footer[role="contentinfo"],
  .tt-footer {
    display: none !important;
  }

  /* ToolDetailPage + GuideDetailPage shared print treatment */
  .td-container,
  .ga-container {
    max-width: 100% !important;
    padding: 0 !important;
  }
  .td-body-grid {
    display: block !important;
  }
  .td-section {
    page-break-inside: auto;
    margin-bottom: 6mm !important;
  }
  .td-title {
    font-size: 22pt !important;
    line-height: 1.1 !important;
    color: #000000 !important;
    page-break-after: avoid;
  }
  .td-eyebrow {
    font-size: 8pt !important;
    color: #555555 !important;
  }

  /* Hero — keep the title, drop the giant logos */
  .cp-hero {
    padding: 0 0 8mm !important;
    border-bottom: 1pt solid #000000 !important;
    background: none !important;
  }
  .cp-hero-meta {
    margin-bottom: 4mm !important;
  }
  .cp-hero-checked {
    font-size: 9pt !important;
    color: #555555 !important;
  }
  .cp-hero-title {
    font-size: 22pt !important;
    line-height: 1.1 !important;
    margin: 0 0 4mm !important;
    color: #000000 !important;
  }
  .cp-hero-title-logo {
    display: none !important;
  }
  .cp-hero-title-vs {
    color: #555555 !important;
  }
  .cp-hero-promise {
    font-size: 12pt !important;
    color: #000000 !important;
    max-width: 100% !important;
    margin: 0 0 3mm !important;
  }
  .cp-hero-intro {
    font-size: 10.5pt !important;
    color: #333333 !important;
    max-width: 100% !important;
  }

  /* Sections — flatten padding, tighten rhythm */
  .cp-section {
    padding: 6mm 0 !important;
    page-break-inside: auto;
  }
  .cp-matrix-header {
    margin-bottom: 4mm !important;
  }
  .cp-title {
    font-size: 16pt !important;
    line-height: 1.15 !important;
    color: #000000 !important;
    page-break-after: avoid;
  }
  .cp-eyebrow,
  .cp-sub-section-eyebrow {
    font-size: 8pt !important;
    color: #555555 !important;
    margin-bottom: 2mm !important;
  }
  .cp-matrix-intro {
    font-size: 10pt !important;
    color: #333333 !important;
    max-width: 100% !important;
  }

  /* Verdict statement — the editorial peak, keep on its page */
  .cp-verdict-statement {
    padding: 0 0 4mm !important;
    margin-bottom: 6mm !important;
    border-bottom: 0.5pt solid #999999 !important;
    page-break-inside: avoid;
  }
  .cp-verdict-statement p {
    font-size: 14pt !important;
    line-height: 1.3 !important;
    color: #000000 !important;
    max-width: 100% !important;
  }
  .cp-verdict-statement p::after {
    background: #000000 !important;
  }

  /* Decision list (Ma situation) — compact print pairs */
  .cp-decision-list {
    border-top: 1pt solid #000000 !important;
    max-width: 100% !important;
  }
  .cp-decision-item {
    padding: 3mm 0 !important;
    border-bottom: 0.5pt solid #BBBBBB !important;
    page-break-inside: avoid;
  }
  .cp-decision-condition {
    font-size: 10pt !important;
    color: #000000 !important;
  }
  .cp-decision-answer {
    font-size: 10pt !important;
    color: #000000 !important;
  }
  .cp-decision-answer::before {
    color: #555555 !important;
  }

  /* Tables — print-friendly: no hover, strong dividers */
  .cp-compare-table {
    page-break-inside: auto;
  }
  .cp-compare-header {
    border-bottom: 1pt solid #000000 !important;
    page-break-after: avoid;
  }
  .cp-compare-row {
    border-bottom: 0.5pt solid #BBBBBB !important;
    page-break-inside: avoid;
    background: none !important; /* kill hover wash */
  }
  .cp-compare-row-title {
    color: #000000 !important;
  }
  .cp-compare-row-verdict {
    color: #333333 !important;
  }
  .cp-compare-row-tool--win .cp-compare-row-tool-val {
    color: #000000 !important;
    font-weight: 700 !important;
  }

  /* Verdict logic — par défaut / bascule si — keep paired on same page */
  .cp-tipping-card {
    page-break-inside: avoid;
    gap: 8mm !important;
  }
  .cp-tipping-card-text {
    font-size: 10.5pt !important;
    color: #000000 !important;
  }

  /* Rules — keep each rule with its content */
  .cp-tipping-rule {
    page-break-inside: avoid;
  }
  .cp-tipping-rule p {
    color: #000000 !important;
  }

  /* FAQ — auto-open all accordion items for print */
  .cp-faq-item details,
  .cp-faq-item {
    page-break-inside: avoid;
  }
  .cp-faq-summary {
    color: #000000 !important;
  }
  .cp-faq-summary::after,
  details > summary::-webkit-details-marker {
    display: none !important;
  }
  details[class*="cp-faq"] > .cp-faq-answer,
  .cp-faq-item .cp-faq-answer {
    display: block !important;
    color: #000000 !important;
  }

  /* Links — show URLs after external anchors */
  a {
    color: #000000 !important;
    text-decoration: underline !important;
  }
  a[href^="http"]::after {
    content: " (" attr(href) ")";
    font-size: 8pt;
    color: #555555;
    word-wrap: break-word;
  }
  /* Don't expand internal route links */
  a[href^="/"]::after,
  .cp-breadcrumb a::after,
  .cp-methodology-link::after { content: ""; }

  /* Source / methodology footer for print — appended via ::after on .cp-hero */
  /* Page numbers and methodology attribution sit in the printed margin */
  @page {
    @bottom-center {
      content: "Vérifié par ToolTrim · page " counter(page) " / " counter(pages);
      font-size: 8pt;
      color: #555555;
    }
  }
}

/* ─────────────────────────────────────────────────────────────────────────
   Tool page — scroll-driven section reveal (signature motion)
   ─────────────────────────────────────────────────────────────────────────
   Each chapter fades + lifts as it enters the viewport. CSS-only via
   animation-timeline: view(); progressive enhancement behind @supports so
   browsers without it just show static content. Disabled for reduced motion.
   td-feature hover is the lone feedback micro-interaction.
   ───────────────────────────────────────────────────────────────────────── */
.td-feature { transition: border-color 140ms cubic-bezier(0.25, 1, 0.5, 1); }
.td-feature:hover { border-color: var(--color-text); }

/* Sticky card "see review" link — underline draw + arrow nudge */

@media (prefers-reduced-motion: no-preference) {
  @supports (animation-timeline: view()) {
    .td-subpage-content > .td-section {
      animation: tdSectionReveal both cubic-bezier(0.16, 1, 0.3, 1);
      animation-timeline: view();
      animation-range: entry 0% entry 55%;
    }
    @keyframes tdSectionReveal {
      from { opacity: 0; transform: translateY(20px); }
      to   { opacity: 1; transform: translateY(0); }
    }
  }
}

/* ─────────────────────────────────────────────────────────────────────────
   ToolGallery — image strip + lightbox on tool detail pages
   ───────────────────────────────────────────────────────────────────────── */

/* Main viewer */
.tg-viewer { width: 100%; }

.tg-main {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--color-border);
  background: var(--color-surface-soft);
}
.tg-main-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.tg-main-img[src*="/tool-media/maniana/"],
.tg-main-img[src*="/tool-media/pdf-agile/"],
.tg-main-img[src*="/tool-media/flexclip/"],
.tg-main-img[src*="/tool-media/piktochart/"],
.tg-main-img[src*="/tool-media/pixlr/"],
.tg-main-img[src*="/og-images/maniana-review"],
.tg-main-img[src*="/tool-media/faceready/"],
.tg-main-img[src*="/og-images/faceready-review"] {
  object-fit: contain;
  background: #F8F8F4;
}
.tg-main-video,
.tg-video-poster {
  display: block;
  width: 100%;
  height: 100%;
  border: 0;
}
.tg-main-img[src*="/tool-media/esign/"],
.tg-main-img[src*="/og-images/esign-review"] {
  object-fit: contain;
  background: #000;
}
.tg-video-poster {
  position: relative;
  padding: 0;
  overflow: hidden;
  background: var(--color-text);
  color: #fff;
  cursor: pointer;
}
.tg-video-poster > img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.82;
}
.tg-video-play {
  position: absolute;
  inset: 50% auto auto 50%;
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: color-mix(in srgb, #fff 92%, transparent);
  color: var(--color-text);
  transform: translate(-50%, -50%);
  box-shadow: 0 8px 24px rgb(0 0 0 / 18%);
}
.tg-video-play svg { width: 19px; height: 19px; transform: translateX(1px); }
.tg-video-caption {
  position: absolute;
  right: 16px;
  bottom: 14px;
  left: 16px;
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 16px;
  font-family: var(--font-ui);
  text-align: left;
  text-shadow: 0 1px 8px rgb(0 0 0 / 55%);
}
.tg-video-caption strong { font-size: 14px; font-weight: 650; }
.tg-video-caption small { font-size: 11px; white-space: nowrap; }

/* Inline nav arrows */
.tg-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 36px;
  height: 36px;
  border-radius: var(--radius-circle);
  background: oklch(0% 0 0 / 32%);
  border: none;
  cursor: pointer;
  transition: background 120ms ease-out;
}
.tg-nav:hover { background: oklch(0% 0 0 / 52%); }
.tg-nav-prev { left: 12px; }
.tg-nav-next { right: 12px; }
.tg-nav-prev::after { content: "‹"; color: #fff; font-size: 20px; }
.tg-nav-next::after { content: "›"; color: #fff; font-size: 20px; }

.tg-counter {
  position: absolute;
  bottom: 10px;
  right: 12px;
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 500;
  color: oklch(100% 0 0 / 75%);
  background: oklch(0% 0 0 / 32%);
  padding: 2px 8px;
  border-radius: var(--radius-pill);
  letter-spacing: 0.04em;
  pointer-events: none;
}

/* Thumbnails row */
.tg-thumbs {
  display: flex;
  gap: 8px;
  margin-top: 8px;
}
.tg-dot-thumb {
  position: relative;
  flex: 1;
  aspect-ratio: 16 / 9;
  border-radius: var(--radius-sm);
  overflow: hidden;
  border: 2px solid transparent;
  background: var(--color-surface-soft);
  padding: 0;
  cursor: pointer;
  transition: border-color 120ms ease-out, opacity 120ms ease-out;
  opacity: 0.55;
  max-width: 100px;
}
.tg-dot-thumb--active {
  border-color: var(--color-text);
  opacity: 1;
}
.tg-dot-thumb:hover { opacity: 0.85; }
.tg-dot-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.tg-dot-play {
  position: absolute;
  inset: 50% auto auto 50%;
  width: 16px;
  height: 16px;
  color: #fff;
  filter: drop-shadow(0 1px 4px rgb(0 0 0 / 55%));
  transform: translate(-50%, -50%);
}

/* Hero media follows the reference's two-up editorial gallery. The gallery is
   intentionally not wrapped in another surface: each item owns its OG ratio
   and radius, while additional media advance by pairs. */
.tg-viewer--hero {
  position: relative;
}
.tg-hero-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}
.tg-hero-grid--single { grid-template-columns: minmax(0, 1fr); }
.tg-hero-cell {
  min-width: 0;
  aspect-ratio: 1200 / 630;
  overflow: hidden;
  border-radius: var(--radius-md);
}
.tg-hero-cell > .tg-main-img,
.tg-hero-cell > .tg-main-video,
.tg-hero-cell > .tg-video-poster { height: 100%; }
.tg-viewer--hero .tg-counter { bottom: 14px; }

@media (max-width: 640px) {
  .tg-nav { width: 28px; height: 28px; }
  .tg-hero-grid:not(.tg-hero-grid--single) {
    display: flex;
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    scrollbar-width: none;
  }
  .tg-hero-grid:not(.tg-hero-grid--single)::-webkit-scrollbar { display: none; }
  .tg-hero-grid:not(.tg-hero-grid--single) .tg-hero-cell {
    flex: 0 0 88%;
    scroll-snap-align: start;
  }
  .td-hero-media { margin-top: 14px; }
}

/* ─────────────────────────────────────────────────────────────────────────
   HomePageV2 — hidden experiment at /fr/v2 (noindex)
   Hybrid: audit-first hero + toolfolio-style catalogue
   ───────────────────────────────────────────────────────────────────────── */
.home-v2 {
  /* OpenAI-inspired spatial grid measured at a 1280px viewport:
     32px page gutters, 32px head-to-content, 24px grid gaps and
     120px between major editorial sections. */
  /* Same gutter as every other page and the footer (design review,
     8 Oct 2026): the home was the only page at 32px, 16px off the site. */
  --v2-grid-gutter: var(--layout-gutter, 48px);
  --v2-section-gap: 72px;
  /* OpenAI reference typography at 1280px:
     section 21.7/27.2, card 17.7/23.2, metadata 14/19.6. */
  --v2-type-section-title: clamp(20px, 1.695vw, 22px);
  --v2-type-card-title: clamp(17px, 1.383vw, 18px);
  --v2-type-description: 16px;
  --v2-type-meta: 14px;
}

.v2-container {
  max-width: var(--layout-content, 1280px);
  padding: 0 var(--v2-grid-gutter);
  margin: 0 auto;
}

/* Bottom padding kept small: the global footer already brings its own
   top margin, and the two stacked left ~200px of dead space under the
   last section. */
.v2-catalog {
  padding: var(--space-3xl) 0 var(--space-lg);
}

.v2-catalog-section + .v2-catalog-section {
  margin-top: var(--v2-section-gap);
}

/* ── Works with: segmented control + shelf ──
   The host picker is a visible iOS-style segmented control (grey track,
   active segment as a white pill) instead of a dropdown hidden in the
   title. On narrow screens the segments scroll sideways. */

/* Shelf: native horizontal scroll with snap. Card width leaves part of the
   next card visible so the row reads as scrollable without any dots. */
.v2-rail {
  position: relative;
}
.v2-rail-track {
  display: flex;
  gap: var(--v2-grid-gap);
  /* Carousels slide out to the screen edges, never clipped at the page
     margin (Michael, 9 Oct 2026); the first card still starts on the grid. */
  margin-inline: calc(-1 * var(--v2-grid-gutter, 0px));
  padding-inline: var(--v2-grid-gutter, 0px);
  scroll-padding-inline: var(--v2-grid-gutter, 0px);
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
}
.v2-rail-track::-webkit-scrollbar { display: none; }
.v2-rail-item {
  flex: 0 0 calc((100% - 3 * var(--v2-grid-gap)) / 4.3);
  min-width: 0;
  scroll-snap-align: start;
}
@media (max-width: 1023px) {
  .v2-rail-item { flex-basis: calc((100% - var(--v2-grid-gap)) / 2.3); }
}
@media (max-width: 639px) {
  .v2-rail-item { flex-basis: 78%; }
}

/* Prev/next buttons: centred on the card image, fade in on hover, hidden
   at the ends and on touch screens (where swiping is the gesture). */
.v2-rail-nav {
  position: absolute;
  z-index: 5; /* above .tce-primary-link (4), which covered it on phones */
  top: 30%;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border: 0;
  border-radius: 50%;
  background: var(--color-surface);
  box-shadow: 0 0 0 1px var(--color-border), 0 4px 14px rgb(0 0 0 / 0.08);
  color: var(--color-text-strong);
  cursor: pointer;
  opacity: 0;
  transform: translateY(-50%);
  transition: opacity 180ms ease-out;
}
.v2-rail-nav svg { width: 16px; height: 16px; }
.v2-rail-nav--prev { left: -14px; }
.v2-rail-nav--next { right: -14px; }
.v2-rail:hover .v2-rail-nav:not(:disabled),
.v2-rail-nav:focus-visible:not(:disabled) {
  opacity: 1;
}
.v2-rail-nav:disabled {
  pointer-events: none;
}
.v2-rail-nav:focus-visible {
  outline: 2px solid var(--color-text-strong);
  outline-offset: 2px;
}
@media (hover: none) {
  .v2-rail-nav { display: none; }
}

/* Search bar */

/* Section heads */
.v2-section-head {
