/* Tool grid */
/* ── V2 Featured carousel (2 rows × 4 cols) ── */

/* ── V2 New Additions — logo list 3×4 ── */

.tlp {
  display: flex;
  align-items: center;
  flex-wrap: nowrap;
  gap: 0;
  isolation: isolate;
  overflow: visible;
}

.tlp-item {
