  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.stack-profile-copy h1 {
  color: var(--color-text);
  font-size: clamp(2.35rem, 4vw, 3.75rem);
  font-weight: 820;
  letter-spacing: -0.055em;
  line-height: 0.98;
