  font-size: 0.78rem;
  font-weight: 690;
  min-height: 25px;
}
.stack-collection-switcher {
  align-items: center;
  display: flex;
  gap: 4px;
  margin-top: 5px;
}
.stack-collection-switcher button {
  align-items: center;
  background: transparent;
  border: 0;
  border-radius: 10px;
  color: var(--color-muted);
  display: inline-flex;
  font-family: var(--font-ui);
  font-size: 0.82rem;
  font-weight: 620;
  gap: 7px;
