  display: inline-flex;
  font-size: 0.7rem;
  height: 20px;
  justify-content: center;
  min-width: 20px;
  padding: 0 5px;
}
.stack-collection-switcher button:not(.is-active) span { background: var(--color-surface); color: var(--color-muted); }
.stack-library-tabs {
  background: var(--color-bg);
}
.stack-library-tabs-inner {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 0 auto;
  max-width: calc(var(--layout-content, 1280px) + var(--layout-gutter, 48px) + var(--layout-gutter, 48px));
