/* Page dédiée d'ajout — même modèle mental qu'une sélection d'épingles :
   contexte fixe, recherche immédiate, sélection multiple, sortie explicite. */
.stack-boards-page:not(.stack-boards-page--adding) > .stack-page-toolbar,
.stack-boards-page:not(.stack-boards-page--adding) > .stack-objective-hero,
.stack-boards-page--adding > .stack-tool-add-page > .stack-tool-add-hero {
  view-transition-name: stack-add-context;
}
::view-transition-old(root),
::view-transition-new(root) {
  animation: none;
}
::view-transition-group(stack-add-context) {
  animation-duration: 210ms;
  animation-timing-function: cubic-bezier(0.2, 0.8, 0.2, 1);
}
::view-transition-old(stack-add-context) {
  animation: stack-add-anchor-out 150ms ease-out both;
}
::view-transition-new(stack-add-context) {
  animation: stack-add-anchor-in 210ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
@keyframes stack-add-anchor-out {
  from { opacity: 1; }
  to { opacity: 0.58; }
}
@keyframes stack-add-anchor-in {
  from { opacity: 0.58; transform: scale(0.985); }
  to { opacity: 1; transform: scale(1); }
}
.stack-boards-page--adding > .stack-page-toolbar,
.stack-boards-page--adding > .stack-objective-hero,
.stack-boards-page--adding > .stack-board-grid,
.stack-boards-page--adding > .stack-objective-detail {
  display: none;
}
.stack-tool-add-page {
  --stack-destination-color: var(--color-surface-soft);
