}
.stack-tool-add-profile {
  grid-area: profile;
  justify-self: end;
}
.stack-tool-add-destination-card {
  align-items: flex-end;
  align-self: stretch;
  background: var(--stack-destination-color);
  border-radius: var(--radius-lg);
  display: flex;
  grid-area: destination;
  justify-content: space-between;
  justify-self: start;
  margin: 0;
  min-height: 72px;
  overflow: hidden;
  padding: 14px;
  position: relative;
  width: 260px;
}
.stack-tool-add-destination-card::after {
  background: color-mix(in srgb, var(--color-text) 8%, transparent);
  border-radius: var(--radius-pill);
  content: "";
  height: 96px;
  position: absolute;
  right: -34px;
  top: -46px;
  width: 96px;
}
.stack-tool-add-destination-copy {
  display: grid;
  gap: 4px;
  min-width: 0;
  position: relative;
  z-index: 1;
}
.stack-tool-add-destination-copy strong {
  color: var(--color-text);
  font: 850 1.08rem/1 var(--font-ui);
  letter-spacing: -0.035em;
}
.stack-tool-add-destination-copy small {
  color: color-mix(in srgb, var(--color-text) 66%, var(--color-muted));
  font: 740 0.66rem/1 var(--font-ui);
}
.stack-tool-add-destination-logos {
  align-items: center;
  display: flex;
  margin-left: 12px;
  position: relative;
  z-index: 1;
}
.stack-tool-add-destination-logos > span {
  align-items: center;
  background: rgba(255, 255, 255, 0.82);
  border: 2px solid rgba(255, 255, 255, 0.88);
  border-radius: var(--radius-pill);
