}
.stack-tool-add-destination-logos > span + span { margin-left: -9px; }
.stack-tool-add-back {
  align-items: center;
  appearance: none;
  background: var(--color-surface-soft);
  border: 0;
  border-radius: var(--radius-pill);
  color: var(--color-text);
