}
.stack-tool-add-done,
.stack-tool-add-footer button {
  align-items: center;
  appearance: none;
  background: var(--color-text);
  border: 0;
  border-radius: var(--radius-pill);
  color: var(--color-bg);
  cursor: pointer;
  display: inline-flex;
  font-family: var(--font-ui);
