}
.stack-tool-add-results-head {
  align-items: baseline;
  display: flex;
  justify-content: space-between;
}
.stack-tool-add-results-head h2 {
  color: var(--color-text);
  font-family: var(--font-ui);
  font-size: 1.08rem;
  font-weight: 850;
