/* Ma stack — cartes éditoriales colorées, proches de la référence validée. */
.stack-board-grid {
  gap: 22px;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-top: 0;
}
.stack-board-card {
  grid-template-rows: minmax(0, 1fr) 60px;
  height: 320px;
  padding: 8px;
  position: relative;
}
.stack-board-card-open {
  appearance: none;
  background: transparent;
  border: 0;
  cursor: pointer;
  inset: 0;
  padding: 0;
  position: absolute;
  z-index: 1;
}
.stack-board-card-open:focus-visible {
  border-radius: var(--radius);
  box-shadow: inset 0 0 0 3px color-mix(in srgb, var(--color-text) 42%, transparent);
  outline: none;
}
.stack-board-editorial-cover {
  align-items: stretch;
  appearance: none;
  border: 0;
  cursor: default;
  display: flex;
  flex-direction: column;
  gap: 18px;
  height: 100%;
  justify-content: space-between;
  padding: 22px;
  text-align: left;
  width: 100%;
}
.stack-board-editorial-cover:focus-visible {
  outline: 3px solid rgba(18, 18, 16, 0.5);
  outline-offset: -5px;
}
.stack-board-editorial-cover .stack-board-preview-copy {
  display: grid;
  gap: 14px;
  min-height: 0;
}
.stack-board-editorial-heading {
  align-items: baseline;
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
}
.stack-board-editorial-title {
  color: var(--color-text);
  font-family: var(--font-ui);
  font-size: clamp(1.65rem, 2.2vw, 2.4rem);
  font-weight: 900;
  letter-spacing: -0.055em;
  line-height: 0.94;
  max-width: 100%;
  min-width: 0;
  overflow-wrap: normal;
  word-break: normal;
}
.stack-board-editorial-heading .stack-board-title-count {
  color: color-mix(in srgb, var(--color-text) 76%, var(--color-muted));
  font-size: 0.72rem;
  font-weight: 850;
}
.stack-board-editorial-description {
  color: color-mix(in srgb, var(--color-text) 86%, var(--color-muted));
  display: block;
  font-family: var(--font-ui);
  font-size: clamp(0.82rem, 0.9vw, 0.96rem);
  font-weight: 610;
  line-height: 1.28;
  max-width: 28ch;
}
.stack-board-editorial-logos {
  align-items: center;
  display: flex;
  flex-wrap: nowrap;
  gap: 0;
  margin-top: auto;
  min-height: 54px;
  overflow: visible;
  position: relative;
}
.stack-board-editorial-logo,
.stack-board-editorial-empty {
  align-items: center;
  background: rgba(255, 255, 255, 0.78);
  border: 2px solid rgba(255, 255, 255, 0.82);
  border-radius: var(--radius-pill);
  display: inline-flex;
  flex: 0 0 auto;
  height: 54px;
  justify-content: center;
  overflow: hidden;
  width: 54px;
}
.stack-board-editorial-logo + .stack-board-editorial-logo {
  margin-left: -7px;
}
.stack-board-editorial-logo-mark {
  background: transparent !important;
  border-radius: var(--radius-pill) !important;
  box-shadow: none !important;
  padding: 0 !important;
}
.stack-board-editorial-empty {
  color: var(--color-muted);
}
.stack-board-editorial-logos .stack-board-overflow {
  aspect-ratio: 1;
  border-radius: var(--radius-circle);
  box-sizing: border-box;
  height: 50px;
  list-style: none;
  margin: 0;
  max-width: 50px;
  min-width: 50px;
  padding: 0;
  width: 50px;
}
.stack-board-editorial-logos .stack-board-overflow::-webkit-details-marker {
  display: none;
}
.stack-board-logo-more {
  flex: 0 0 50px;
  margin-left: -4px;
  position: relative;
  z-index: 8;
}
.stack-board-logo-more[open] {
  z-index: 18;
}
.stack-board-logo-popover {
  align-items: center;
  background: rgba(255, 255, 255, 0.97);
  border: 1px solid rgba(18, 18, 16, 0.12);
  border-radius: var(--radius-md);
  bottom: calc(100% + 8px);
  box-shadow: 0 14px 34px rgba(18, 18, 16, 0.16);
  display: grid;
  gap: 7px;
  grid-template-columns: repeat(3, 44px);
  max-height: 148px;
  overflow-y: auto;
  padding: 9px;
  position: absolute;
  right: 0;
}
.stack-board-logo-popover-item {
  align-items: center;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  display: inline-flex;
  height: 44px;
  justify-content: center;
  overflow: hidden;
  width: 44px;
}
.stack-board-footer {
  min-height: 60px;
  padding: 6px 8px 0;
  position: relative;
  z-index: 2;
}
.stack-board-explore {
  align-items: center;
  font-size: 0.84rem;
  gap: 7px;
}
.stack-board-explore::after {
  border-radius: var(--radius);
  font-size: 1.2rem;
  height: 38px;
  margin-left: 2px;
  width: 38px;
}
.stack-board-add-link {
  font-size: 0.8rem;
  gap: 6px;
  min-height: 40px;
  padding: 0 12px;
  width: auto;
}
.stack-board-card--unassigned .stack-board-preview {
  background: #f1ede4;
}
.stack-board-card--unassigned .stack-board-footer > span {
  color: color-mix(in srgb, var(--color-text) 62%, var(--color-muted));
}
.stack-board-grid--organizing .stack-board-card:not(.stack-board-card--create):not(.stack-board-card--unassigned) {
  cursor: grab;
}
.stack-board-grid--organizing .stack-board-card:not(.stack-board-card--create):not(.stack-board-card--unassigned):active {
  cursor: grabbing;
}
.stack-board-grid--organizing .stack-board-card:not(.stack-board-card--create):not(.stack-board-card--unassigned) > .stack-board-preview,
.stack-board-grid--organizing .stack-board-card:not(.stack-board-card--create):not(.stack-board-card--unassigned) > .stack-board-footer {
  animation: stack-board-organize-wiggle 420ms ease-in-out infinite alternate;
  transform-origin: 50% 55%;
}
.stack-board-grid--organizing .stack-board-card:nth-child(even) > .stack-board-preview,
.stack-board-grid--organizing .stack-board-card:nth-child(even) > .stack-board-footer {
  animation-delay: -210ms;
}
.stack-board-grid--organizing .stack-board-card-open,
.stack-board-grid--organizing .stack-board-footer button,
.stack-board-grid--organizing .stack-board-logo-more {
  pointer-events: none;
}
.stack-board-grid--organizing .stack-board-card.is-dragging > .stack-board-preview,
.stack-board-grid--organizing .stack-board-card.is-dragging > .stack-board-footer {
  animation-play-state: paused;
  opacity: 0.68;
}
.stack-board-grid--organizing .stack-board-card.is-drop-target {
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--color-text) 20%, transparent);
}
.stack-board-drag-handle,
.stack-board-delete,
.stack-board-rename {
  align-items: center;
  background: rgba(255, 255, 255, 0.94);
  border: 2px solid rgba(255, 255, 255, 0.92);
  border-radius: var(--radius-pill);
  color: var(--color-text);
  display: inline-flex;
  height: 38px;
  justify-content: center;
  position: absolute;
  top: 10px;
  width: 38px;
  z-index: 12;
}
.stack-board-drag-handle {
  pointer-events: none;
  right: 10px;
}
.stack-board-delete {
  appearance: none;
  background: var(--color-text);
  color: var(--color-bg);
  cursor: pointer;
  left: 10px;
  padding: 0;
  transition: background 140ms ease, transform 140ms ease;
}
.stack-board-rename {
  appearance: none;
  cursor: pointer;
  left: 54px;
  padding: 0;
}
.stack-board-delete:hover,
.stack-board-delete:focus-visible {
  background: #9a2f2f;
  outline: none;
  transform: scale(1.07);
}
.stack-board-rename:hover,
.stack-board-rename:focus-visible {
  background: var(--color-text);
  color: var(--color-bg);
  outline: none;
  transform: scale(1.07);
}
.stack-board-order-actions {
  bottom: 10px;
  display: flex;
  gap: 4px;
  position: absolute;
  right: 10px;
  z-index: 12;
}
.stack-board-order-actions button {
  align-items: center;
  appearance: none;
  background: rgb(255 255 255 / 0.94);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  color: var(--color-text);
  cursor: pointer;
  display: inline-flex;
  height: 34px;
  justify-content: center;
  padding: 0;
  width: 34px;
}
.stack-board-order-actions button:disabled { cursor: default; opacity: 0.35; }
.stack-board-rename-form {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: 10px;
  box-shadow: 0 12px 30px rgb(34 34 34 / 0.14);
  display: grid;
  gap: 10px;
  left: 12px;
  padding: 14px;
  position: absolute;
  right: 12px;
  top: 58px;
  z-index: 20;
}
.stack-board-rename-form label {
  color: var(--color-muted);
  font-family: var(--font-ui);
  font-size: 0.7rem;
  font-weight: 700;
}
.stack-board-rename-form input {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  color: var(--color-text);
  font-family: var(--font-ui);
  font-size: 0.88rem;
  min-height: 40px;
  padding: 0 11px;
}
.stack-board-rename-form > div { display: flex; gap: 8px; justify-content: flex-end; }
.stack-board-rename-form button {
  background: transparent;
  border: 0;
  border-radius: 8px;
  color: var(--color-text);
  cursor: pointer;
  font-family: var(--font-ui);
  font-size: 0.74rem;
  font-weight: 700;
  min-height: 34px;
  padding: 0 10px;
}
.stack-board-rename-form button[type="submit"] { background: var(--color-text); color: var(--color-bg); }
.stack-board-delete-confirm {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: 10px;
  box-shadow: 0 12px 30px rgb(34 34 34 / 0.14);
  display: grid;
  gap: 8px;
  left: 12px;
  padding: 14px;
  position: absolute;
  right: 12px;
  top: 58px;
  z-index: 21;
}
.stack-board-delete-confirm strong,
.stack-board-delete-confirm p { font-family: var(--font-ui); margin: 0; }
.stack-board-delete-confirm strong { color: var(--color-text); font-size: 0.88rem; }
.stack-board-delete-confirm p { color: var(--color-muted); font-size: 0.74rem; line-height: 1.45; }
.stack-board-delete-confirm > div { display: flex; gap: 8px; justify-content: flex-end; }
.stack-board-delete-confirm button {
  background: transparent;
  border: 0;
  border-radius: 8px;
  color: var(--color-text);
  cursor: pointer;
  font-family: var(--font-ui);
  font-size: 0.74rem;
  font-weight: 700;
  min-height: 34px;
  padding: 0 10px;
}
.stack-board-delete-confirm button.is-danger { background: #8f302e; color: #fff; }
@keyframes stack-board-organize-wiggle {
  from { transform: rotate(-0.28deg); }
  to { transform: rotate(0.28deg); }
}
.stack-board-card--create .stack-board-create-preview {
  appearance: none;
  border: 1px solid rgba(34, 34, 34, 0.08);
  cursor: pointer;
  padding: 0;
  width: 100%;
}
.stack-board-create-form {
  align-content: center;
  background: #e5e4de;
  border: 1px solid rgba(34, 34, 34, 0.1);
  border-radius: var(--radius-lg);
  display: grid;
  gap: 12px;
  height: 100%;
  min-height: 0;
  padding: 24px;
}
.stack-board-create-form label {
  color: var(--color-text);
  font-family: var(--font-ui);
  font-size: 0.78rem;
  font-weight: 820;
}
.stack-board-create-form input {
  appearance: none;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  color: var(--color-text);
  font-family: var(--font-ui);
  font-size: 1rem;
  font-weight: 720;
  min-height: 48px;
  outline: none;
  padding: 0 13px;
  width: 100%;
}
.stack-board-create-form input:focus {
  border-color: var(--color-border-strong);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--color-text) 12%, transparent);
}
.stack-board-create-form > div {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}
.stack-board-create-form button {
  appearance: none;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  color: var(--color-text);
  cursor: pointer;
  font-family: var(--font-ui);
  font-size: 0.74rem;
  font-weight: 800;
  min-height: 40px;
  padding: 0 14px;
}
.stack-board-create-form button[type="submit"] {
  background: var(--color-text);
  color: var(--color-bg);
}
.stack-board-create-form button:disabled {
  cursor: default;
  opacity: 0.45;
}
@media (prefers-reduced-motion: reduce) {
  .stack-board-grid--organizing .stack-board-card > .stack-board-preview,
  .stack-board-grid--organizing .stack-board-card > .stack-board-footer {
    animation: none;
  }
}

@media (max-width: 1160px) {
  .stack-board-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .stack-board-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 560px) {
  .stack-board-management-head {
    align-items: stretch;
    flex-direction: column;
    gap: 16px;
  }
  .stack-board-management-head > button {
    align-self: flex-start;
  }
  .stack-board-grid {
    grid-template-columns: 1fr;
  }
  .stack-board-card {
    height: 310px;
  }
  .stack-board-editorial-cover {
    padding: 20px;
  }
  .stack-board-editorial-title {
    font-size: clamp(1.8rem, 8vw, 2.2rem);
  }
}

/* ═══════════════════════════════════════════════════════════════════════════
   ComparePage — canonical article layout
   Keep page structure here; the earlier cp-* block only owns shared elements.
═══════════════════════════════════════════════════════════════════════════ */
.cp-page-light {
  background: var(--color-bg);
}

.cp-hero {
  padding: var(--space-xl) 0 0;
  background: var(--color-bg);
}
.cp-hero-inner {
  max-width: var(--layout-content, 1280px);
}
.cp-hero-meta {
  margin-bottom: var(--space-xl);
}
.cp-hero-layout {
  display: block;
}
.cp-hero-duel {
  min-width: 0;
}
.cp-hero-title {
  flex-wrap: nowrap;
  max-width: none;
  margin: 0;
  font-size: clamp(40px, 3.6vw, 52px);
  line-height: 0.98;
  letter-spacing: -0.055em;
}
.cp-hero-title-tool {
  gap: var(--space-sm);
}
.cp-hero-title-logo {
  width: 40px;
  height: 40px;
}
.cp-article-dek {
  max-width: 62ch;
  margin: var(--space-lg) 0 0;
  font-family: var(--font-ui);
