.cp-product-shell {
  display: grid;
  grid-template-columns: minmax(0, 1fr) var(--layout-tool-sidebar, 360px);
  gap: var(--space-2xl);
  align-items: start;
  max-width: var(--layout-content, 1280px);
  margin: 0 auto;
  padding: 0 var(--layout-gutter, 48px);
}
.cp-product-main {
  min-width: 0;
}
.cp-product-main .cp-section {
  padding: var(--space-3xl) 0;
  border: 0;
  background: transparent;
}
.cp-product-main .cp-container {
  display: block;
  padding: 0;
}
.cp-product-main .cp-container > .cp-matrix-header {
  position: static;
  height: auto;
  margin: 0 0 var(--space-xl);
}
.cp-product-main .cp-matrix-header .cp-eyebrow {
  margin-bottom: var(--space-sm);
}
.cp-product-main .cp-title {
  max-width: none;
