/* ─────────────────────────────────────────────────────────────────────────
   Detail pages — canonical editorial typography
   Tool, stack and comparison pages now share the same hierarchy as their
   catalogue indexes: one restrained page title, one section-title level,
   then compact subheads and metadata. Keep this block last so legacy detail
   variants cannot silently reintroduce a different scale or font family.
   ───────────────────────────────────────────────────────────────────────── */
.td-hero-h1,
.sd-hero-h1,
.cp-hero-title {
  font-family: var(--font-ui);
  font-size: var(--tt-size-page-title);
  font-weight: 500;
  line-height: 1;
  letter-spacing: -0.045em;
}

.td-hero-desc,
.sd-hero-desc,
.cp-article-dek {
  font-family: var(--font-ui);
  font-size: var(--tt-size-body-large);
  font-weight: 400;
  line-height: 1.45;
  letter-spacing: -0.02em;
}

.td-hero-context,
.td-editorial-intro .td-analysis-paragraph,
.sd-tools-subtitle,
.sd-decision-copy,
.cp-fundamental-copy {
  font-family: var(--font-ui);
  font-size: var(--tt-size-body);
  font-weight: 400;
  line-height: 1.55;
  letter-spacing: -0.01em;
}

.td-title,
.td-editorial-intro-title,
.td-overview-title,
.sd-section-title,
.sd-decision-title,
.cp-title {
  font-family: var(--font-ui);
  font-size: var(--tt-size-section-h);
  font-weight: 620;
  line-height: 1.08;
  letter-spacing: -0.035em;
}

/* Tool pages use a calmer editorial hierarchy than stack and comparison
   pages: section headings guide the scan without competing with the tool. */
.td-title,
.td-editorial-intro-title,
.td-overview-title {
  font-family: var(--font-brand);
  font-weight: 600;
  line-height: 1.15;
}

.td-analysis-lead {
  font-weight: 400;
}

/* The tool breadcrumb belongs to the product UI, not to the publication-like
   monospace treatment used by the other editorial page families. */
.td-page-breadcrumb .cp-breadcrumb a {
  font-family: "Inter Variable", Arial, sans-serif;
}

.td-editorial-fact-link {
  color: hsl(var(--primary));
  text-decoration: underline;
  text-decoration-color: var(--color-border-strong);
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  transition: color 160ms ease, text-decoration-color 160ms ease;
}

.td-editorial-fact-link:hover {
  color: var(--color-text-strong);
  text-decoration-color: currentColor;
}

/* Tool detail surfaces share one rectangular radius. Pills, circular controls
   and brand marks keep their own geometry. */
.td-tool-page .td-hero-card,
.td-tool-page .td-overview-group,
.td-tool-page .td-decision-verdict,
.td-tool-page .td-review-rationale,
.td-tool-page .td-review-rationale-v2,
.td-tool-page .td-score-axis-card,
.td-tool-page .td-compare-card,
.td-tool-page .td-pricing-plans,
.td-tool-page .td-profit-card,
.td-tool-page .td-tile,
.td-tool-page .tg-hero-cell,
.td-tool-page .td-tutorials,
.td-tool-page .td-tutorial-card,
