  .cp-guide-matrix thead th { font-size: 15px; font-weight: 650; padding-top: 16px; padding-bottom: 16px; background: var(--color-surface-soft); }
  .cp-guide-matrix thead th:first-child { width: 26%; border-radius: 12px 0 0 12px; }
  .cp-guide-matrix thead th:last-child { border-radius: 0 12px 12px 0; }
  .cp-guide-matrix tbody tr { border-bottom: 1px solid var(--color-border); }
  .cp-guide-matrix tbody th { font-size: 15px; font-weight: 600; line-height: 1.4; }
  .cp-guide-matrix td { font-size: 15px; line-height: 1.6; }
  .cp-guide-matrix .cp-guide-disclosure summary { justify-content: flex-start; font-size: 12px; margin-top: 4px; }
  .cp-guide-matrix .cp-guide-disclosure p { font-size: 13px; }
  .cp-guide-matrix .cp-guide-disclosure a { text-decoration: underline; }
  .cp-guide-mobile-label { display: none; }
  .cp-guide-segmented { display: inline-flex; gap: 4px; padding: 4px; background: var(--color-surface-soft); border-radius: 999px; margin: 0 0 24px; }
  .cp-guide-segmented button { min-width: 110px; min-height: 44px; padding: 10px 20px; border-radius: 999px; font-size: 14px; font-weight: 550; }
  .cp-guide-segmented button[aria-pressed="true"] { background: var(--color-text); color: var(--color-bg); }
  .cp-guide-price-cards { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; }
  .cp-guide-price-cards article { padding: 24px 0; border-top: 1px solid var(--color-border); }
  .cp-guide-price-cards h3 { margin-bottom: 8px; font-size: 20px; }
  .cp-guide-plan-name { margin: 0; font-size: 14px; }
  .cp-guide-price-cards .cp-guide-price-value { margin: 20px 0 4px; font-family: var(--font-brand); font-size: 52px; line-height: 1.1; font-weight: 600; letter-spacing: -.04em; }
  .cp-guide-price-value span { display: inline-block; margin-left: 8px; font-family: var(--font-ui); font-size: 14px; font-weight: 400; letter-spacing: 0; }
