  .cp-media-controls { display: flex; align-items: center; gap: 8px; }
  .cp-media-controls button { display: grid; place-items: center; width: 36px; height: 36px; border: 1px solid var(--color-border); border-radius: 50%; background: var(--color-surface); color: var(--color-text); }
  .cp-media-controls button:hover { background: var(--color-border); }
