  .cp-media-fallback > svg { padding: 12px; width: 48px; height: 48px; border: 1px solid var(--color-border); border-radius: 14px; }
  .cp-media-connector { width: clamp(8px, 2vw, 30px); flex-shrink: 1; border-top: 1px dashed var(--color-border); }
  .cp-guide-scenarios { align-items: stretch; }
  .cp-guide-scenario { border: 1px solid var(--color-border); }
  .cp-guide-editorial-verdict { padding: 24px 0 24px 24px; border-left: 3px solid var(--color-text); font-size: 20px; }
  .cp-criteria-selector { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 24px; }
  .cp-criteria-selector button { display: inline-flex; align-items: center; gap: 8px; padding: 12px 16px; min-height: 44px; text-align: left; border: 1px solid var(--color-border); border-radius: 16px; font-size: 13px; line-height: 1.35; background: var(--color-surface); color: var(--color-text); transition: background 180ms, color 180ms; }
  .cp-criteria-selector button svg { flex-shrink: 0; }
  .cp-criteria-selector button[aria-pressed="true"] { background: var(--color-text); color: var(--color-bg, #fff); border-color: var(--color-text); }
  .cp-section-icon { display: block; margin-bottom: 20px; }
  .cp-guide-switching .cp-decision-diagram { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding-bottom: 28px; border-bottom: 1px solid var(--color-border); }
  .cp-decision-diagram > span { display: flex; flex-direction: column; align-items: center; gap: 12px; font-size: 13px; }
  .cp-decision-diagram .cp-diagram-link { flex: 1; text-align: center; font-size: 11px; }
