  @keyframes cp-media-in { from { opacity: .3; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }
  @media (max-width: 600px) { .cp-media-stage { min-height: 220px; aspect-ratio: 16 / 9; border-radius: 22px 22px 0 0; } .cp-guide-editorial-verdict { font-size: 17px; padding-left: 16px; } .cp-media-controls button { width: 44px; height: 44px; } }
  @media (prefers-reduced-motion: reduce) { .cp-guide *, .cp-guide *::after { animation: none !important; transition: none !important; scroll-behavior: auto !important; } }
