@layer components {
  /* Shared stack guide: visible roles and editorial, independent of catalogue size. */
  .sg-page { max-width: calc(var(--layout-content, 1280px) + 2 * var(--layout-gutter, 48px)); margin: 0 auto; padding: 40px var(--layout-gutter, 48px) 100px; color: var(--color-text); }
  .sg-hero { padding: 24px 0 44px; }
