  .sg-hero h1 { max-width: 900px; font: 600 clamp(36px, 4.5vw, 64px)/1.04 var(--font-brand); letter-spacing: -.045em; margin: 0; }
  .sg-lead { max-width: 740px; font-size: clamp(18px, 2vw, 23px); line-height: 1.5; margin: 22px 0; }
  .sg-hero-tools { display: flex; gap: 12px; flex-wrap: wrap; margin: 28px 0; }
