  .sg-tool-list { border: 1px solid var(--color-border); border-radius: 20px; overflow: hidden; }
  .sg-tool-row { display: grid; grid-template-columns: minmax(200px, .8fr) minmax(0, 2fr) 32px; gap: 28px; align-items: start; padding: 26px; background: var(--color-surface); scroll-margin-top: 90px; }
  .sg-tool-row + .sg-tool-row { border-top: 1px solid var(--color-border); }
