  .sg-tool-link { padding: 8px; margin-top: 3px; }
  .sg-tool-identity a:hover, .sg-tool-link:hover { text-decoration: underline; }
  .sg-editorial { max-width: 850px; font-size: 20px; line-height: 1.7; }
  .sg-editorial p { margin: 0; }
  .sg-fit-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; margin-top: 32px; padding: 28px; border-radius: 16px; background: var(--color-surface-soft); }
