  .sg-budget-summary p, .sg-risk-intro { max-width: 740px; font-size: 17px; line-height: 1.65; margin: 0; }
  .sg-page a:focus-visible { outline: 2px solid currentColor; outline-offset: 5px; }
  @media (max-width: 700px) {
