.sg-check p { margin: 0; font-size: 15px; line-height: 1.6; color: var(--color-text); }

.sg-related {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr));
  gap: 16px;
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}
.sg-related-card {
