  font: 600 13px/1.2 var(--font-ui);
  color: var(--color-text-strong);
  text-decoration: none;
}
.ga-tools-open:hover { background: var(--color-text-strong); color: var(--color-surface); box-shadow: none; }
.ga-tools a:focus-visible { outline: 2px solid var(--color-text-strong); outline-offset: 2px; border-radius: 10px; }

/* ── Guide: keep reading ─────────────────────────────────────────────── */
.ga-next { margin-top: 56px; }
.ga-next-head { display: flex; align-items: baseline; justify-content: space-between; gap: 16px; margin-bottom: 16px; }
.ga-next-head h2 { margin: 0; font: 600 24px/1.2 var(--font-brand); letter-spacing: -0.02em; }
.ga-next-all { display: inline-flex; align-items: center; gap: 2px; font-size: 14px; font-weight: 600; color: var(--color-text-strong); text-decoration: none; }
.ga-next-all svg { width: 16px; height: 16px; }
.ga-next-list { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; margin: 0; padding: 0; list-style: none; }
.ga-next-card { display: flex; height: 100%; flex-direction: column; gap: 12px; color: inherit; text-decoration: none; }
.ga-next-media { display: block; aspect-ratio: 16 / 10; overflow: hidden; border-radius: 16px; background: var(--color-surface-soft); }
.ga-next-media img { width: 100%; height: 100%; object-fit: cover; transition: transform 400ms cubic-bezier(0.2, 0.8, 0.2, 1); }
.ga-next-card:hover .ga-next-media img { transform: scale(1.04); }
.ga-next-copy { display: flex; flex-direction: column; gap: 4px; }
.ga-next-meta { font: 600 11px/1.3 var(--font-ui); letter-spacing: 0.05em; text-transform: uppercase; color: var(--color-muted); }
.ga-next-title {
  display: -webkit-box;
  overflow: hidden;
  font: 600 16px/1.35 var(--font-ui);
  color: var(--color-text-strong);
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
}
.ga-next-card:focus-visible { outline: 2px solid var(--color-text-strong); outline-offset: 4px; border-radius: 16px; }
@media (max-width: 760px) {
  .ga-next-list { grid-template-columns: 1fr; }
  .ga-next-card { flex-direction: row; align-items: center; }
  .ga-next-media { width: 112px; flex: none; }
}
@media (prefers-reduced-motion: reduce) {
  .ga-next-media img { transition: none; }
  .ga-next-card:hover .ga-next-media img { transform: none; }
}
.ga-next-media[data-kind="tool"] { display: grid; place-items: center; }
.ga-next-tool {
  padding: 3px !important;
  border-radius: 18px !important;
  background: var(--color-surface) !important;
  box-shadow: 0 12px 26px rgb(0 0 0 / 0.08), inset 0 0 0 1px var(--color-border) !important;
  transition: transform 300ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.ga-next-card:hover .ga-next-tool { transform: scale(1.06) rotate(-3deg); }
@media (max-width: 760px) {
  .ga-next-tool { width: 48px !important; height: 48px !important; min-width: 48px !important; min-height: 48px !important; border-radius: 12px !important; }
}
@media (prefers-reduced-motion: reduce) { .ga-next-card:hover .ga-next-tool { transform: none; } }

/* ── Guide quick wins ────────────────────────────────────────────────── */
/* 1. Tables as a spec card */
.ga-content .overflow-x-auto { margin: 32px 0; border-radius: 20px; background: var(--color-surface-soft); }
.ga-content table { margin: 0; border: 0; border-radius: 0; background: transparent; }
.ga-content th { padding: 16px 20px 10px; border-bottom: 1px solid var(--color-border); background: transparent; }
.ga-content td { padding: 14px 20px; border-bottom: 1px solid var(--color-border); font-variant-numeric: tabular-nums; }
.ga-content td:first-child { font-weight: 600; color: var(--color-text-strong); }
.ga-content tr:last-child td { border-bottom: 0; }

/* 2. Generated cover: the article's tools on their brand tints */
.ga-cover {
  display: grid;
  gap: 6px;
  min-height: 360px;
  overflow: hidden;
  border-radius: var(--radius-lg, 24px);
}
.ga-cover[data-count="1"] { grid-template-columns: 1fr; }
.ga-cover[data-count="2"] { grid-template-columns: 1fr 1fr; }
.ga-cover[data-count="3"] { grid-template-columns: 1fr 1fr; grid-template-rows: 1fr 1fr; }
.ga-cover[data-count="3"] .ga-cover-tile:first-child { grid-row: span 2; }
.ga-cover[data-count="4"] { grid-template-columns: 1fr 1fr; grid-template-rows: 1fr 1fr; }
.ga-cover-tile {
  position: relative;
  display: grid;
  place-items: center;
  background: var(--color-surface-soft);
}
.ga-cover-icon {
  padding: 4px !important;
  border-radius: 26% !important;
  background: var(--color-surface) !important;
  box-shadow: 0 18px 40px rgb(0 0 0 / 0.1), inset 0 0 0 1px var(--color-border) !important;
  transform: rotate(-5deg);
  animation: ga-cover-in 700ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.ga-cover-tile:nth-child(even) .ga-cover-icon { transform: rotate(5deg); }
.ga-cover-name {
  position: absolute;
  left: 16px;
  bottom: 12px;
  font: 600 13px/1 var(--font-ui);
  color: var(--color-text-strong);
  opacity: 0.7;
}
@keyframes ga-cover-in { from { opacity: 0; transform: translateY(12px) rotate(0); } }
@media (max-width: 900px) {
  .ga-cover { min-height: 240px; }
  .ga-cover-icon { width: 72px !important; height: 72px !important; min-width: 72px !important; min-height: 72px !important; }
}

/* 3. Reading progress: CSS scroll timeline, hidden where unsupported */
.ga-progress { display: none; }
@supports (animation-timeline: scroll()) {
  .ga-progress {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    z-index: 60;
    display: block;
    height: 3px;
    background: var(--color-text-strong);
    transform-origin: 0 50%;
    animation: ga-progress linear both;
    /* The app shell scrolls .asv2-content, not the window: a named
       timeline on that scroller drives the bar. */
    animation-timeline: --tt-page-scroll;
  }
  @keyframes ga-progress { from { transform: scaleX(0); } to { transform: scaleX(1); } }
  .asv2-content { scroll-timeline: --tt-page-scroll block; }
}

/* 5. "Found this useful?" as a quiet line, not a boxed card */
.ga-share-row {
  margin-top: 40px;
  padding: 16px 0 0;
  border: 0;
  border-top: 1px solid var(--color-border);
  border-radius: 0;
  background: transparent;
}
.ga-share-row .ga-share-btn { border-radius: 999px; }

@media (prefers-reduced-motion: reduce) {
  .ga-cover-icon { animation: none; }
  .ga-progress { display: none; }
}

/* ── Guides: shared cover (article hero + index cards) ───────────────── */
.ga-cover-image img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gi-card-media.ga-cover-image img { border-radius: 0; }
.gi-card-media.ga-cover { min-height: 0; gap: 4px; border-radius: var(--tt-surface-radius-info); }
.ga-cover[data-size="small"] .ga-cover-icon {
  padding: 3px !important;
  border-radius: 24% !important;
  box-shadow: 0 10px 22px rgb(0 0 0 / 0.08), inset 0 0 0 1px var(--color-border) !important;
}
.gi-card:hover .ga-cover-icon { transform: rotate(0) scale(1.05); }
.gi-card:hover { opacity: 1; }
.gi-card:hover .gi-card-media.ga-cover-image img { transform: scale(1.03); }
.gi-card-media.ga-cover-image img { transition: transform 400ms cubic-bezier(0.2, 0.8, 0.2, 1); }
.ga-cover-icon { transition: transform 300ms cubic-bezier(0.2, 0.8, 0.2, 1); }

/* ── Guides index: reading scale ─────────────────────────────────────── */
.gi-card-eyebrow {
  margin-bottom: 6px;
  font: 600 11px/1.3 var(--font-ui);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-muted);
}
.gi-card-title { font-weight: 600; letter-spacing: -0.015em; color: var(--color-text-strong); }
.gi-card--featured .gi-card-title { font-weight: 600; letter-spacing: -0.03em; }
.gi-card--compact .gi-card-title { font-weight: 600; }
.gi-card-meta { gap: 10px; margin-top: 10px; font-size: 13px; }
.gi-card-grid { row-gap: clamp(40px, 4.5vw, 56px); margin-top: clamp(48px, 5vw, 64px); }
.gi-simple-controls .gi-filter-pills { flex: 1 1 auto; }
.gi-language-badge {
  padding: 2px 7px;
  border-radius: 6px;
  background: var(--color-surface-soft);
  font: 600 11px/1.4 var(--font-ui);
  color: var(--color-muted);
}
@media (prefers-reduced-motion: reduce) {
  .gi-card:hover .ga-cover-icon, .gi-card:hover .gi-card-media.ga-cover-image img { transform: none; }
}

/* Lead block balance: a Today-sized headline, not a poster, and both
   columns ending on the same line. */
@media (min-width: 901px) {
  .gi-lead-grid { grid-template-columns: minmax(0, 2fr) minmax(0, 1fr); align-items: stretch; }
  .gi-lead-grid > .gi-card--featured { display: flex; flex-direction: column; }
  .gi-lead-grid > .gi-card--featured .gi-card-media { flex: 1; min-height: 0; aspect-ratio: auto; }
  .gi-lead-side { grid-template-rows: 1fr 1fr; }
  .gi-lead-side .gi-card--compact .gi-card-media { aspect-ratio: 16 / 10; }
}
.gi-card--featured .gi-card-title {
  max-width: 30ch;
  font-size: clamp(1.5rem, 2.1vw, 1.95rem);
  line-height: 1.2;
}
.gi-card--featured .gi-card-body { padding-top: 16px; }

/* ── Tools catalogue: category shelves (App Store "Apps" tab) ────────── */
.tt-shelf { margin-top: 56px; }
.tt-shelf + .tt-shelf { margin-top: 44px; }
.tt-shelf-head { display: flex; align-items: baseline; justify-content: space-between; gap: 16px; margin-bottom: 10px; }
.tt-shelf-head h2 { display: flex; align-items: baseline; gap: 10px; margin: 0; font: 600 22px/1.2 var(--font-brand); letter-spacing: -0.02em; color: var(--color-text-strong); }
.tt-shelf-head h2 span { font: 500 14px/1 var(--font-ui); letter-spacing: 0; color: var(--color-muted); }
.tt-shelf-all { display: inline-flex; align-items: center; gap: 2px; font-size: 14px; font-weight: 600; color: var(--color-text-strong); text-decoration: none; }
.tt-shelf-all svg { width: 16px; height: 16px; }
.tt-shelf-list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 2px 24px;
  margin: 0 -12px;
  padding: 0;
  list-style: none;
}
.tt-shelf-row {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px 12px;
  border-radius: 16px;
  color: inherit;
  text-decoration: none;
  transition: background-color 160ms ease;
}
.tt-shelf-row:hover { background: var(--color-surface-soft); }
.tt-shelf-row:focus-visible { outline: 2px solid var(--color-text-strong); outline-offset: 2px; }
.tt-shelf-icon { padding: 2px !important; border-radius: 13px !important; background: var(--color-surface) !important; box-shadow: inset 0 0 0 1px var(--color-border); }
.tt-shelf-copy { display: flex; min-width: 0; flex-direction: column; gap: 2px; }
.tt-shelf-name { overflow: hidden; font: 600 15px/1.3 var(--font-ui); color: var(--color-text-strong); text-overflow: ellipsis; white-space: nowrap; }
.tt-shelf-meta { font-size: 13px; color: var(--color-muted); font-variant-numeric: tabular-nums; }
@media (max-width: 1100px) { .tt-shelf-list { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 640px) {
  /* Phone: a horizontal pager of three-row columns, like App Store charts. */
  .tt-shelf-list {
    grid-auto-flow: column;
    grid-template-columns: none;
    grid-template-rows: repeat(3, auto);
    grid-auto-columns: 82%;
    margin-inline: -20px;
    padding: 0 20px 4px;
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    scrollbar-width: none;
  }
  .tt-shelf-list::-webkit-scrollbar { display: none; }
  .tt-shelf-list > li { scroll-snap-align: start; }
}

/* ── Catalogue shelves, App Store list rhythm ────────────────────────── */
.tt-shelf-head { margin-bottom: 6px; padding-bottom: 0; }
.tt-shelf-head h2 { font-size: clamp(22px, 2.2vw, 28px); letter-spacing: -0.025em; }
.tt-shelf-list { gap: 0 28px; margin: 0; }
.tt-shelf-list > li { min-width: 0; }
.tt-shelf-row {
  position: relative;
  gap: 16px;
  padding: 16px 0;
  border-radius: 0;
}
.tt-shelf-row:hover { background: transparent; }
.tt-shelf-row:hover .tt-shelf-name { text-decoration: underline; text-underline-offset: 3px; }
/* inset divider, from the text column to the end, never after the last row
   of a column */
.tt-shelf-row::after {
  content: "";
  position: absolute;
  left: 80px;
  right: 0;
  bottom: 0;
  height: 1px;
  background: var(--color-border);
}
@media (min-width: 1101px) { .tt-shelf-list > li:nth-child(3n) .tt-shelf-row::after, .tt-shelf-list > li:nth-last-child(-n + 3) .tt-shelf-row::after { display: none; } }
.tt-shelf-list > li:nth-child(3n) .tt-shelf-row::after { display: none; }
.tt-shelf-icon {
  width: 64px !important;
  height: 64px !important;
  min-width: 64px !important;
  min-height: 64px !important;
  padding: 3px !important;
  border-radius: 16px !important;
  box-shadow: 0 6px 16px rgb(0 0 0 / 0.08), inset 0 0 0 1px var(--color-border) !important;
}
.tt-shelf-copy { flex: 1; }
.tt-shelf-name { font-size: 16px; font-weight: 500; white-space: normal; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.tt-shelf-meta { overflow: hidden; font-size: 14px; text-overflow: ellipsis; white-space: nowrap; }
.tt-shelf-action { display: flex; flex: none; flex-direction: column; align-items: center; gap: 4px; }
.tt-shelf-capsule {
  min-width: 72px;
  padding: 6px 14px;
  border-radius: 999px;
  background: var(--color-surface-soft);
  font: 600 13px/1.2 var(--font-ui);
  font-variant-numeric: tabular-nums;
  text-align: center;
  color: var(--color-text-strong);
  transition: background-color 160ms ease, color 160ms ease;
}
.tt-shelf-row:hover .tt-shelf-capsule { background: var(--color-text-strong); color: var(--color-surface); }
.tt-shelf-note { font-size: 10px; letter-spacing: 0.01em; color: var(--color-muted); }
@media (max-width: 1100px) {
  .tt-shelf-list > li .tt-shelf-row::after { display: block; }
  .tt-shelf-list > li:nth-child(2n) .tt-shelf-row::after { display: block; }
}
@media (max-width: 640px) {
  .tt-shelf-row::after { display: block !important; }
  .tt-shelf-list > li:nth-child(3n) .tt-shelf-row::after { display: none !important; }
  .tt-shelf-icon { width: 56px !important; height: 56px !important; min-width: 56px !important; min-height: 56px !important; }
  .tt-shelf-row::after { left: 72px; }
}

/* ── Catalogue editorial opening, App Store "pépites" cards ──────────── */
.tt-pepites { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px; }
.tt-pepite { display: flex; min-width: 0; flex-direction: column; color: inherit; text-decoration: none; }
.tt-pepite-media { aspect-ratio: 16 / 9; overflow: hidden; border-radius: 18px; }
.tt-pepite-media img { transition: transform 400ms cubic-bezier(0.2, 0.8, 0.2, 1); }
.tt-pepite:hover .tt-pepite-media img { transform: scale(1.03); }
.tt-pepite-eyebrow { margin-top: 16px; font: 600 12px/1.3 var(--font-ui); letter-spacing: 0.06em; text-transform: uppercase; color: var(--color-muted); }
.tt-pepite-title { margin-top: 4px; font: 600 clamp(20px, 1.8vw, 24px)/1.2 var(--font-brand); letter-spacing: -0.02em; color: var(--color-text-strong); }
.tt-pepite-sub {
  display: -webkit-box;
  margin-top: 4px;
  overflow: hidden;
  font-size: 16px;
  line-height: 1.4;
  color: var(--color-muted);
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}
.tt-pepite:focus-visible { outline: 2px solid var(--color-text-strong); outline-offset: 4px; border-radius: 18px; }
@media (max-width: 900px) { .tt-pepites { grid-template-columns: 1fr; gap: 32px; } }
@media (prefers-reduced-motion: reduce) { .tt-pepite:hover .tt-pepite-media img { transform: none; } }
/* Divider rules, per layout (supersede the ones above): the grid fills row by
   row, so the rows without a divider are the last row, not a column. */
.tt-shelf-list > li .tt-shelf-row::after { display: block !important; }
@media (min-width: 1101px) { .tt-shelf-list > li:nth-last-child(-n + 3) .tt-shelf-row::after { display: none !important; } }
@media (min-width: 641px) and (max-width: 1100px) { .tt-shelf-list > li:nth-last-child(-n + 2) .tt-shelf-row::after { display: none !important; } }
/* Phone pager fills column by column, three rows each. */
@media (max-width: 640px) { .tt-shelf-list > li:nth-child(3n) .tt-shelf-row::after { display: none !important; } }

/* ── Catalogue: one grid for the whole page ──────────────────────────
   Featured cards, category shelves and the full grid share the same three
   columns and the same gutter, so every column edge lines up down the page
   (the full grid used to jump to four columns at 1280px). */
.tt-catalog-page { --tt-grid-gap: 28px; }
.tt-catalog-page .tt-pepites,
.tt-catalog-page .tt-shelf-list,
.tt-catalog-page .tt-catalog-results .tc-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  column-gap: var(--tt-grid-gap);
}
.tt-catalog-page .tt-pepites { row-gap: var(--tt-grid-gap); }
@media (max-width: 1100px) {
  .tt-catalog-page .tt-pepites,
  .tt-catalog-page .tt-shelf-list,
  .tt-catalog-page .tt-catalog-results .tc-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 640px) {
  .tt-catalog-page .tt-pepites,
  .tt-catalog-page .tt-catalog-results .tc-grid { grid-template-columns: 1fr; }
  .tt-catalog-page .tt-shelf-list { grid-template-columns: none; }
}
/* Fixed-width action so the text column has the same width on every row. */
.tt-shelf-action { width: 72px; }
.tt-shelf-capsule { width: 100%; min-width: 0; padding-inline: 0; }
/* Shelves without CTA or hairlines: the row is the link, space separates. */
.tt-shelf-list > li .tt-shelf-row::after { display: none !important; }
.tt-shelf-row { padding: 12px 0; }


/* ── Catalogue: featured band + sponsored label ──────────────────────── */
.tt-spotlight { margin-top: 12px; }
.tt-section-title { margin: 0 0 16px; font: 600 clamp(22px, 2.2vw, 28px)/1.2 var(--font-brand); letter-spacing: -0.025em; color: var(--color-text-strong); }
/* Paid placements must read as ads: a plain, legible label, never hidden. */
.tt-sponsored {
  display: inline-block;
  margin-left: 8px;
  padding: 1px 6px;
  border-radius: 5px;
  box-shadow: inset 0 0 0 1px var(--color-border);
  font: 600 10px/1.5 var(--font-ui);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--color-muted);
  vertical-align: middle;
}
.tt-shelf-copy > .tt-sponsored { align-self: flex-start; margin-left: 0; }
/* The generic card image bleeds with -24px margins; the featured cards are
   not padded cards, so the image sits flush in its own column. */
.tt-pepite .tt-pepite-media { width: 100%; margin: 0 !important; }
/* Three featured cards never leave an orphan: three columns down to 760px. */
@media (min-width: 761px) and (max-width: 1100px) {
  .tt-catalog-page .tt-spotlight .tt-pepites { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 760px) {
  .tt-catalog-page .tt-spotlight .tt-pepites { grid-template-columns: 1fr; }
}

/* ── Catalogue command bar: one row at every width ───────────────────────────
   /tools, category pages, /stacks and /comparatifs. Pills scroll on the left,
   a single "Filters" (or "Sort") button stays on the right; sort lives in its
   panel. The shared ≤900px rule wrapped the tail onto a second line, which
   doubled the sticky bar over the cards. */
.tt-catalog-page [data-toolbar] {
  flex-wrap: nowrap;
  align-items: center;
  gap: 12px;
}
.tt-catalog-page [data-toolbar] .tt-pillrow {
  flex: 1 1 auto;
  order: 0;
  mask-image: linear-gradient(90deg, #000 calc(100% - 40px), transparent);
}
.tt-catalog-page [data-toolbar] .tt-catalog-toolbar-tail {
  flex: 0 0 auto;
}
.tt-catalog-page [data-toolbar] .tt-pill--more {
  position: relative;
  gap: 8px;
  padding-inline: 16px;
  border-color: var(--color-border);
  background: var(--color-surface);
}
.tt-catalog-page [data-toolbar] .tt-pill--more:hover:not(:disabled) {
  border-color: var(--color-border-strong);
  background: var(--color-surface);
}
.tt-catalog-page [data-toolbar] .tt-pill--more.tt-pill--active {
  border-color: var(--color-text);
}
@media (max-width: 900px) {
  .tt-catalog-page [data-toolbar] { min-height: 60px; }
}
@media (max-width: 640px) {
  /* The page scrolls as a whole here and .asv2-topbar sticks at the top:
     a catalogue bar stuck at 0 slid underneath it and vanished. */
  .tt-catalog-page .tt-sticky-toolbar,
  .tt-catalog-page .tt-sticky-toolbar--stuck { top: var(--asv2-chrome-h, 56px); transition: top 220ms cubic-bezier(0.2, 0.8, 0.2, 1); z-index: 19; }
  .tt-catalog-page [data-toolbar] { gap: 8px; }
  .tt-catalog-page [data-toolbar] .tt-pill {
    height: 36px;
    padding-inline: 14px;
    font-size: 14px;
  }
  /* Icon only: the badge carries the state, the aria-label the meaning. */
  .tt-catalog-page [data-toolbar] .tt-pill--more {
    width: 36px;
    padding: 0;
    justify-content: center;
  }
  .tt-catalog-page [data-toolbar] .tt-pill--more .tt-pill-label { display: none; }
  .tt-catalog-page [data-toolbar] .tt-pill--more.tt-pill--active .tt-pill-count {
    position: absolute;
    top: -5px;
    right: -5px;
    min-width: 18px;
    height: 18px;
    padding: 0 5px;
    font-size: 11px;
  }
}

/* ── /tools results: contextual header, active filters, quiet controls ──── */
.tt-catalog-results--after-editorial { border-top: 0; }
.tt-catalog-page .tt-catalog-results-header { margin-bottom: 28px; }
.tt-active-filters {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 16px;
}
.tt-active-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  padding: 0 10px 0 14px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  background: var(--color-surface);
  color: var(--color-text);
  font: 540 14px/1 var(--font-ui);
  cursor: pointer;
  transition: border-color 140ms ease-out;
}
.tt-active-chip svg { color: var(--color-muted); }
.tt-active-chip:hover { border-color: var(--color-text); }
.tt-active-chip:hover svg { color: var(--color-text); }
.tt-active-chip:focus-visible,
.tt-active-clear:focus-visible { outline: 2px solid var(--color-text); outline-offset: 2px; }
.tt-active-clear {
  padding: 0 6px;
  color: var(--color-muted);
  font: 540 14px/32px var(--font-ui);
  cursor: pointer;
}
.tt-active-clear:hover { color: var(--color-text); }
.tt-catalog-more {
  display: flex;
  justify-content: center;
  margin-top: 40px;
}
.tt-catalog-more .tt-pill { padding-inline: 28px; }
.tt-catalog-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  padding: 72px 16px;
  color: var(--color-muted);
  text-align: center;
}
.tt-catalog-empty p {
  margin: 0;
  color: var(--color-text);
  font: 600 18px/1.3 var(--font-brand);
}

/* Phone shelves: the page-wide grid rule above forced three 242px columns on
   the pager, so the next column showed only its icons. One column per screen
   with a peek wide enough to reveal the next names, full-bleed scroll,
   snapping to the gutter. */
@media (max-width: 640px) {
  .tt-catalog-page .tt-shelf-list {
    grid-template-columns: none;
    grid-auto-columns: calc(100% - 100px);
    column-gap: 20px;
    margin-inline: -20px;
    padding-inline: 20px;
    scroll-padding-inline: 20px;
  }
}

/* /tools grid cards ask ToolLogo for a 56px logo so the phone rows below stay
   sharp; on wider screens the identity logo keeps its 24px size. */
.tt-catalog-results .tce-logo {
  width: 24px !important;
  height: 24px !important;
  min-width: 24px !important;
  min-height: 24px !important;
  padding: 2px !important;
}

/* Phone results: App Store rows, like the shelves. A column of full-width
   covers gave one tool per screen and kept touch buttons over every image. */
@media (max-width: 640px) {
  .tt-catalog-page .tt-catalog-results .tc-grid {
    grid-template-columns: minmax(0, 1fr);
    row-gap: 0;
  }
  /* The cover keeps only its save button, moved to the end of the row; the
     image, its gradient and the explore shortcut stay hidden. */
  .tt-catalog-page .tt-catalog-results .tce-cover {
    position: absolute;
    top: 50%;
    right: 0;
    z-index: 6;
    transform: translateY(-50%);
  }
  .tt-catalog-page .tt-catalog-results .tce-cover > :not(.tce-hover-actions),
  .tt-catalog-page .tt-catalog-results .tce-cover::after,
  .tt-catalog-page .tt-catalog-results .tce-hover-action { display: none; }
  .tt-catalog-page .tt-catalog-results .tce-hover-actions {
    position: static;
    opacity: 1;
    pointer-events: auto;
    transform: none;
  }
  .tt-catalog-page .tt-catalog-results .tce-identity-copy { padding-right: 44px; }
  .tt-catalog-page .tt-catalog-results .tce-card--media .tce-body { padding: 12px 0; }
  .tt-catalog-page .tt-catalog-results .tce-identity-link {
    grid-template-columns: 56px minmax(0, 1fr);
    gap: 16px;
  }
  .tt-catalog-page .tt-catalog-results .tce-logo {
    width: 56px !important;
    height: 56px !important;
    min-width: 56px !important;
    min-height: 56px !important;
    padding: 3px !important;
    border-radius: 14px !important;
    box-shadow: 0 6px 16px rgb(0 0 0 / 0.08), inset 0 0 0 1px var(--color-border) !important;
  }
  .tt-catalog-page .tt-catalog-results .tce-identity-copy {
    flex-direction: column;
    align-items: flex-start;
    gap: 2px;
  }
  .tt-catalog-page .tt-catalog-results .tce-name { max-width: 100%; font-size: 16px; font-weight: 500; }
  .tt-catalog-page .tt-catalog-results .tce-category { max-width: 100%; font-size: 14px; }
  .tt-catalog-page .tt-catalog-results .tce-category::before { display: none; }
}
/* Once the row has scrolled, its start fades too instead of cutting a pill. */
.tt-catalog-page [data-toolbar] .tt-pillrow[data-scrolled="true"] {
  mask-image: linear-gradient(90deg, transparent, #000 32px, #000 calc(100% - 40px), transparent);
}

/* ToolLogo while its file is on the way (data-logo-loading): a soft tile
   instead of an empty white square. Beats the white !important tile
   backgrounds of shelf and card logos by specificity. */
img[data-logo-loading] {
  background-color: var(--color-surface-soft) !important;
  transition: background-color 200ms ease-out;
}

/* Save to "My stack" from the catalogue: a quiet bookmark at the end of each
   shelf row and phone result row, filled once saved. */
.tt-shelf-list > li { position: relative; }
.tt-shelf-list > li .tt-shelf-copy { padding-right: 44px; }
.tt-save {
  position: absolute;
  top: 50%;
  right: 0;
  z-index: 2;
  transform: translateY(-50%);
}
.tt-save .pin-tool-button {
  width: 36px;
  min-width: 36px;
  height: 36px;
  min-height: 36px;
  padding: 0;
  border: 0;
  border-radius: var(--radius-circle);
  background: transparent;
  box-shadow: none;
  color: var(--color-muted);
  transition: background-color 140ms ease-out, color 140ms ease-out;
}
.tt-save .pin-tool-button svg { width: 18px; height: 18px; }
.tt-save .pin-tool-button:hover {
  background: var(--color-surface-soft);
  color: var(--color-text);
}
.tt-save .pin-tool-button--active { color: var(--color-text); }
.tt-save .pin-tool-button::after { display: none; }
/* Same bookmark on the phone result rows; desktop cards keep their cover
   buttons. */
@media (max-width: 640px) {
  .tt-catalog-page .tt-catalog-results .tce-hover-actions .pin-tool-button {
    width: 36px;
    min-width: 36px;
    height: 36px;
    min-height: 36px;
    padding: 0;
    border: 0;
    border-radius: var(--radius-circle);
    background: transparent;
    box-shadow: none;
    color: var(--color-muted);
    transition: background-color 140ms ease-out, color 140ms ease-out;
  }
  .tt-catalog-page .tt-catalog-results .tce-hover-actions .pin-tool-button svg { width: 18px; height: 18px; }
  .tt-catalog-page .tt-catalog-results .tce-hover-actions .pin-tool-button:hover {
    background: var(--color-surface-soft);
    color: var(--color-text);
  }
  .tt-catalog-page .tt-catalog-results .tce-hover-actions .pin-tool-button--active { color: var(--color-text); }
  .tt-catalog-page .tt-catalog-results .tce-hover-actions .pin-tool-button::after { display: none; }
}
/* A need's top picks sit between the results header and the grid. */
.tt-catalog-results .tt-need-top { margin-bottom: 56px; }
@media (max-width: 640px) { .tt-catalog-results .tt-need-top { margin-bottom: 40px; } }

/* ── Category pages, aligned on /tools ─────────────────────────────────── */
.tt-catalog-page .cat-body .tt-spotlight { margin-bottom: clamp(48px, 5vw, 72px); }
.cat-guides { margin-top: clamp(56px, 6vw, 88px); }

/* A to Z index: every tool of the category as a plain link, so the page is a
   crawl path to each fiche. Quiet on purpose: a directory, not a feature. */
.cat-az { margin-top: clamp(56px, 6vw, 88px); }
.cat-az-title {
  margin: 0 0 16px;
  color: var(--color-text-strong);
  font: 600 18px/1.3 var(--font-brand);
  letter-spacing: -0.015em;
}
.cat-az-list {
  margin: 0;
  padding: 0;
  list-style: none;
  columns: 4 180px;
  column-gap: 28px;
}
.cat-az-list li { break-inside: avoid; }
.cat-az-list a {
  display: inline-block;
  padding: 3px 0;
  color: var(--color-muted);
  font-size: 14px;
  line-height: 1.4;
  text-decoration: none;
}
.cat-az-list a:hover { color: var(--color-text); text-decoration: underline; text-underline-offset: 3px; }

/* Other categories: pills, no rules between rows. */
.tt-catalog-page .cat-related {
  margin-top: clamp(48px, 5vw, 72px);
  padding-top: 0;
  border-top: 0;
}
.tt-catalog-page .cat-related-list { display: flex; flex-wrap: wrap; gap: 8px; }
.tt-catalog-page .cat-related-item { border-bottom: 0; }
.tt-catalog-page .cat-related-row {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  margin: 0;
  padding: 10px 16px;
  border-radius: var(--radius-pill);
  background: var(--color-surface-soft);
}
.tt-catalog-page .cat-related-row:hover { background: var(--color-chip); }
.tt-catalog-page .cat-related-name { font-size: 15px; font-weight: 560; }
.tt-catalog-page .cat-related-count { font-family: var(--font-ui); font-size: 13px; letter-spacing: 0; }
/* Category pages keep their lead visible: it is the page's own copy. */
.tt-catalog-page .cat-body .tt-catalog-compact-intro { display: block; margin-top: 14px; }
/* Without an eyebrow, the title needs the spacing the eyebrow gave. */
.tt-catalog-page .cat-body .tt-pepite-media + .tt-pepite-title { margin-top: 16px; }

/* Tool sub-pages: "NordPass pricing". The page name reads as a quiet second
   part of the title through weight, not grey (the site keeps text near-black);
   the compact sticky header keeps only the tool name. */
.td-hero-h1-page { font-weight: 400; }
.td-hero.is-compact .td-hero-h1-page { display: none; }
@layer components {
  .td-tapstitch-decision { display: grid; gap: 16px; color: inherit; }
  .td-tapstitch-decision p { margin: 0; line-height: 1.6; }
  .td-tapstitch-decision ol { padding-left: 22px; display: grid; gap: 14px; }
  .td-tapstitch-decision .td-hero-site-link { white-space: normal; text-align: center; }
  .td-tapstitch-note { font-size: 14px; }
}
@layer components {
  .cp-guide-product-visual { margin: 2rem 0; }
  .cp-guide-product-visual img { display: block; width: 100%; max-height: 480px; object-fit: contain; border-radius: 16px; background: #F8F8F4; }
  .cp-guide-product-visual figcaption { margin-top: .5rem; font-size: .875rem; color: #6F6F68; }
  .cp-guide-source-url { display: block; overflow-wrap: anywhere; font-size: .875rem; }
}

/* ── Pages « meilleurs outils » par intention (BestOfGuidePage.tsx) ─────────
   Préfixe gb-. Mêmes jetons que les guides : surfaces claires, texte sombre,
   aucun bouton bleu ni dégradé. */
@layer components {
  .gb-wrap { max-width: 880px; margin: 0 auto; padding: 0 var(--space-lg); }
  .gb-crumbs { padding-top: var(--space-lg); }
  .gb-hero { padding-top: clamp(24px, 4vw, 48px); padding-bottom: clamp(24px, 4vw, 40px); }
  .gb-eyebrow { margin: 0 0 var(--space-sm); color: var(--color-muted); font-family: var(--font-ui); font-size: 13px; }
  .gb-title { margin: 0; font-family: var(--font-ui); font-size: clamp(30px, 4vw, 44px); font-weight: 600; line-height: 1.1; letter-spacing: -0.03em; color: var(--color-text-strong); }
  .gb-intro { margin: var(--space-md) 0 0; max-width: 680px; color: var(--color-muted); font-size: 18px; line-height: 1.6; }
  .gb-section { padding-top: clamp(24px, 3.5vw, 40px); padding-bottom: clamp(24px, 3.5vw, 40px); }
  .gb-h2 { display: flex; align-items: center; gap: 10px; margin: 0 0 var(--space-md); font-family: var(--font-ui); font-size: clamp(22px, 2.4vw, 28px); font-weight: 600; letter-spacing: -0.02em; color: var(--color-text-strong); }
  .gb-h3 { margin: 0; font-family: var(--font-ui); font-size: 21px; font-weight: 600; letter-spacing: -0.015em; color: var(--color-text-strong); }
  .gb-text { margin: var(--space-sm) 0 0; color: var(--color-text); font-size: 16px; line-height: 1.65; }
  .gb-muted { color: var(--color-muted); font-size: 15px; }
  .gb-note { margin: var(--space-sm) 0 0; color: var(--color-muted); font-size: 13px; }
  .gb-icon { width: 18px; height: 18px; flex: none; }
  .gb-yes { color: var(--color-text-strong); }
  .gb-no { color: var(--color-muted-light); }
  .gb-logo { border-radius: var(--radius-sm); flex: none; }

  .gb-picks { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-md); }
  .gb-pick { display: flex; flex-direction: column; gap: 10px; padding: var(--space-md); border: 1px solid var(--color-border); border-radius: var(--radius-lg); background: var(--color-surface); color: var(--color-text); text-decoration: none; transition: border-color .15s ease; }
  .gb-pick:hover { border-color: var(--color-border-strong); }
  .gb-pick-label { color: var(--color-muted); font-family: var(--font-ui); font-size: 12px; font-weight: 500; text-transform: uppercase; letter-spacing: .04em; }
  .gb-pick-tool { display: flex; align-items: center; gap: 10px; }
  .gb-pick-name { font-family: var(--font-ui); font-size: 17px; font-weight: 600; color: var(--color-text-strong); }
  .gb-pick-meta { color: var(--color-muted); font-size: 14px; }

  .gb-angle { padding: var(--space-md) var(--space-lg); border-left: 3px solid var(--color-text-strong); border-radius: var(--radius-sm); background: var(--color-surface-soft); }
  .gb-angle-label { display: flex; align-items: center; gap: 8px; margin: 0; font-family: var(--font-ui); font-size: 14px; font-weight: 600; color: var(--color-text-strong); }
  .gb-angle-text { margin: var(--space-sm) 0 0; font-size: 16px; line-height: 1.65; color: var(--color-text); }

  .gb-table-scroll { overflow-x: auto; border: 1px solid var(--color-border); border-radius: var(--radius-lg); background: var(--color-surface); }
  .gb-table { width: 100%; border-collapse: collapse; font-size: 15px; }
  .gb-table th { padding: 12px 14px; border-bottom: 1px solid var(--color-border); color: var(--color-muted); font-family: var(--font-ui); font-size: 12px; font-weight: 500; text-align: left; text-transform: uppercase; letter-spacing: .04em; white-space: nowrap; }
  .gb-table td { padding: 12px 14px; border-bottom: 1px solid var(--color-border-soft); vertical-align: middle; }
  .gb-table tr:last-child td { border-bottom: 0; }
  .gb-rank { width: 36px; color: var(--color-muted); font-variant-numeric: tabular-nums; }
  .gb-table-tool { display: flex; flex-direction: column; color: var(--color-text); text-decoration: none; }
  .gb-table-name { font-weight: 600; color: var(--color-text-strong); }
  .gb-table-tagline { color: var(--color-muted); font-size: 13px; }

  .gb-ai-list { display: grid; gap: 0; margin: var(--space-md) 0 0; padding: 0; list-style: none; border-top: 1px solid var(--color-border); }
  .gb-ai-item { display: grid; grid-template-columns: 180px 1fr; gap: var(--space-md); padding: 12px 0; border-bottom: 1px solid var(--color-border-soft); font-size: 15px; }
  .gb-ai-name { font-weight: 600; color: var(--color-text-strong); }
  .gb-ai-text { color: var(--color-text); line-height: 1.55; }

  .gb-review { padding: var(--space-xl) 0; border-top: 1px solid var(--color-border); scroll-margin-top: calc(var(--navbar-h) + 16px); }
  .gb-review-head { display: flex; align-items: center; gap: 14px; }
  .gb-review-tagline { margin: 2px 0 0; color: var(--color-muted); font-size: 14px; }
  .gb-facts { display: flex; flex-wrap: wrap; gap: 8px; margin: var(--space-md) 0 0; padding: 0; }
  .gb-facts span { padding: 4px 10px; border-radius: var(--radius-pill); background: #E0DBD7; color: var(--color-text-strong); font-size: 13px; font-weight: 500; }
  .gb-proscons { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-lg); margin-top: var(--space-md); }
  .gb-list { display: grid; gap: 8px; margin: 0; padding: 0; list-style: none; font-size: 15px; line-height: 1.5; }
  .gb-list li { display: flex; gap: 8px; }
  .gb-list .gb-icon { margin-top: 2px; }
  .gb-verdict { display: grid; grid-template-columns: max-content 1fr; gap: 8px 16px; margin: var(--space-md) 0 0; font-size: 15px; line-height: 1.55; }
  .gb-verdict dt { font-family: var(--font-ui); font-weight: 600; color: var(--color-text-strong); }
  .gb-verdict dd { margin: 0; color: var(--color-text); }
  .gb-links { display: flex; flex-wrap: wrap; gap: var(--space-lg); margin: var(--space-md) 0 0; font-family: var(--font-ui); font-size: 14px; font-weight: 500; }
  .gb-links a { color: var(--color-text-strong); text-decoration: underline; text-underline-offset: 3px; }

  .gb-more-list { display: grid; gap: 0; margin: 0; padding: 0; list-style: none; border-top: 1px solid var(--color-border); }
  .gb-more-list a { display: flex; align-items: center; justify-content: space-between; padding: 14px 0; border-bottom: 1px solid var(--color-border-soft); color: var(--color-text-strong); font-family: var(--font-ui); font-weight: 500; text-decoration: none; }

  @media (max-width: 720px) {
    .gb-wrap { padding: 0 16px; }
    .gb-picks { grid-template-columns: 1fr; }
    .gb-proscons { grid-template-columns: 1fr; }
    .gb-verdict { grid-template-columns: 1fr; gap: 2px; }
    .gb-verdict dd { margin-bottom: 8px; }
    .gb-ai-item { grid-template-columns: 1fr; gap: 2px; }
  }
}

@layer components {
  .gi-bestof { margin: 0 0 var(--space-lg); }
  .gi-bestof-title { margin: 0 0 var(--space-sm); color: var(--color-muted); font-family: var(--font-ui); font-size: 13px; font-weight: 500; }
  .gi-bestof-list { display: flex; flex-wrap: wrap; gap: 8px; margin: 0; padding: 0; list-style: none; }
  .gi-bestof-list a { display: inline-flex; padding: 6px 12px; border: 1px solid var(--color-border); border-radius: var(--radius-pill); background: var(--color-surface); color: var(--color-text-strong); font-family: var(--font-ui); font-size: 14px; text-decoration: none; }
  .gi-bestof-list a:hover { border-color: var(--color-border-strong); }
}


/* ══ US-NAV-01 : barre du haut qui réagit au scroll ═══════════════════════
   AppShellV2 pose data-chrome="hidden" quand on descend, "shown" quand on
   remonte ou en haut de page. Ordinateur : la barre se replie dans le sens
   du scroll (marge négative), le contenu et ses barres collantes suivent sans
   changer leur propre calage. Mobile : la page défile, la barre glisse hors
   de l'écran et les barres collantes de page prennent sa place via
   --asv2-chrome-h. */
.asv2-root { --asv2-chrome-h: 56px; }
.asv2-root[data-chrome="hidden"] { --asv2-chrome-h: 0px; }

@media (min-width: 641px) {
  .asv2-topbar { transition: margin-top 220ms cubic-bezier(0.2, 0.8, 0.2, 1), opacity 160ms ease-out; }
  .asv2-root[data-chrome="hidden"] .asv2-topbar { margin-top: -56px; opacity: 0; }
}
@media (max-width: 640px) {
  .asv2-topbar { transition: transform 220ms cubic-bezier(0.2, 0.8, 0.2, 1); }
  .asv2-root[data-chrome="hidden"] .asv2-topbar { transform: translateY(-100%); }
}

/* Recherche compacte dans la barre du haut (ordinateur et tablette) : visible
   quand le fil d'Ariane ou les raccourcis occupent la place du grand champ. */
.asv2-topbar-search { display: none; }
@media (min-width: 641px) {
  .asv2-topbar:not([data-topbar-mode="search"]) .asv2-topbar-search {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    height: 34px;
    padding: 0 8px 0 12px;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-pill);
    background: var(--color-surface);
    color: var(--color-muted);
    font-family: var(--font-ui);
    font-size: 13px;
    cursor: pointer;
    transition: border-color 140ms ease-out, color 140ms ease-out;
  }
  .asv2-topbar-search:hover,
  .asv2-topbar-search:focus-visible { border-color: var(--color-border-strong); color: var(--color-text); }
  .asv2-topbar-search:focus-visible { outline: 2px solid var(--color-text-strong); outline-offset: 2px; }
  .asv2-topbar-search .asv2-kbd { display: inline-flex; }
}
@media (min-width: 641px) and (max-width: 1080px) {
  .asv2-topbar-search-label, .asv2-topbar-search .asv2-kbd { display: none !important; }
  .asv2-topbar-search { padding: 0; width: 34px; justify-content: center; }
}

@media (prefers-reduced-motion: reduce) {
  .asv2-topbar,
  .tt-catalog-page .tt-sticky-toolbar,
  .tt-catalog-page .tt-sticky-toolbar--stuck { transition: none !important; }
}

/* ══ US-NAV-01 : menu mobile (MobileMenu.tsx) ══════════════════════════════
   Bouton visible sous 641 px seulement. Panneau plein écran à droite, un
   niveau à la fois, animation courte, désactivée si l'utilisateur réduit
   les animations. */
.asv2-topbar-menu { display: none; }
@media (max-width: 640px) {
  .asv2-topbar-menu {
    display: grid;
    place-items: center;
    width: 42px;
    height: 42px;
    flex: none;
    padding: 0;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-pill);
    background: var(--color-surface);
    color: var(--color-text-strong);
    cursor: pointer;
  }
  .asv2-topbar-menu:focus-visible { outline: 2px solid var(--color-text-strong); outline-offset: 2px; }
}

