.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-utility-item > svg { box-sizing: content-box; width: 18px; height: 18px; padding: 7px; }
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-utility-item .asv2-currency-glyph { justify-self: center; margin: 7px; }
@media (min-width: 641px) and (max-width: 1180px) {
