.asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-nav-item--active::before { display: none; }
.asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-utility-item > svg { box-sizing: content-box; width: 18px; height: 18px; padding: 7px; }
.asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-utility-item .asv2-currency-glyph { justify-self: center; margin: 7px; }
