/* ══ Navigation, revue design du 9 oct. 2026 ═══════════════════════════════
   Mesures Playwright à 1440, 1024 et 390 px. */

/* Le haut de page suit le conteneur des pages (--layout-content et
   --layout-gutter) : fil d'Ariane et contenu partent du même bord. */
@media (min-width: 641px) {
  .asv2-topbar {
    padding-inline: max(var(--layout-gutter), calc((100% - var(--layout-content)) / 2 + var(--layout-gutter)));
  }
}

/* Colonne réduite : la page active se distingue du survol. Avant, les deux
   avaient la même pastille et le libellé actif restait en 500. */
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-nav-item:not(.asv2-nav-item--active):hover .asv2-nav-icon,
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-nav-item:not(.asv2-nav-item--active):focus-visible .asv2-nav-icon {
  background: color-mix(in srgb, var(--color-surface-soft) 56%, var(--color-surface));
}
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-nav-item--active .asv2-nav-icon {
  background: color-mix(in srgb, var(--color-text-strong) 9%, var(--color-surface));
  color: var(--color-text-strong);
}
.asv2-root:not(.asv2-root--sidebar-expanded) .asv2-nav .asv2-nav-item--active .asv2-nav-label {
  color: var(--color-text-strong);
  font-weight: 650;
}
@media (min-width: 641px) and (max-width: 1180px) {
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-nav-item:not(.asv2-nav-item--active):hover .asv2-nav-icon,
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-nav-item:not(.asv2-nav-item--active):focus-visible .asv2-nav-icon {
    background: color-mix(in srgb, var(--color-surface-soft) 56%, var(--color-surface));
  }
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-nav-item--active .asv2-nav-icon {
    background: color-mix(in srgb, var(--color-text-strong) 9%, var(--color-surface));
    color: var(--color-text-strong);
  }
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-nav .asv2-nav-item--active .asv2-nav-label {
    color: var(--color-text-strong);
    font-weight: 650;
  }
}

/* Colonne imposée (641 à 1 180 px) avec la préférence « déployée » : le fond
   de l'entrée entière, propre à la barre large, doublait la pastille de
   l'icône. Une seule pastille, comme dans la colonne réduite. */
@media (min-width: 641px) and (max-width: 1180px) {
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-nav-item,
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-nav-item:hover,
  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-nav-item--active {
    background: transparent;
    transform: none;
  }
}

/* Libellés sous icône : 11 px partout (colonne réduite et barre du bas). */
