  .asv2-root--sidebar-expanded:not(.asv2-root--rail-open) .asv2-sidebar-submit .asv2-nav-label { font-size: 11px; }
}

/* Menu mobile : il ne garde que les sous-niveaux, la ligne entière ouvre. */
.asv2-mm-link--drill {
  justify-content: space-between;
  width: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  text-align: left;
  cursor: pointer;
}
.asv2-mm-link--drill svg { width: 20px; height: 20px; color: var(--color-muted); }
.asv2-mm-link--drill > span { flex: 1; }

/* Accueil : le champ de recherche occupe la place du fil d'Ariane, au bord du
   contenu. Version de barre : hauteur et contour des boutons voisins, loupe
   en tête, raccourci en bout ; plus de pastille de 48 px ni de rond noir. */
@media (min-width: 641px) {
  .asv2-topbar .asv2-search {
    flex: 0 1 440px;
    height: 36px;
    min-width: 0;
    gap: 8px;
    padding: 0 6px 0 12px;
    border: 1px solid var(--color-border-soft);
    background: var(--color-surface);
    color: var(--color-muted);
    font-size: 14px;
    font-weight: 500;
    transition: border-color 140ms ease-out, background-color 140ms ease-out;
  }
  .asv2-topbar .asv2-search:hover {
    border-color: var(--color-muted);
    background: var(--color-surface-soft);
  }
  .asv2-topbar .asv2-search:focus-visible { outline: 2px solid var(--color-text-strong); outline-offset: 2px; box-shadow: none; }
  .asv2-topbar .asv2-search span.asv2-search-action {
    order: -1;
    width: auto;
    height: auto;
    background: transparent;
    color: inherit;
  }
  .asv2-topbar .asv2-search:hover span.asv2-search-action { background: transparent; }
  .asv2-topbar .asv2-search .asv2-kbd { padding: 2px 6px; }
}

/* Dialogues (menu mobile, recherche) au-dessus du bandeau cookies. */
.asv2-mm { z-index: 1100; }
@keyframes asv2-mm-slide-out { from { transform: none; opacity: 1; } to { transform: translateX(24px); opacity: 0; } }

/* US-NAV-01 : au scroll vers le bas, la barre d'onglets du bas cède aussi la
   place au contenu, et revient avec la barre du haut dès qu'on remonte. */
@media (max-width: 640px) {
  .asv2-bottomnav { transition: transform 220ms cubic-bezier(0.2, 0.8, 0.2, 1); }
  .asv2-root[data-chrome="hidden"] .asv2-bottomnav { transform: translateY(calc(100% + 8px)); }
  .asv2-root[data-chrome="hidden"] .asv2-bottomnav:focus-within { transform: none; }
}
