  .td-hero-actions .td-hero-site-link,
  .td-hero-actions .pin-tool-button.pin-tool-button--full { flex: 1 1 100%; }
}
/* Barre d'action mobile de la fiche : en lecture (chrome masqué), elle prend
   la place des onglets du bas ; on remonte, les onglets reviennent. */
.td-mobile-actionbar { display: none; }
@media (max-width: 640px) {
  .td-mobile-actionbar {
    display: flex; align-items: center; gap: 10px;
