    transition: transform 220ms cubic-bezier(0.2, 0.8, 0.2, 1);
  }
  .asv2-root[data-chrome="hidden"] .td-mobile-actionbar.is-armed { transform: none; }
  .td-mobile-actionbar-logo { flex: none; border-radius: 8px; }
  .td-mobile-actionbar-id { display: flex; flex: 1; flex-direction: column; min-width: 0; }
  .td-mobile-actionbar-id strong { overflow: hidden; color: var(--color-text); font: 650 15px/1.25 var(--font-ui); text-overflow: ellipsis; white-space: nowrap; }
  .td-mobile-actionbar-id span { overflow: hidden; color: var(--color-muted); font: 400 13px/1.3 var(--font-ui); text-overflow: ellipsis; white-space: nowrap; }
  .td-mobile-actionbar .pin-tool-button { position: static; flex: 0 0 44px; width: 44px; height: 44px; padding: 0; border: 1px solid var(--color-border); border-radius: 50%; background: var(--color-surface); color: var(--color-text); display: inline-flex; align-items: center; justify-content: center; }
  .td-mobile-actionbar-cta { display: inline-flex; flex: none; align-items: center; gap: 6px; min-height: 44px; padding: 0 18px; border-radius: var(--radius-pill); background: var(--color-text); color: var(--color-surface); font: 600 15px/20px var(--font-ui); text-decoration: none; }
