  .td-localnav-inner.td-container { display: flex; align-items: center; gap: 26px; height: 60px; padding-top: 0; padding-bottom: 0; }
  .td-localnav-title {
    display: flex; flex: 1; align-items: center; gap: 10px; min-width: 0; color: var(--color-text); text-decoration: none;
  }
