  .td-localnav-links a[aria-current="page"] { color: hsl(var(--primary)); opacity: 1; cursor: default; }
  .td-localnav-links a[aria-current="page"]::after {
    content: ""; position: absolute; left: 0; right: 0; bottom: 0; z-index: 1; height: 2px;
    border-radius: 2px 2px 0 0; background: hsl(var(--primary));
  }
  .td-localnav .pin-tool-button {
