  .td-plans::-webkit-scrollbar { display: none; }
  .td-plans > .td-plan { flex: 0 0 82%; }
  .td-plans[data-plans="1"] > .td-plan { flex-basis: 100%; }
}
@container td-pricing (min-width: 452px) {
  .td-plans[data-plans="1"] { --cols: 1; }
  .td-plans[data-plans="2"] { --cols: 2; }
  .td-plans[data-plans="3"] { --cols: 2; }
  .td-plans[data-plans="4"] { --cols: 2; }
  .td-plans[data-plans="5"] { --cols: 2; }
  .td-plans[data-plans="6"] { --cols: 2; }
  .td-plans[data-plans="7"] { --cols: 2; }
  .td-plans[data-plans="8"] { --cols: 2; }
}
@container td-pricing (min-width: 684px) {
  .td-plans[data-plans="1"] { --cols: 1; }
  .td-plans[data-plans="2"] { --cols: 2; }
  .td-plans[data-plans="3"] { --cols: 3; }
  .td-plans[data-plans="4"] { --cols: 2; }
  .td-plans[data-plans="5"] { --cols: 3; }
  .td-plans[data-plans="6"] { --cols: 3; }
  .td-plans[data-plans="7"] { --cols: 3; }
  .td-plans[data-plans="8"] { --cols: 3; }
}
@container td-pricing (min-width: 916px) {
  .td-plans[data-plans="1"] { --cols: 1; }
  .td-plans[data-plans="2"] { --cols: 2; }
  .td-plans[data-plans="3"] { --cols: 3; }
  .td-plans[data-plans="4"] { --cols: 4; }
  .td-plans[data-plans="5"] { --cols: 3; }
  .td-plans[data-plans="6"] { --cols: 3; }
  .td-plans[data-plans="7"] { --cols: 4; }
  .td-plans[data-plans="8"] { --cols: 4; }
}
.td-plan {
  position: relative;
  display: flex; flex-direction: column; gap: 10px; min-width: 0; padding: 22px 18px 20px;
  border: 1px solid var(--color-border); border-radius: 16px; background: var(--color-surface);
  scroll-snap-align: start;
}
.td-plan--reference { border-color: var(--color-text); }
.td-plan--soon { opacity: .7; }
.td-plan-head { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 8px; min-height: 22px; }
.td-plan-name { margin: 0; color: var(--color-text); font: 600 15px/1.25 var(--font-ui); }
/* Repère posé sur le bord haut : il n'abaisse pas le prix de sa colonne. */
.td-plan-badge {
