.td-plan-price strong { color: var(--color-text); font: 650 26px/1.1 var(--font-ui); letter-spacing: -.02em; }
.td-plan-price span { color: var(--color-muted); font: 500 14px/1.2 var(--font-ui); }
.td-plan-condition { margin: 0; color: var(--color-muted); font: 400 13px/1.45 var(--font-ui); }
