/* ── Fiche outil : apparitions douces au défilement (2 oct.) ──
   Les sections montent de 16 px en apparaissant. La classe .td-reveal n'est
   posée qu'après le montage (le HTML servi reste visible) ; rien en
   mouvement réduit. La note de la carte se remplit à l'arrivée. */
@media (prefers-reduced-motion: no-preference) {
  .td-reveal { opacity: 0; transform: translateY(16px); }
  .td-reveal.is-revealed {
    opacity: 1; transform: none;
    transition: opacity 600ms cubic-bezier(0.2, 0.8, 0.2, 1), transform 700ms cubic-bezier(0.2, 0.8, 0.2, 1);
  }
  .td-decision-verdict-gauge-fill { animation: td-gauge-fill 1100ms cubic-bezier(0.2, 0.8, 0.2, 1) 200ms both; }
  .td-decision-verdict-score strong { animation: td-rise 600ms cubic-bezier(0.2, 0.8, 0.2, 1) 150ms both; display: inline-block; }
}
@keyframes td-gauge-fill { from { stroke-dashoffset: 87.96px; } }
@keyframes td-rise { from { opacity: 0; transform: translateY(6px); } }
/* ── Fiche outil : couleur d'accent tirée du logo (2 oct.) ──
   --tool-accent est posé en style sur la fiche (src/data/toolAccents.json,
   gen-tool-accents.mjs). Pas de classe dédiée : une classe présente sur une
   partie des fiches seulement doublait les variantes de CSS critique (budget
   du build dépassé). Les dérivées ci-dessous deviennent invalides sans
   accent, et chaque règle retombe alors sur sa couleur d'origine (repli de
   var()). Teintes unies seulement, pas de dégradé. */
.td-tool-page {
  --tool-accent-ink: color-mix(in oklab, var(--tool-accent) 68%, #000);
  --tool-accent-soft: color-mix(in srgb, var(--tool-accent) 9%, var(--color-surface));
  --tool-accent-line: color-mix(in srgb, var(--tool-accent) 32%, var(--color-border));
}
.dark .td-tool-page { --tool-accent-ink: color-mix(in oklab, var(--tool-accent) 70%, #fff); }
.td-tool-page .td-hero-logo { background: var(--tool-accent-soft, var(--color-surface)); border-color: var(--tool-accent-line, var(--color-border)); }
.td-tool-page .td-tool-subnav a[aria-current="page"] { color: var(--tool-accent-ink, var(--color-text)); }
.td-tool-page .td-localnav-links a[aria-current="page"],
.td-tool-page .td-localnav-links a:hover,
.td-tool-page .td-localnav .pin-tool-button:hover,
.td-tool-page .td-localnav-title:hover > span:last-child { color: var(--tool-accent-ink, hsl(var(--primary))); }
.td-tool-page .td-localnav-links a[aria-current="page"]::after { background: var(--tool-accent-ink, hsl(var(--primary))); }
.td-tool-page .td-localnav-logo { border-radius: 8px; background: var(--tool-accent-soft, transparent); box-shadow: inset 0 0 0 1px var(--tool-accent-line, transparent); }
.td-tool-page .td-eyebrow { color: var(--tool-accent-ink, var(--color-muted)); }
.td-tool-page .td-plan--reference { border-color: var(--tool-accent-ink, var(--color-text)); }
.td-tool-page .td-plan-badge { background: var(--tool-accent-ink, var(--color-text)); }
/* ── Fiche outil : rythme éditorial (2 oct.) ──
   Chapitres plus aérés et titres un peu plus présents, toujours sous le nom
   de l'outil (40-56 px). Tous les titres suivent la même grammaire :
   « Sujet. Question en gris ». */
.td-tool-page { --tt-size-section-h: clamp(26px, 2.7vw, 38px); }
@media (min-width: 769px) { .td-tool-page .td-main { --td-chapter-gap: clamp(72px, 7.5vw, 112px); } }
/* « Ajouter à ma stack » : le signet se coche avec un petit rebond. */
@media (prefers-reduced-motion: no-preference) {
  .pin-tool-button--active svg { animation: tt-pin-pop 420ms cubic-bezier(0.3, 1.6, 0.5, 1); }
}
@keyframes tt-pin-pop { 0% { transform: scale(.6); } 60% { transform: scale(1.18); } 100% { transform: none; } }

/* Mon Stack — catalogue inventory, usage map, and integrated context. */
@layer components {

  .ms-page { max-width: 1440px; margin: 0 auto; padding: var(--space-2xl) var(--space-2xl) var(--space-3xl); color: hsl(var(--foreground)); font-family: var(--font-ui); }

  .ms-empty-copy { font-size: var(--tt-size-body-large); line-height: 1.5; }

  .ms-empty-copy { max-width: 620px; margin: var(--space-2xl) 0 var(--space-lg); }

  .ms-search { max-width: 680px; margin: 0 0 var(--space-xl); }

  .ms-search-input { display: flex; align-items: center; gap: var(--space-sm); padding: var(--space-xs) var(--space-md); border: 1px solid hsl(var(--border)); border-radius: var(--tt-surface-radius-info); background: hsl(var(--card)); }

  .ms-search-input input { flex: 1; min-width: 0; padding: var(--space-xs) 0; background: transparent; outline: none; font-size: var(--tt-size-body); }

  .ms-search-input:focus-within { outline: 2px solid hsl(var(--primary)); outline-offset: 2px; }

  .ms-search-status { padding: var(--space-sm) var(--space-md) var(--space-xs); font-size: var(--tt-size-card-body); }

  .ms-results { list-style: none; padding: 0; }

  .ms-results li { display: flex; align-items: center; gap: var(--space-sm); padding: var(--space-xs) var(--space-md); border-bottom: 1px solid hsl(var(--border)); }

  .ms-results a { flex: 1; padding: var(--space-xs) 0; font-weight: 600; }

  .ms-results button, .ms-icon-action { display: inline-flex; align-items: center; justify-content: center; width: 44px; height: 44px; border-radius: var(--tt-surface-radius-info); flex-shrink: 0; }

  .ms-results button:hover:not(:disabled), .ms-icon-action:hover { background: hsl(var(--secondary)); }

  .ms-results button:disabled { opacity: 0.55; }

  .ms-domain-filters { display: flex; flex: 1; min-width: 0; gap: var(--space-lg); overflow-x: auto; scrollbar-width: thin; }

  .ms-domain-filters button { display: inline-flex; align-items: center; flex-shrink: 0; gap: var(--space-xs); min-height: 60px; padding: var(--space-sm) 0; border-bottom: 2px solid transparent; white-space: nowrap; color: hsl(var(--muted-foreground)); font-size: var(--tt-size-card-body); font-weight: 500; }

  .ms-domain-filters button[aria-pressed="true"] { color: hsl(var(--foreground)); border-bottom-color: hsl(var(--foreground)); font-weight: 600; }

  .ms-domain-filters button > span { display: inline-flex; align-items: center; justify-content: center; min-width: 24px; height: 24px; padding: 0 var(--space-2xs); border-radius: var(--radius-pill); background: hsl(var(--secondary)); font-size: var(--tt-size-kicker); color: hsl(var(--foreground)); }

  .ms-tool { display: flex; align-items: center; text-align: left; gap: var(--space-sm); min-width: 0; width: 100%; padding: var(--space-xs) var(--space-sm); border-radius: var(--tt-surface-radius-info); background: transparent; transition: background 160ms ease; }

  .ms-tool:hover, .ms-tool--selected { background: hsl(var(--secondary)); }

  .ms-tool--selected { outline: 1px solid hsl(var(--border)); }
  .ms-storage-notice { font-size: var(--tt-size-card-body); line-height: 1.5; margin-bottom: var(--space-lg); }

  .ms-unavailable { margin-top: var(--space-xl); }

  .ms-unavailable > p { font-size: var(--tt-size-card-body); margin-bottom: var(--space-md); }

  .ms-unavailable > div { display: flex; align-items: center; justify-content: space-between; gap: var(--space-md); padding: var(--space-xs) 0; border-bottom: 1px solid hsl(var(--border)); overflow-wrap: anywhere; }

  .ms-unavailable button { min-height: 44px; flex-shrink: 0; font-size: var(--tt-size-card-body); }

  .ms-page button:focus-visible, .ms-page a:focus-visible { outline: 2px solid hsl(var(--primary)); outline-offset: 3px; }
  @media (max-width: 639px) {
  .ms-page { padding: var(--space-lg) var(--space-md) var(--space-2xl); }

  .ms-domain-filters { gap: var(--space-md); }

  .ms-empty-copy { font-size: var(--tt-size-body); }

  .ms-empty-copy { margin-top: var(--space-lg); }
  }
  @media (prefers-reduced-motion: reduce) {
