}

@layer components {
  .ms-card-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: var(--space-md); margin-top: var(--space-md); }
  .ms-tool.ms-tool-card { display: grid; grid-template-columns: 40px minmax(0, 1fr) auto; column-gap: var(--space-sm); row-gap: var(--space-xs); padding: var(--space-md); background: hsl(var(--secondary) / .4); border: 1px solid transparent; border-radius: var(--tt-surface-radius-info); align-items: start; align-content: start; transition: background 160ms ease, border-color 160ms ease; }
  .ms-tool-card > :first-child { grid-column: 1; grid-row: 1 / 3; }
  .ms-tool.ms-tool-card:hover { background: hsl(var(--secondary)); }
  .ms-tool.ms-tool-card.ms-tool--selected { background: hsl(var(--secondary)); border-color: hsl(var(--foreground)); }
  .ms-tool-card:focus-visible { outline: 2px solid hsl(var(--foreground)); outline-offset: 3px; }
  @media (max-width: 639px) {
    .ms-card-grid { grid-template-columns: 1fr; }
  }
}
/* ── Ma stack : repasse design (7 oct.) ──
   Même ton que la fiche outil : surfaces plates, filets fins, pilules,
   sélecteur segmenté discret. Aucun dégradé (charte), aucun relief simulé.
   Logique et structure de la V2 inchangées : seulement l'apparence. */
/* Onglets de domaines : compteurs en simple chiffre gris, pas en pastille. */
.ms-page .ms-domain-filters button { min-height: 48px; font-size: 14px; }
.ms-page .ms-domain-filters button > span { min-width: 0; height: auto; padding: 0; background: transparent; color: hsl(var(--muted-foreground)); font-size: 13px; font-weight: 500; font-variant-numeric: tabular-nums; }
.ms-page .ms-domain-filters button[aria-pressed="true"] > span { color: hsl(var(--foreground)); }
/* Le titre répète l'onglet actif : gardé pour les lecteurs d'écran seulement. */
.ms-page .ms-list-title { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
/* Cartes d'outils : blanches, filet fin, élévation au survol (comme le catalogue). */
.ms-page .ms-tool.ms-tool-card {
  background: hsl(var(--card)); border: 1px solid hsl(var(--border)); border-radius: 16px;
  transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease;
}
.ms-page .ms-tool.ms-tool-card:hover { background: hsl(var(--card)); border-color: hsl(var(--muted-foreground) / .35); box-shadow: 0 8px 24px rgba(15, 15, 15, .06); transform: translateY(-2px); }
.ms-page .ms-tool.ms-tool-card.ms-tool--selected { border-color: hsl(var(--foreground)); outline: 0; }

@media (prefers-reduced-motion: reduce) { .ms-page .ms-tool.ms-tool-card:hover { transform: none; } }

/* Ma stack, lecture d'ensemble (7 oct.) : une ligne factuelle sous le titre,
   et sur chaque carte le recoupement possible, même règle que le panneau. */
/* Fiche outil : rappel discret de ce que la stack contient déjà. */
.td-stack-note { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 12px; margin: 0; color: hsl(var(--muted-foreground)); font: 400 14px/1.45 var(--font-ui); }
.td-tool-page .td-hero:not(.is-compact) .td-stack-note { grid-column: 2; }
.td-stack-note a { color: var(--tool-accent-ink, var(--color-text)); font-weight: 600; text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; }
@media (max-width: 640px) { .td-tool-page .td-hero:not(.is-compact) .td-stack-note { grid-column: 1 / -1; } }
/* Stack vide : trois étapes, numérotées, sans suggestion d'outils. */
.ms-page .ms-howto { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; max-width: 980px; margin: 40px 0 0; padding: 0; list-style: none; counter-reset: ms-howto; }
.ms-page .ms-howto li { display: grid; gap: 6px; padding: 20px; border: 1px solid hsl(var(--border)); border-radius: 16px; background: hsl(var(--card)); counter-increment: ms-howto; }
.ms-page .ms-howto li::before { content: counter(ms-howto); display: grid; place-items: center; width: 28px; height: 28px; margin-bottom: 6px; border-radius: 50%; background: hsl(var(--foreground)); color: hsl(var(--background)); font: 600 13px/1 var(--font-ui); }
.ms-page .ms-howto strong { font: 600 16px/1.3 var(--font-ui); color: hsl(var(--foreground)); }
.ms-page .ms-howto span { font: 400 14px/1.5 var(--font-ui); color: hsl(var(--muted-foreground)); }
@media (max-width: 760px) { .ms-page .ms-howto { grid-template-columns: 1fr; margin-top: 28px; } .ms-page .ms-howto li { grid-template-columns: 28px 1fr; column-gap: 12px; padding: 16px; } .ms-page .ms-howto li::before { grid-row: 1 / 3; margin: 0; } }
/* ── Ma stack, cartes (7 oct.) ──
   Deux zones fixes : l'identité en haut (logo dans un cadre teinté de la
   couleur de l'outil, nom, catégorie), puis un pied posé sur un filet, aligné
   d'une carte à l'autre (prix à gauche, recoupement à droite sur une ligne). */
.ms-page .ms-card-grid { grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 14px; align-items: stretch; }
.ms-page .ms-tool.ms-tool-card {
  display: flex; flex-direction: column; align-items: stretch; gap: 0; height: 100%; padding: 0; text-align: left;
}
.ms-page .ms-card-top { display: flex; align-items: center; gap: 14px; padding: 18px 18px 16px; min-width: 0; }
.ms-page .ms-card-logo {
  display: grid; flex: none; place-items: center; width: 52px; height: 52px; border-radius: 14px;
  background: color-mix(in srgb, var(--tool-accent, hsl(var(--secondary))) 12%, hsl(var(--card)));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--tool-accent, hsl(var(--border))) 28%, hsl(var(--border)));
}
.ms-page .ms-card-id { display: grid; gap: 3px; min-width: 0; }
.ms-page .ms-card-id strong { overflow: hidden; color: hsl(var(--foreground)); font: 650 17px/1.25 var(--font-ui); letter-spacing: -.01em; text-overflow: ellipsis; white-space: nowrap; }
.ms-page .ms-card-id span { overflow: hidden; color: hsl(var(--muted-foreground)); font: 400 13.5px/1.35 var(--font-ui); text-overflow: ellipsis; white-space: nowrap; }
.ms-page .ms-card-foot {
  display: flex; align-items: center; justify-content: space-between; gap: 10px; min-height: 48px; margin-top: auto;
  padding: 0 18px; border-top: 1px solid hsl(var(--border));
}
.ms-page .ms-card-price { overflow: hidden; color: hsl(var(--foreground)); font: 600 13.5px/1.2 var(--font-ui); text-overflow: ellipsis; white-space: nowrap; font-variant-numeric: tabular-nums; }
.ms-page .ms-card-price--none { color: hsl(var(--muted-foreground)); font-weight: 400; }
.ms-page .ms-card-overlap {
  display: inline-flex; align-items: center; gap: 4px; flex: 0 1 auto; min-width: 0; max-width: 60%; height: 26px; padding: 0 10px;
  border-radius: var(--radius-pill); background: color-mix(in srgb, var(--tool-accent, hsl(var(--foreground))) 10%, hsl(var(--card)));
  color: hsl(var(--foreground)); font: 600 12px/1 var(--font-ui); white-space: nowrap;
}
.ms-page .ms-card-overlap::before { content: "⇄"; flex: none; font-weight: 400; color: hsl(var(--muted-foreground)); }
.ms-page .ms-card-overlap-name { overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.ms-page .ms-tool.ms-tool-card.ms-tool--selected .ms-card-foot { border-top-color: hsl(var(--foreground) / .25); }
@media (max-width: 640px) {
  .ms-page .ms-card-grid { grid-template-columns: 1fr; gap: 10px; }
  .ms-page .ms-card-top { padding: 14px 14px 12px; }
  .ms-page .ms-card-foot { padding: 0 14px; min-height: 44px; }
}
/* ── Ma stack, vue Par usage (7 oct.) ──
   Présence : une couleur par domaine (teinte unie, pas de dégradé), logos plus
   grands en pile. Compréhension : nom, nombre d'outils (ce que mesure la
   taille), prix ; légende d'une ligne. Fluidité : entrée en cascade à chaque
   niveau, léger agrandissement au survol. */
/* ── Ma stack, vue Par usage en tableau de domaines (7 oct.) ──
   Une carte par domaine : pastille de couleur, nom, nombre d'outils, budget
   d'entrée ; puis ses usages et leurs outils (logo, nom, prix). Couleurs en
   aplats légers, pas de dégradé. Entrée en cascade, survol discret. */
/* Ma stack, coût (7 oct.) : total converti en tête, sélecteur Coût / Outils,
   interrupteur « Je paie » sur les outils freemium. */
.ms-page .ms-size-switch { display: inline-flex; gap: 2px; padding: 2px; border-radius: var(--radius-pill); background: hsl(var(--secondary)); }
.ms-page .ms-size-switch button { height: 28px; padding: 0 12px; border-radius: var(--radius-pill); color: hsl(var(--muted-foreground)); font: 500 12.5px/1 var(--font-ui); }
.ms-page .ms-size-switch button[aria-pressed="true"] { background: hsl(var(--card)); color: hsl(var(--foreground)); font-weight: 600; box-shadow: 0 1px 2px rgba(15, 15, 15, .08); }
.ms-page .ms-size-switch button:focus:not(:focus-visible) { outline: none; }
/* Ma stack, indicateurs (7 oct.) : quatre chiffres lisibles d'un coup d'œil. */
.ms-page .ms-stat--overlaps { border-color: color-mix(in srgb, #E8590C 35%, hsl(var(--border))); background: color-mix(in srgb, #E8590C 6%, hsl(var(--card))); }
.ms-page .ms-stat--overlaps dd { color: color-mix(in srgb, #E8590C 80%, #000); }
/* Ma stack, en-tête façon page Stack (7 oct.) : bandeau, bande de chiffres,
   bouton d'ajout, collage de mes logos (le plus cher au centre). */
.ms-page .ms-hero { margin-bottom: 28px; }
.ms-page .ms-hero h1 { margin-top: 18px; }
.ms-page .ms-hero-stats { margin-top: 28px; }
.ms-page .ms-hero-stats .ms-stat--overlaps dd { color: color-mix(in srgb, #E8590C 82%, #000); }
.ms-page .ms-hero button.sg-cluster-app { padding: 0; border: 0; background: none; cursor: pointer; }
.ms-page .ms-hero--empty { grid-template-columns: minmax(0, 1fr); }
.ms-page .ms-hero-stats .ms-stat--overlaps { padding: 0 16px; border: 0; border-left: 1px solid var(--color-border); border-radius: 0; background: none; }
/* Ma stack, sections numérotées comme les pages Stack (7 oct.). */
.ms-page .ms-section { margin-top: 72px; }
.ms-page .ms-section-lead { max-width: 70ch; margin: -12px 0 20px; color: hsl(var(--muted-foreground)); font: 400 15px/1.55 var(--font-ui); }
.ms-page .ms-budget-link { padding: 0; border: 0; background: none; color: inherit; font: inherit; text-align: left; cursor: pointer; }
.ms-page .ms-budget-link:hover { text-decoration: underline; text-underline-offset: 3px; }
.ms-page .ms-pairs { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 420px), 1fr)); gap: 12px; margin: 0; padding: 0; list-style: none; }
.ms-page .ms-pair { display: grid; gap: 10px; padding: 16px; border: 1px solid hsl(var(--border)); border-radius: 18px; background: hsl(var(--card)); }
.ms-page .ms-pair-tools { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.ms-page .ms-pair-tool { position: relative; display: flex; align-items: center; gap: 10px; min-width: 0; padding: 10px; border-radius: 12px; background: hsl(var(--secondary) / .5); text-align: left; }
.ms-page .ms-pair-tool:hover { background: hsl(var(--secondary)); }
.ms-page .ms-pair-tool > span:not(.ms-pair-sign) { display: grid; min-width: 0; }
.ms-page .ms-pair-tool strong { overflow: hidden; font: 650 14.5px/1.25 var(--font-ui); text-overflow: ellipsis; white-space: nowrap; }
.ms-page .ms-pair-tool small { color: hsl(var(--muted-foreground)); font: 500 12.5px/1.3 var(--font-ui); }
.ms-page .ms-pair-sign { position: absolute; top: 50%; right: -16px; z-index: 1; display: grid; place-items: center; width: 24px; height: 24px; border-radius: 50%; background: hsl(var(--card)); box-shadow: 0 0 0 1px hsl(var(--border)); color: color-mix(in srgb, #E8590C 80%, #000); font: 600 13px/1 var(--font-ui); transform: translateY(-50%); }
.ms-page .ms-pair-why { margin: 0; color: hsl(var(--muted-foreground)); font: 400 13px/1.45 var(--font-ui); }
.ms-page .ms-pair-compare { justify-self: start; display: inline-flex; align-items: center; height: 32px; padding: 0 14px; border-radius: var(--radius-pill); background: hsl(var(--foreground)); color: hsl(var(--background)); font: 600 13px/1 var(--font-ui); text-decoration: none; }
.ms-page .ms-pair-compare:hover { background: hsl(var(--foreground) / .85); }
@media (max-width: 640px) { .ms-page .ms-section { margin-top: 48px; } .ms-page .ms-pair { padding: 12px; } .ms-page .ms-pair-tool { flex-direction: column; align-items: flex-start; gap: 6px; padding: 10px; } .ms-page .ms-pair-sign { right: -16px; } }
.ms-page .ms-stat-link { color: color-mix(in srgb, #E8590C 82%, #000); font: 600 12px/1.3 var(--font-ui); text-decoration: none; }
.ms-page .ms-stat-link:hover { text-decoration: underline; text-underline-offset: 3px; }
.ms-page #ms-overlaps { scroll-margin-top: 24px; }

/* My stack as a dashboard (7 Oct 2026): the hero keeps the whole-stack view
   (four figures, logo cluster), then the usage map as the scope picker, then budget, overlaps and the
   tools of the picked scope. */
.ms-page .ms-tile { min-width: 0; padding: 20px; border-radius: 24px; background: hsl(var(--card)); box-shadow: inset 0 0 0 1px hsl(var(--border)); }
.ms-page .ms-tile-head { display: flex; flex-wrap: wrap; align-items: flex-start; justify-content: space-between; gap: 8px 16px; margin-bottom: 12px; }
.ms-page .ms-tile-head h2 { margin: 0; font: 650 18px/1.25 var(--font-ui); letter-spacing: -.01em; }
.ms-page .ms-tile-head p { max-width: 52ch; margin: 4px 0 0; color: hsl(var(--muted-foreground)); font: 400 13px/1.45 var(--font-ui); }
.ms-page .ms-tile-note { margin: 16px 0 0; color: hsl(var(--muted-foreground)); font: 400 12px/1.5 var(--font-ui); }
.ms-page .ms-tile-more { margin-top: 12px; padding: 0; color: hsl(var(--foreground)); font: 600 13px/1.3 var(--font-ui); text-decoration: underline; text-underline-offset: 3px; }
/* Budget tile: smaller ring, one-column legend. */
.ms-page .ms-budget-tile .sg-budget-viz--share { grid-template-columns: 150px minmax(0, 1fr); gap: 20px; margin-top: 4px; }
.ms-page .ms-budget-tile .sg-donut { width: 150px; height: 150px; }
.ms-page .ms-budget-tile .sg-storage-legend { grid-template-columns: 1fr; gap: 8px; }
.ms-page .ms-budget-tile .sg-budget-name, .ms-page .ms-budget-tile .sg-budget-value { font-size: 13.5px; }
.ms-page .ms-budget-rest .sg-budget-name, .ms-page .ms-budget-rest .sg-budget-value { color: hsl(var(--muted-foreground)); font-weight: 500; }
/* Overlaps tile: pairs one per row. */
.ms-page .ms-pairs-panel .ms-pairs { grid-template-columns: 1fr; gap: 10px; }
.ms-page .ms-pairs-panel .ms-pair { padding: 12px; border-radius: 16px; }
.ms-page .ms-pair-foot { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.ms-page .ms-pair-foot .ms-pair-why { min-width: 0; }
.ms-page .ms-pair-foot .ms-pair-compare { flex-shrink: 0; }
.ms-page #ms-budget { scroll-margin-top: 24px; }
/* Tools tile. */
@media (max-width: 640px) {
  .ms-page .ms-tile { padding: 14px; border-radius: 20px; }
  .ms-page .ms-budget-tile .sg-budget-viz--share { grid-template-columns: 1fr; justify-items: center; }
  .ms-page .ms-budget-tile .sg-storage-legend { width: 100%; }
}
/* Design pass (7 Oct 2026): back to the stack pages' language. Editorial
   section headings, no frame around the map or the tools, budget and
   overlaps as soft Apple-style widgets (no hairline, no box in a box). */
.ms-page .ms-tools-section { margin-top: 64px; }
.ms-page .ms-section-row { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 12px 24px; margin-bottom: 28px; }
.ms-page .ms-section-row .sg-section-heading { margin: 0; }
.ms-page .ms-tile { padding: 28px; border-radius: 28px; background: var(--color-surface-soft); box-shadow: none; }
.ms-page .ms-tile-head { margin-bottom: 20px; }
.ms-page .ms-tile-head h2 { color: var(--color-text-muted); font: 600 11px/1.3 var(--font-ui); letter-spacing: .08em; text-transform: uppercase; }
.ms-page .ms-tile-head p { margin-top: 6px; color: hsl(var(--foreground)); font: 600 19px/1.3 var(--font-brand); letter-spacing: -.015em; }
.ms-page .ms-tile .ms-size-switch { background: hsl(var(--card)); }
.ms-page .ms-tile .ms-size-switch button[aria-pressed="true"] { background: hsl(var(--foreground)); color: hsl(var(--background)); box-shadow: none; }
.ms-page .ms-budget-tile .sg-budget-viz--share { grid-template-columns: 160px minmax(0, 1fr); gap: 24px; }
.ms-page .ms-budget-tile .sg-donut { width: 160px; height: 160px; }
/* Overlaps: an inset grouped list, one white row per pair. */
.ms-page .ms-pairs-panel .ms-pairs { gap: 8px; }
.ms-page .ms-pairs-panel .ms-pair { gap: 8px; padding: 14px 16px; border: 0; border-radius: 18px; background: hsl(var(--card)); transition: transform 220ms cubic-bezier(.2, .8, .2, 1); }
.ms-page .ms-pairs-panel .ms-pair:hover { transform: translateY(-2px); }
.ms-page .ms-pairs-panel .ms-pair-tool { padding: 0; background: none; }
.ms-page .ms-pairs-panel .ms-pair-tool:hover { background: none; }
.ms-page .ms-pairs-panel .ms-pair-tool:hover strong { text-decoration: underline; text-underline-offset: 3px; }
.ms-page .ms-pairs-panel .ms-pair-sign { right: -4px; box-shadow: none; background: color-mix(in srgb, #E8590C 12%, hsl(var(--card))); }
.ms-page .ms-pairs-panel .ms-pair-tool:last-child { padding-left: 16px; }
.ms-page .ms-pairs-panel .ms-pair-compare { height: 30px; padding: 0 12px; background: hsl(var(--secondary)); color: hsl(var(--foreground)); }
.ms-page .ms-pairs-panel .ms-pair-compare:hover { background: hsl(var(--foreground)); color: hsl(var(--background)); }
.ms-page .ms-tile-more { margin-top: 14px; text-decoration: none; }
.ms-page .ms-tile-more::after { content: " →"; }
/* Tools: plain section, the cards are the only boxes. */
.ms-page .ms-tools-section .ms-domain-filters { margin: -8px 0 20px; }
@media (max-width: 640px) {
  .ms-page .ms-tools-section { margin-top: 48px; }
  .ms-page .ms-tile { padding: 18px; border-radius: 24px; }
  .ms-page .ms-budget-tile .sg-budget-viz--share { grid-template-columns: 1fr; }
}
/* Budget by area: no logo column, and an area is a way into the page filter. */
.ms-page .ms-budget-tile .sg-storage-legend li.ms-budget-area { grid-template-columns: 8px minmax(0, 1fr) auto; }
.ms-page .ms-budget-tile .sg-storage-legend li.ms-budget-area .sg-storage-dot { width: 10px; height: 10px; }
.ms-page .ms-budget-tile .sg-donut-seg { cursor: pointer; }
/* Freemium widget: full width under budget and overlaps, an iOS-style list of
   switches, with what the declarations add to the budget. */
.ms-freemium-list { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 300px), 1fr)); gap: 8px; margin: 0; padding: 0; list-style: none; }
.ms-freemium-list li { display: flex; align-items: center; gap: 12px; padding: 10px 12px 10px 14px; border-radius: 18px; background: hsl(var(--card)); transition: box-shadow 220ms ease; }
.ms-freemium-list li.is-on { box-shadow: inset 0 0 0 1.5px color-mix(in srgb, #0E9F6E 45%, transparent); }
.ms-freemium-tool { display: flex; flex: 1; align-items: center; gap: 12px; min-width: 0; padding: 0; text-align: left; }
.ms-freemium-tool > span { display: grid; min-width: 0; }
.ms-freemium-tool strong { overflow: hidden; font: 650 14.5px/1.3 var(--font-ui); text-overflow: ellipsis; white-space: nowrap; }
.ms-freemium-tool small { overflow: hidden; color: hsl(var(--muted-foreground)); font: 500 12.5px/1.35 var(--font-ui); text-overflow: ellipsis; white-space: nowrap; font-variant-numeric: tabular-nums; }
.ms-switch { display: inline-flex; flex-shrink: 0; align-items: center; gap: 8px; padding: 4px 0; color: hsl(var(--muted-foreground)); font: 600 12.5px/1 var(--font-ui); }
.ms-switch[aria-checked="true"] { color: color-mix(in srgb, #0E9F6E 80%, #000); }
.ms-switch-track { position: relative; width: 42px; height: 26px; border-radius: 13px; background: hsl(var(--muted-foreground) / .28); transition: background-color 220ms ease; }
.ms-switch-track > span { position: absolute; top: 3px; left: 3px; width: 20px; height: 20px; border-radius: 50%; background: #fff; box-shadow: 0 1px 3px rgba(15, 15, 15, .2); transition: transform 260ms cubic-bezier(.34, 1.56, .64, 1); }
.ms-switch[aria-checked="true"] .ms-switch-track { background: #0E9F6E; }
.ms-switch[aria-checked="true"] .ms-switch-track > span { transform: translateX(16px); }
.ms-switch:focus-visible { outline: none; }
.ms-switch:focus-visible .ms-switch-track { outline: 2px solid hsl(var(--ring)); outline-offset: 2px; }
/* Budget: the freemium count is a way to the widget, not a fold. */
@media (prefers-reduced-motion: reduce) { .ms-switch-track > span { transition: none; } }
/* Visit order (7 Oct 2026): overlaps, then budget with freemium beside it,
   then the tools. */
.ms-page .ms-overlaps-section, .ms-page .ms-budget-section { margin-top: 64px; }
.ms-page .ms-pairs-panel { padding: 12px; border-radius: 28px; background: var(--color-surface-soft); }
.ms-page .ms-pairs-panel .ms-pairs { grid-template-columns: repeat(auto-fill, minmax(min(100%, 380px), 1fr)); gap: 8px; }
.ms-page .ms-pairs-panel .ms-tile-more { margin: 12px 8px 4px; }
