  .tt-footer .tt-footer-lang > * { min-width: 48px; height: 36px; }
  .tt-footer .tt-footer-rail { flex-direction: column; align-items: flex-start; gap: 16px; }
  .tt-footer .tt-footer-legal { flex-direction: row; justify-content: flex-start; align-items: center; text-align: left; gap: 8px 16px; }
}

/* Footer twist: the tagline acted out. A pile of five same-job tools, trimmed
   to one when the footer comes into view; hover reopens the pile. */
.tt-trim { --ease: cubic-bezier(.34, 1.3, .64, 1); display: inline-flex; vertical-align: middle; margin: -6px 0 0 18px; }
.tt-trim-pile { position: relative; width: 84px; height: 52px; }
.tt-trim-tile { position: absolute; left: 0; top: 6px; display: block; width: 40px; height: 40px; border-radius: var(--radius-stack-logo-mobile); background: var(--tt-footer-card); box-shadow: 0 0 0 1px rgba(15, 15, 15, .06), 0 2px 6px rgba(15, 15, 15, .08); overflow: hidden;
  transform: translate(calc(var(--i) * 10px), calc(var(--i) * -1.5px)) rotate(var(--r));
  transition: transform 380ms var(--ease) calc(var(--i) * 25ms), opacity 140ms cubic-bezier(0, 0, .2, 1) calc(var(--i) * 25ms); z-index: var(--i); }
/* Each tile's place in the pile: its index and tilt (static, so in CSS
   rather than inline styles). */
.tt-trim-tile:nth-child(1) { --i: 0; --r: -7deg; }
.tt-trim-tile:nth-child(2) { --i: 1; --r: 5deg; }
.tt-trim-tile:nth-child(3) { --i: 2; --r: -3deg; }
.tt-trim-tile:nth-child(4) { --i: 3; --r: 8deg; }
.tt-trim-tile:nth-child(5) { --i: 4; --r: -5deg; }
.tt-trim-tile > * { width: 100% !important; height: 100% !important; border-radius: inherit; }
.tt-trim[data-trimmed] .tt-trim-tile { transform: translate(22px, 0) rotate(0deg) scale(.6); opacity: 0; transition: transform 380ms var(--ease) calc((4 - var(--i)) * 25ms), opacity 220ms ease calc(140ms + (4 - var(--i)) * 25ms); }
/* The one kept: a neutral white tile with an ink check, never a brand, and
   never a second black block next to the primary button. */
.tt-trim-one { position: absolute; left: 22px; top: 6px; z-index: 10; display: grid; place-items: center; width: 40px; height: 40px; border-radius: var(--radius-stack-logo-mobile); background: var(--tt-footer-card); color: var(--tt-footer-ink); box-shadow: 0 0 0 1px rgba(15, 15, 15, .06), 0 4px 14px rgba(15, 15, 15, .10); opacity: 0; transform: scale(.7) rotate(-6deg); transition: transform 380ms var(--ease), opacity 160ms ease; }
.tt-trim-one path { stroke-dasharray: 16; stroke-dashoffset: 16; transition: stroke-dashoffset 240ms ease; }
.tt-trim[data-trimmed] .tt-trim-one { opacity: 1; transform: none; transition-delay: 160ms; }
.tt-trim[data-trimmed] .tt-trim-one path { stroke-dashoffset: 0; transition-delay: 340ms; }
@media (prefers-reduced-motion: reduce) { .tt-trim *, .tt-trim *::before { transition: none !important; } }
@media (max-width: 640px) { .tt-trim { margin-left: 12px; transform: scale(.85); transform-origin: left center; } }

/* Apple reference (8 Oct 2026): the footer closes the page on its own soft
   grey surface, opens with numbered fine print above a hairline, and ends on
   a legal line whose links are split by thin vertical rules. */
.tt-footer {
  /* Three tones, as on apple.com: ink for titles and figures, a dark grey
     for links and copy, the palette's metadata grey for fine print. The
     site-wide --color-muted equals the text colour, so the footer sets its
     own (design review, 8 Oct 2026). #6F6F68 on #F6F5F4 = 4.7:1, AA. */
  --tt-footer-ink: #0F0F0F;
  --tt-footer-text: #1D1D1F;
  --tt-footer-link: var(--color-text-secondary, #424245);
  --tt-footer-muted: var(--color-text-meta, #6F6F68);
  --tt-footer-card: #FFFFFF;
  --tt-footer-track: #EDEBE9;
  --tt-footer-alert: #C2410C;
  --tt-footer-surface: #F6F5F4; --tt-footer-border: rgba(15, 15, 15, .09); background: var(--tt-footer-surface); padding-top: clamp(64px, 6vw, 88px); }
.tt-footer .tt-footer-legal { gap: 6px 0; }
.tt-footer .tt-footer-legal > * + *::before { content: ""; display: inline-block; width: 1px; height: 11px; margin: 0 10px; vertical-align: -1px; background: var(--tt-footer-border); }
.tt-footer .tt-footer-legal > span:first-child { margin-right: 14px; }
.tt-footer .tt-footer-legal > span:first-child + *::before { display: none; }
.tt-footer .tt-footer-lang { background: rgba(255, 255, 255, .6); }
@media (max-width: 640px) {
    .tt-footer .tt-footer-legal > span:first-child { flex-basis: 100%; margin: 0 0 4px; }
  .tt-footer .tt-footer-legal > *:nth-child(2)::before { display: none; }
  .tt-footer .tt-footer-stack-total { font-size: 28px; }
}
.tt-footer .tt-footer-stack-approx { margin-right: 6px; font-weight: 400; color: var(--tt-footer-muted); }
.tt-footer .tt-footer-intro { color: var(--tt-footer-link); }
@media (max-width: 640px) { .tt-footer .tt-footer-col a { display: flex; align-items: center; min-height: 24px; } .tt-footer .tt-footer-col { gap: 6px; } }
.tt-footer .tt-footer-tagline-end { white-space: nowrap; }

/* Home, design review (8 Oct 2026).
   Works with: the same filter language as Ma stack, no track, the active
   software as a dark pill. */
/* Card titles share one line whether or not a category follows. */
.home-v2 .v2-rail-item .tce-identity-link { align-items: flex-start; }
/* "See all" links and the footer legal links: at least 24px to tap. */
.home-v2 .v2-section-link, .tt-footer .tt-footer-legal a, .tt-footer .tt-footer-linkbutton { display: inline-flex; align-items: center; min-height: 24px; }
@media (max-width: 640px) {
  /* A shorter phone page: two picks per universe (scoped to the universes:
     the watchlist reuses the same row markup and keeps its six tools). */
  .home-v2 .v2-shelf-cell .v2-shelf-picks > li:nth-child(n+3) { display: none; }
}

/* ── Home, chapter 1 (8 Oct 2026): the stacks become four large white cards
   right after the hero, on the page's white (no grey band: Michael). The iOS folder
   grows and leads each card; the copy sits under it. ── */
.home-v2 .sgs-root { margin-top: 0; padding: 72px 0 0; background: none; }
.home-v2 .sgs-list { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px; column-gap: 16px; }
.home-v2 .sgs-list > li { border-top: 0; display: flex; }
.home-v2 .sgs-item { flex: 1; flex-direction: column; align-items: flex-start; gap: 22px; margin: 0; padding: 24px 22px 26px; background: var(--color-surface); box-shadow: 0 0 0 1px var(--color-border); transition: box-shadow 260ms cubic-bezier(.25, 1, .5, 1), transform 260ms cubic-bezier(.25, 1, .5, 1); }
.home-v2 .sgs-item:hover { background: var(--color-surface); transform: translateY(-3px); box-shadow: 0 0 0 1px var(--color-border), 0 14px 34px rgba(15, 15, 15, .08); }
.home-v2 .sgs-item:active { transform: translateY(-1px) scale(.99); }
.home-v2 .sgs-folder { width: 112px; height: 112px; grid-template-columns: repeat(2, 38px); grid-template-rows: repeat(2, 38px); gap: 10px; background: var(--color-bg-warm); box-shadow: none; }
.home-v2 .sgs-item:hover .sgs-folder { background: var(--color-surface-warm); transform: none; }
.home-v2 .sgs-folder-logo { width: 38px !important; height: 38px !important; min-width: 38px !important; min-height: 38px !important; box-shadow: 0 1px 2px rgba(15, 15, 15, .08) !important; }
.home-v2 .sgs-item-copy { gap: 6px; }
.home-v2 .sgs-item-title { font-size: 19px; line-height: 1.2; }
.home-v2 .sgs-item-subtitle { -webkit-line-clamp: 3; }
@media (max-width: 1100px) { .home-v2 .sgs-list { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 640px) {
  .home-v2 .sgs-root { padding: 48px 0 0; }
  /* position: relative keeps the cards' sr-only names inside the scroller;
     without it they widened the phone page to 909px (a11y audit). */
  .home-v2 .sgs-list { position: relative; display: flex; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; margin-inline: calc(-1 * var(--v2-grid-gutter)); padding-inline: var(--v2-grid-gutter); scroll-padding-inline: var(--v2-grid-gutter); }
  .home-v2 .sgs-list::-webkit-scrollbar { display: none; }
  .home-v2 .sgs-list > li { flex: 0 0 78%; scroll-snap-align: start; }
  .home-v2 .sgs-folder { width: 96px; height: 96px; border-radius: var(--radius-2xl); grid-template-columns: repeat(2, 32px); grid-template-rows: repeat(2, 32px); }
  .home-v2 .sgs-folder-logo { width: 32px !important; height: 32px !important; min-width: 32px !important; min-height: 32px !important; }
}
/* Watchlist: three columns of editorial rows, no share images. */
.home-v2 .v2-watch-list { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); column-gap: 40px; }
@media (max-width: 1100px) { .home-v2 .v2-watch-list { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 640px) { .home-v2 .v2-watch-list { grid-template-columns: 1fr; } }
/* Fewer separators (Michael, 8 Oct 2026): the home breathes through space,
   not hairlines. No line above each universe, none between its tools. */
.home-v2 .v2-shelf-cell { border-top: 0; padding-top: 0; }
.home-v2 .v2-shelf-pick-copy,
.home-v2 .v2-shelf-picks li .v2-shelf-pick-copy { border-bottom-color: transparent; }
.home-v2 .v2-shelf-grid { row-gap: 56px; }

/* ── Home type and rhythm system (design review, 8 Oct 2026) ──────────────
   One scale instead of ~20 sizes, three weights (400 / 500 / 600, the hero's
   480 display stays), three text tones, one section gap, four radii.
     display 56 (hero) · feature 32 (lead guide) · section 28 ·
     card title 18 · item 15 · body 15 · lead 16 · meta 13 · kicker 11
   Tones: ink #1D1D1F (titles), text #424245 (body), meta #6F6F68.
   Radii: 12 tiles and rows · 20 cards and media · 24 the hero band ·
   9999 pills. Section gap: 72 desktop, 48 phone. */
.home-v2 {
  --h-ink: #1D1D1F;
  --h-text: var(--color-text-secondary, #424245);
  --h-meta: var(--color-text-meta, #6F6F68);
  --h-section: clamp(22px, 2.2vw, 28px);
  --h-gap: 72px;
  --h-radius-tile: 12px;
  --h-radius-card: 20px;
  --h-radius-hero: 24px;
  /* One column gap for every grid on the page (stacks, rails, guides). */
  --v2-grid-gap: 16px;
  --v2-head-content-gap: 24px;
}
@media (max-width: 640px) { .home-v2 { --h-gap: 48px; } }

/* Comparative review, 9 Oct 2026 (tokens only). */
/* A rail with four items or fewer fills the row exactly, edge to edge. */
.home-v2 .v2-rail-track:not(:has(> .v2-rail-item:nth-child(5))) > .v2-rail-item { flex-basis: calc((100% - 3 * var(--v2-grid-gap)) / 4); }
@media (max-width: 1023px) {
  .home-v2 .v2-rail-track:not(:has(> .v2-rail-item:nth-child(5))) > .v2-rail-item { flex-basis: calc((100% - var(--v2-grid-gap)) / 2.3); }
}
/* Phones: the Compatible avec tabs and rail bleed to the screen edge, like
   the stacks rail, instead of stopping 20px short. */
/* Stack cards: copy is not cut on the 4-up row. */
@media (min-width: 1101px) { .home-v2 .sgs-item-subtitle { -webkit-line-clamp: 4; } }
.home-v2 .sgs-item-subtitle, .home-v2 .v2-shelf-pick-take { text-wrap: pretty; }
/* Heading to content: 24, title to lead: 8. */
.home-v2 .sgs-lead { margin-top: 8px; }
/* "Freemium" and price badges on covers: on the type scale. */
.home-v2 .tce-cover-price { font: 600 11px/1 var(--font-ui); color: var(--color-text); }

/* Section titles: one size, clearly above the card titles. */
.home-v2 .v2-section-title { font: 600 var(--h-section)/1.15 var(--font-ui); letter-spacing: -.025em; color: var(--h-ink); }
/* Card and group titles: 18 / 600. */
.home-v2 .v2-shelf-cell-name,
.home-v2 .sgs-item-title,
.home-v2 .tce-name,
.home-v2 .v2-today-title { font: 600 18px/1.25 var(--font-ui); letter-spacing: -.015em; color: var(--h-ink); }
/* The lead guide title never outranks its section title. */
.home-v2 .v2-today-card--feature .v2-today-title { font-size: clamp(22px, 2.3vw, 32px); line-height: 1.12; letter-spacing: -.02em; max-width: 24ch; }
/* Items and body. */
.home-v2 .v2-shelf-pick-name { font: 600 15px/1.35 var(--font-ui); letter-spacing: -.01em; color: var(--h-ink); }
.home-v2 .v2-shelf-pick-take,
.home-v2 .sgs-item-subtitle,
.home-v2 .sgs-lead { font: 400 15px/1.45 var(--font-ui); letter-spacing: -.005em; color: var(--h-text); }
.home-v2 .hv2-subtitle { font-size: 16px; line-height: 1.5; }
/* Meta: 13 / 500, grey. */
.home-v2 .v2-today-date,
.home-v2 .tce-category { font: 500 13px/1.4 var(--font-ui); letter-spacing: 0; color: var(--h-meta); }
/* Kickers: 11 / 600, uppercase, grey. */
.home-v2 .hv2-eyebrow,
.home-v2 .sgs-item-objective,
.home-v2 .v2-today-eyebrow { font: 600 11px/1.4 var(--font-ui); letter-spacing: .06em; text-transform: uppercase; color: var(--h-meta); }
/* Actions: 14 / 600 everywhere. */
.home-v2 .tt-section-action { font-size: 14px; font-weight: 600; }

/* One section gap. */
.home-v2 .hv2-root { padding-bottom: 0; }
.home-v2 .sgs-root { padding-top: var(--h-gap); }
.home-v2 .v2-catalog { padding-top: var(--h-gap); }
.home-v2 .v2-catalog-section + .v2-catalog-section { margin-top: var(--h-gap); }

/* Radii. */
.home-v2 .hv2-band { border-radius: var(--h-radius-hero); }
.home-v2 .sgs-item,
.home-v2 .v2-today-media,
.home-v2 .tc-image,
.home-v2 .tce-primary-link { border-radius: var(--h-radius-card); }
.home-v2 .sgs-folder { border-radius: var(--radius-2xl); }
.home-v2 .v2-shelf-pick,
.home-v2 .v2-shelf-pick-logo,
.home-v2 .tce-logo,
.home-v2 .sgs-folder-logo { border-radius: var(--h-radius-tile) !important; }

/* Footer tagline echoes the hero face instead of a second display face. */
.tt-footer .tt-footer-tagline { font: 480 clamp(30px, 3vw, 40px)/1.05 var(--font-ui); letter-spacing: -.045em; }
/* Footer on the same scale: titles 13/600, links 13/400, legal 12/400,
   language 12/600, badge label 12/500. */
.tt-footer .tt-footer-col-label { font: 600 13px/1.3 var(--font-ui); }
.tt-footer .tt-footer-col a { font: 400 13px/1.35 var(--font-ui); }
.tt-footer .tt-footer-lang { font: 600 12px/1 var(--font-ui); letter-spacing: .02em; }
.tt-footer .tt-footer-partners-label { font: 500 12px/1.3 var(--font-ui); }
/* The search block now sits right under the hero, on its own. */

/* ── Accessibility and motion fixes (design review, 8 Oct 2026) ── */
/* Focus rings where the audit found none or a faint one. */
.asv2-sidebar-resizer:focus-visible { outline: 2px solid var(--color-text); outline-offset: 2px; }
.pin-tool-button:focus-visible { box-shadow: 0 0 0 2px var(--color-surface), 0 0 0 4px var(--color-text); }
.analytics-consent__copy a { display: inline-flex; align-items: center; min-height: 24px; }
/* Stack folder: the apps drift apart with transform, not by animating gap. */
.home-v2 .sgs-folder { transition: background 200ms ease-out; }
.home-v2 .sgs-item:hover .sgs-folder { gap: 10px; }
.home-v2 .sgs-folder-app { transition: transform 260ms cubic-bezier(.2, .8, .2, 1); }
.home-v2 .sgs-item:hover .sgs-folder-app:nth-child(1) { transform: translate(-1.5px, -1.5px); }
.home-v2 .sgs-item:hover .sgs-folder-app:nth-child(2) { transform: translate(1.5px, -1.5px); }
.home-v2 .sgs-item:hover .sgs-folder-app:nth-child(3) { transform: translate(-1.5px, 1.5px); }
.home-v2 .sgs-item:hover .sgs-folder-app:nth-child(4) { transform: translate(1.5px, 1.5px); }
/* Footer gauge: 500ms, started when the card is seen. */
.tt-footer .tt-footer-stack-gauge > span { animation-duration: 500ms; animation-delay: 0ms; animation-play-state: paused; }
.tt-footer .tt-footer-stack[data-seen] .tt-footer-stack-gauge > span { animation-play-state: running; }
/* Trim: the tiles converge before they fade, so the fold reads. */
@media (prefers-reduced-motion: reduce) {
  .home-v2 .sgs-folder-app, .home-v2 .sgs-item:hover .sgs-folder-app,
  .home-v2 .sgs-item:hover .sgs-folder-app:nth-child(n) { transition: none; transform: none; }
  .home-v2 .sgs-item, .home-v2 .sgs-item:hover, .home-v2 .hv2-cta, .home-v2 .hv2-cta-secondary, .tt-footer .tt-footer-badge { transition: none; transform: none; }
  .tce-hover-actions, .tt-section-action svg, .tt-footer .tt-footer-stack, .tt-footer .tt-footer-stack-logos > *, .tt-footer .tt-footer-stack-cta svg { transition: none !important; transform: none !important; }
  .tt-footer .tt-footer-stack-gauge > span { animation: none; }
}
/* Search block on the stack cards' 4-column grid (Michael: "ça flotte"):
   title over columns 1-2, the field over columns 3-4, one line, edges on
   the cards below. Stacked on phones. */
/* <main> inside the shell's scroll container: no focus ring when the skip
   link sends focus to it. */
.asv2-main { display: block; outline: none; }
/* Phone and tablet: the badge strip must scroll, not widen its column (the
   base rule's flex-wrap made the line max-content wide, so 14 of 18 badges
   were clipped off-screen; a11y audit, 9 Oct 2026). */
@media (max-width: 1100px) {
  .tt-footer .tt-footer-partners { flex-wrap: nowrap; min-width: 0; }
  .tt-footer .tt-footer-badges { min-width: 0; max-width: 100%; }
}

/* Focus: one ring everywhere that has none of its own (zero specificity, so
   any component ring still wins; a11y review, 9 Oct 2026). */
:where(a, button, [role="tab"], summary):focus-visible { outline: 2px solid var(--color-text); outline-offset: 2px; }
/* While the cookie banner shows, scrolling to a focused element keeps it
   above the banner (WCAG 2.4.11). */
html, .asv2-content { scroll-padding-bottom: var(--consent-h, 0px); }
/* The page ends into the footer with a little more air than between sections. */
.asv2-main:has(.home-v2) + .tt-footer { --tt-footer-margin-top: calc(var(--h-gap, 72px) * 1.5); }
@media (max-width: 640px) { .asv2-main:has(.home-v2) + .tt-footer { --tt-footer-margin-top: 72px; } }

/* ── Lequel garder ? (home, 9 Oct 2026) ──────────────────────────────────
   Two tools face to face on a soft stage, tilted away from each other and
   joined by Ma stack's swap badge; on hover they straighten and close in,
   like a duel about to be settled. Title and decision line below, on the
   home type scale. Tokens only. */
.hc-card { display: flex; flex-direction: column; color: inherit; text-decoration: none; border-radius: var(--h-radius-card, 20px); }
.hc-card:focus-visible { outline: 2px solid var(--color-text); outline-offset: 4px; }
.hc-duel { position: relative; display: grid; place-items: center; aspect-ratio: 16 / 10; border-radius: var(--h-radius-card, 20px); background: var(--color-surface-soft); overflow: hidden; }
.hc-icon { position: absolute; left: 50%; top: 50%; width: 72px; height: 72px; margin: -36px 0 0 -36px; border-radius: var(--radius-stack-card-mobile); background: var(--color-surface); box-shadow: 0 1px 2px rgba(15, 15, 15, .06), 0 10px 24px rgba(15, 15, 15, .10); overflow: hidden; transition: transform 320ms cubic-bezier(.34, 1.3, .64, 1); }
.hc-icon > * { width: 100% !important; height: 100% !important; min-width: 0 !important; min-height: 0 !important; border-radius: inherit !important; box-shadow: none !important; }
.hc-icon--a { transform: translateX(-64%) rotate(-7deg); }
.hc-icon--b { transform: translateX(64%) rotate(6deg); }
.hc-swap { position: relative; z-index: 2; display: grid; place-items: center; width: 28px; height: 28px; border-radius: var(--radius-circle); background: var(--color-text); color: var(--color-surface); font: 600 13px/1 var(--font-ui); box-shadow: 0 0 0 3px var(--color-surface-soft); transition: transform 260ms cubic-bezier(.34, 1.4, .64, 1); }
.hc-card:hover .hc-icon--a, .hc-card:focus-visible .hc-icon--a { transform: translateX(-56%) rotate(0deg); }
.hc-card:hover .hc-icon--b, .hc-card:focus-visible .hc-icon--b { transform: translateX(56%) rotate(0deg); }
.hc-card:hover .hc-swap { transform: scale(1.1); }
.hc-card:active .hc-duel { transform: scale(.99); }
.hc-title { margin-top: 14px; font: 600 18px/1.25 var(--font-ui); letter-spacing: -.015em; color: var(--color-text); }
.hc-summary { display: -webkit-box; margin-top: 6px; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 3; font: 400 15px/1.45 var(--font-ui); color: var(--color-text-secondary); text-wrap: pretty; }
@media (max-width: 640px) { .hc-icon { width: 60px; height: 60px; margin: -30px 0 0 -30px; } }
@media (prefers-reduced-motion: reduce) {
  .hc-icon, .hc-swap { transition: none; }
  .hc-card:hover .hc-icon--a, .hc-card:focus-visible .hc-icon--a { transform: translateX(-64%) rotate(-7deg); }
  .hc-card:hover .hc-icon--b, .hc-card:focus-visible .hc-icon--b { transform: translateX(64%) rotate(6deg); }
  .hc-card:hover .hc-swap { transform: none; }
}
